SET FOREIGN_KEY_CHECKS=0;
START TRANSACTION;
CREATE TABLE `users` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `username` VARCHAR(50) UNIQUE, `email` VARCHAR(100) UNIQUE, `phone` VARCHAR(20) UNIQUE, `password_hash` VARCHAR(255) NOT NULL, `avatar` VARCHAR(500), `company_name` VARCHAR(100), `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `role` TEXT DEFAULT 'user', `subscription_status` TEXT DEFAULT 'inactive', `subscription_end_date` DATETIME, `email_verified` TINYINT(1) DEFAULT 0, `phone_verified` TINYINT(1) DEFAULT 0, `last_login_at` DATETIME, `login_count` INTEGER DEFAULT 0, `is_active` TINYINT(1) DEFAULT 1, `real_name` VARCHAR(100), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `resumes` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `file_name` VARCHAR(255) NOT NULL, `file_size` INTEGER NOT NULL, `file_type` VARCHAR(50) NOT NULL, `file_path` VARCHAR(500) NOT NULL, `upload_date` DATETIME, `parsed_data` JSON, `raw_text` TEXT, `status` TEXT DEFAULT 'uploaded', `tags` JSON DEFAULT '[]', `analysis_count` INTEGER DEFAULT 0, `last_analysis_date` DATETIME, `is_public` TINYINT(1) DEFAULT 0, `download_count` INTEGER DEFAULT 0, `source` VARCHAR(50) DEFAULT 'manual', `is_talent_pool` TINYINT(1) DEFAULT 0, `name` VARCHAR(100), `phone` VARCHAR(50), `email` VARCHAR(100), `location` VARCHAR(200), `job_title` VARCHAR(100), `experience_years` INTEGER, `highest_education` VARCHAR(50), `job_status` VARCHAR(50), `expected_salary` VARCHAR(100), `work_experience` JSON, `education` JSON, `skills` JSON, `summary` TEXT, `projects` JSON, `recruitment_status` TEXT DEFAULT '投递', `auto_rejected` TINYINT(1) DEFAULT 0, `rejection_reason` VARCHAR(255), `score` INTEGER DEFAULT 0, `updated_at` DATETIME NOT NULL, `avatar` VARCHAR(255));
CREATE TABLE `analysis_results` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `resume_id` INTEGER NOT NULL REFERENCES `resumes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `job_id` INTEGER REFERENCES `jobs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `analysis_date` DATETIME, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `type` TEXT DEFAULT 'single', `overall_score` INTEGER NOT NULL, `dimensions` JSON DEFAULT '{}', `suggestions` JSON DEFAULT '[]', `strengths` JSON DEFAULT '[]', `weaknesses` JSON DEFAULT '[]', `summary` TEXT, `hiring_advice` TEXT, `target_job` JSON DEFAULT NULL, `detailed_analysis` JSON DEFAULT '{}', `ai_provider` VARCHAR(50), `ai_model` VARCHAR(100), `processing_time` INTEGER, `is_favorite` TINYINT(1) DEFAULT 0, `notes` TEXT);
CREATE TABLE `jobs` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `title` VARCHAR(200) NOT NULL, `description` TEXT, `requirements` TEXT, `responsibilities` TEXT, `salary_range` VARCHAR(100), `location` VARCHAR(200), `experience_required` VARCHAR(100), `education_required` VARCHAR(100), `job_type` TEXT DEFAULT 'full_time', `department` VARCHAR(100), `status` TEXT DEFAULT 'draft', `urgency` TEXT DEFAULT 'medium', `positions_count` INTEGER DEFAULT 1, `view_count` INTEGER DEFAULT 0, `application_count` INTEGER DEFAULT 0, `tags` JSON DEFAULT '[]', `expiry_date` DATETIME, `is_featured` TINYINT(1) DEFAULT 0, `enable_auto_screening` TINYINT(1) DEFAULT 0, `auto_reject_score` INTEGER DEFAULT 60, `notify_high_score` TINYINT(1) DEFAULT 0, `high_score_threshold` INTEGER DEFAULT 85, `weight_preference` TEXT DEFAULT 'balanced', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, enable_deep_analysis INTEGER DEFAULT 0, deep_analysis_status TEXT DEFAULT 'none', deep_analysis_trigger TEXT DEFAULT 'manual');
CREATE TABLE `orders` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `plan` TEXT NOT NULL, `amount` DECIMAL(10,2) NOT NULL, `currency` VARCHAR(3) DEFAULT 'CNY', `provider` TEXT NOT NULL, `out_trade_no` VARCHAR(64) UNIQUE, `transaction_id` VARCHAR(64), `status` TEXT DEFAULT 'pending', `payment_url` VARCHAR(500), `code_url` VARCHAR(500), `paid_at` DATETIME, `expires_at` DATETIME, `refund_amount` DECIMAL(10,2) DEFAULT 0, `refund_reason` VARCHAR(500), `metadata` JSON DEFAULT '{}', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `invoices` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `invoiceNo` VARCHAR(64) NOT NULL UNIQUE, `orderId` INTEGER NOT NULL REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `userId` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `amount` DECIMAL(10,2) NOT NULL, `taxAmount` DECIMAL(10,2) NOT NULL, `totalAmount` DECIMAL(10,2) NOT NULL, `planType` VARCHAR(50), `paymentMethod` VARCHAR(50), `transactionId` VARCHAR(64), `status` TEXT DEFAULT 'issued', `issuedAt` DATETIME, `buyerName` VARCHAR(200) NOT NULL, `buyerTaxNumber` VARCHAR(50), `buyerAddress` VARCHAR(500), `buyerPhone` VARCHAR(50), `buyerBank` VARCHAR(200), `invoiceDate` VARCHAR(20), `serviceDescription` VARCHAR(500), `servicePeriod` VARCHAR(100), `originalInvoiceId` INTEGER, `redReason` VARCHAR(500), `redInvoiceId` INTEGER, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `recruitment_processes` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `company_name` VARCHAR(200), `name` VARCHAR(100) NOT NULL, `steps` JSON NOT NULL DEFAULT '[]', `is_default` TINYINT(1) DEFAULT 0, `status` TEXT DEFAULT 'active', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `resume_jobs` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `resume_id` INTEGER NOT NULL REFERENCES `resumes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `job_id` INTEGER NOT NULL REFERENCES `jobs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `status` TEXT DEFAULT 'applied', `applied_at` DATETIME, `notes` TEXT, `match_score` INTEGER, `recruiter_notes` TEXT, `updated_at` DATETIME NOT NULL, deep_analysis_status TEXT DEFAULT 'none', deep_analysis_trigger TEXT DEFAULT 'manual', deep_analysis_retry_count INTEGER DEFAULT 0, deep_analysis_error TEXT, UNIQUE (`resume_id`, `job_id`));
CREATE TABLE `user_activities` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `action` VARCHAR(100) NOT NULL, `resource_type` VARCHAR(50), `resource_id` INTEGER, `details` JSON, `ip_address` VARCHAR(45), `user_agent` VARCHAR(500), `created_at` DATETIME);
CREATE TABLE `system_configs` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `key` VARCHAR(100) NOT NULL UNIQUE, `value` TEXT, `type` TEXT DEFAULT 'string', `description` TEXT, `is_public` TINYINT(1) DEFAULT 0, `updated_at` DATETIME);
CREATE TABLE `companies` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `name` VARCHAR(200) NOT NULL, `address` VARCHAR(500), `province` VARCHAR(100), `city` VARCHAR(100), `district` VARCHAR(100), `industry` VARCHAR(100), `contact_name` VARCHAR(100), `contact_phone` VARCHAR(50), `size` VARCHAR(50), `founding_year` VARCHAR(10), `website` VARCHAR(200), `description` TEXT, `logo_url` VARCHAR(500), `contact_account_id` INTEGER REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `is_verified` TINYINT(1) DEFAULT 0, `verification_status` TEXT DEFAULT 'none', `verification_info` JSON DEFAULT '{}', `code` VARCHAR(50) UNIQUE, `status` TEXT DEFAULT 'active', `settings` JSON DEFAULT '{}', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `company_members` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `company_id` INTEGER NOT NULL REFERENCES `companies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `role` TEXT DEFAULT 'member', `status` TEXT DEFAULT 'active', `joined_at` DATETIME, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `interview_sessions` (`id` UUID PRIMARY KEY, `resume_job_id` INTEGER REFERENCES `resume_jobs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `resume_id` INTEGER REFERENCES `resumes` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `resume_text` TEXT NOT NULL, `total_questions` INTEGER DEFAULT 0, `current_question_index` INTEGER DEFAULT 0, `questions` JSON DEFAULT '[]', `status` TEXT DEFAULT 'CREATED', `expires_at` DATETIME, `report` JSON, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `company_name` VARCHAR(255));
CREATE TABLE `deep_analysis_records` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `resume_id` INTEGER NOT NULL REFERENCES `resumes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `analysis_data` JSON, `created_at` DATETIME, company_id INTEGER DEFAULT NULL);
CREATE TABLE `subscriptions` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `company_id` INTEGER NOT NULL REFERENCES `companies` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `plan` TEXT NOT NULL DEFAULT 'free', `billing_cycle` TEXT DEFAULT 'monthly', `start_at` DATETIME, `end_at` DATETIME, `status` TEXT DEFAULT 'pending', `quota` JSON DEFAULT '{"resume_parses_per_month":100,"concurrent":1,"ai_calls":10000}', `payment_provider` VARCHAR(50), `order_no` VARCHAR(64), `auto_renew` TINYINT(1) DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `subscription_plans` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `key` VARCHAR(50) NOT NULL UNIQUE, `name` VARCHAR(100) NOT NULL, `i18n_names` JSON DEFAULT '{"zh":"","en":""}', `features` JSON DEFAULT '[]', `quota` JSON DEFAULT '{"resume_parses_per_month":100,"concurrent":1,"ai_calls":10000}', `price` DECIMAL(10,2) DEFAULT 0, `status` TEXT DEFAULT 'active', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `model_providers` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `provider` TEXT NOT NULL, `adapter_config` JSON DEFAULT '{}', `enabled` TINYINT(1) DEFAULT 1, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `model_keys` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `company_id` INTEGER REFERENCES `companies` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `provider` TEXT NOT NULL, `api_key` VARCHAR(255) NOT NULL, `limits` JSON DEFAULT '{"rpm":60,"rpd":10000}', `scope` TEXT DEFAULT 'company', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `roles` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `key` VARCHAR(100) NOT NULL UNIQUE, `name` VARCHAR(100) NOT NULL, `description` TEXT, `status` TEXT DEFAULT 'active', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `role_permissions` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `role_id` INTEGER NOT NULL REFERENCES `roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `permission_key` VARCHAR(200) NOT NULL);
CREATE TABLE `user_roles` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `user_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `role_id` INTEGER NOT NULL REFERENCES `roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, UNIQUE (`user_id`, `role_id`));
CREATE TABLE `audit_logs` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `actor_account_id` INTEGER NOT NULL REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `action` VARCHAR(100) NOT NULL, `resource_type` VARCHAR(50), `resource_id` INTEGER, `payload` JSON, `ip` VARCHAR(45), `ua` VARCHAR(500), `occurred_at` DATETIME);
CREATE TABLE `verification_codes` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `phone` VARCHAR(20) NOT NULL, `code` VARCHAR(10) NOT NULL, `type` VARCHAR(20) DEFAULT 'login', `status` TEXT DEFAULT 'sent', `ip` VARCHAR(45), `expires_at` DATETIME NOT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `prompt_templates` (`id` INT PRIMARY KEY AUTO_INCREMENT AUTO_INCREMENT, `key` VARCHAR(100) NOT NULL UNIQUE, `name` VARCHAR(100) NOT NULL, `content` TEXT NOT NULL, `variables` JSON DEFAULT '[]', `description` TEXT, `category` VARCHAR(50) DEFAULT 'general', `is_active` TINYINT(1) DEFAULT 1, `version` INTEGER DEFAULT 1, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
