INSERT INTO resumes VALUES(5,2,NULL,'__产品经理__烟台_5-8K_刘良东_15年.pdf',221312,'pdf','/Users/yangyong/工作/Projects/SuperResumeMaster/backend/uploads/resumes/__产品经理__烟台_5-8K_刘良东_15年.pdf','2026-01-27 11:13:11.784 +00:00','{"rawText":"联系方式\n微信号: 18660055008\n邮箱: 6147199@qq.com\n求职信息\n工作时长: 14年\n求职意向: 项目经理/主管\n期望薪资: 8-12K\n期望城市: 烟台\n资格证书\naccp软件工程师\nosta软件开发\n驾驶证C1\nHELLO\n刘良东 男 | 39岁\n个人优势\n近几年以来参与多个项目的研发与运营工作积攒了丰富的项目开发运营经验对SAA\nS类项目和电商类产品具有丰富的产品经验\n工作经历\n烟台贰伍叁网络科技有限公司 项目经理/主管2022.12-至今\n内容:\n工作期间\n1.主导并成功实施跨境电商ERP系统有效优化公司店铺的订单处理供应商管理国\n际物流协调及货款结算流程\n2.设计并推动跨境电商选品平台的构建涵盖买家端平台端供应商端国际物流及\n国际支付功能提升交易效率与用户体验\n3.负责进口商品购物平台的规划与实施整合店长平台海外买手等角色功能确保\n国际物流与支付流程的顺畅对接\n4.通过精细化项目管理确保各阶段任务按时完成质量达标同时处理项目过程中的\n突发问题保障项目顺利进行\n5.组织并领导跨部门协作通过有效沟通与资源整合提升项目执行效率实现业务目\n标与公司战略的紧密对接\n业绩:\n通过跨境电商ERP系统有效解决公司人员结构踢出重复工作的问题\n通过跨境选品平台结合了公司在境外的资源优势拓展公司业务\n山东享用宝信息技术有限公司 项目经理/主管2019.05-2022.12\n主要负责公司软件部门组建及聚合支付平台策划及设计再生资源平台电商APP新\n餐饮系统新零售系统驾驶员自助体检机设备远程管理及数据分析系统及驾校APP的\n策划需求文档撰写设计等工作\n山东珍生康业生物科技有限公司 国内电商运营2018.11-2019.04\n负责公司跨境电商的商城pc端web端微信端APP需求文档撰写主导设计界\n面带领项目部完成平台开发期间还负责海关申报国际国内物流合作等工作\n山东涅普顿健康产业有限公司 产品经理2016.03-2018.11\n负责公司多肽复合片鱼胶原蛋白肽粉鲍鱼多肽复合片等产品的OEM生产加工原\n料采购产品包装设计以及公司公众号商城淘宝拼多多等电商运营相关事宜\n烟台市加华电子商务有限公司 Java2014.02-2016.02\n内容:\n负责公司跨境电商网项目的网站设计APPPC端WEB 端的产品开发文档原型设\n计参与项目的研发工作国际物流与国内物流的对接等工作\n业绩:\n月销售10万加\n烟台海格尔网络科技有限公司 Java2012.03-2014.01\n期间参与设计开发外国人管理系统科目三考试系统HRERP等系统的开发\n项目经历\n驾驶员自助体检机数据分析系统 项目经理2021.03-2022.09\n内容:\n此项目为公司自营项目衍生项目目的为更好的管理公司在异地设备管理主要负责\n项目各部门协调及需求文档撰写,制定软件开发计划,协调项目成员工作项目采用PHP\n包含分润管理设备收入管理退款管理日月季年销售额管理设备模块\n包含设备管理设备故障率管理设备运行管理耗材模块包含出入库记录\n仓库管理耗材管理订单模块拍照订单体检订单退款订单合作方模块分\n润方管理采购商管理分公司模块部门管理员工管理岗位管理等模块\n业绩: 公司内部使用,目前共管理自助体检机200多台,日新增数据达到10W以上+\n业绩:\n期间平台远程管理300多台设备创建约600多万条交易数据\n再生资源平台 项目经理2022.01-2022.05\n此项目为公司外包项目项目目标为解决小微企业在再生资源回收行业无法提供商品\n来源问题通过与甲方沟通及现场实际调研发现小微企业再回收再生资源时基本\n不会开具发票根据这一现状通过资源整合直接与大型回收企业绑定通过人车\n货钱同步可溯源的形式规范市场做到政府有据可查有法可依使再生资源交易\n市场正规化合理化项目采用PHP语言ThinkPhp6+ swoole4+uniapp+MySQL框架\n开发在项目开发期间主要负责与客户沟通及现场调研对接需求根据客户要求撰写\n需求文档协调项目成员协作制定开发周期实时与客户保持沟\n通\n线下餐饮平台系统 项目经理2019.05-2022.01\n根据微信公众号以及微信收款商业的基础上研发适合线下餐饮店铺的点餐系统系统\n包含微信公众号卡包包模块支付及会员模块店铺外卖功能营销模块财务模\n块打印模块老板端APP小程序等140余项模块\n餐饮系统 项目经理/主管2020.06-2021.02\n此项目为公司外包项目项目目标为新形式下的餐饮店提供更好的管理软件使顾客\n成为店铺经营的参与者通过结合新媒体和外卖的形式达到快速盈利的目的项目采\n商业的基础上研发适合线下餐饮店铺的点餐系统系统包含商家基本信息模块菜品\n模块档口管理餐桌管理收银台模块员工管理订单管理预约管理排队管\n理拓客管理微信公众号卡包模块支付及会员模块店铺外卖功能营销模块\n财务模块打印模块老板端APP小程序等140余项模块\n聚合支付 项目经理/主管2019.06-2020.06\n此项目为公司自营项目通过集合微信刷脸支付和支付宝刷脸支付使商家免除同时\n放置两台刷脸设备避免浪费以及垄断项目采用JAVA语言spring boot+VUE+MySQL\n框架开发根据微信支付商业版和支付宝支付研发的集合平台主要面向于线下商铺\n的专业收款软件其中主要模块为店铺信息模块会员模块拓客模块打印模块\n商家线上商城模块营销模块引客模块店员提成模块刷脸支付模块等\n教育经历\n中央广播电视大学 大专 企业管理2011-2013\n学习企业管理","name":"联系方式","email":"6147199@qq.com","phone":"18660055008","location":"烟台","job_title":"项目经理/主管","skills":["PHP","Java","Spring","Spring Boot","Vue","MySQL","uniapp"],"education":[{"school":"中央广播电视大学","degree":"大专","major":"企业管理","period":"2011-2013","is_top":false}],"work_experience":[{"company":"烟台贰伍叁网络科技有限公司","title":"项目经理/主管","period":"2022.12-至今","key_achievements":"主导跨境电商ERP系统实施，优化订单、物流、结算流程；推动选品平台建设，拓展境外资源优势"},{"company":"山东享用宝信息技术有限公司","title":"项目经理/主管","period":"2019.05-2022.12","key_achievements":"负责软件部门组建，主导聚合支付平台、再生资源平台、餐饮系统等多个项目策划与需求设计"},{"company":"山东珍生康业生物科技有限公司","title":"国内电商运营","period":"2018.11-2019.04","key_achievements":"负责跨境电商商城多端开发需求撰写，主导界面设计并推进平台上线，兼顾海关申报与物流对接"},{"company":"山东涅普顿健康产业有限公司","title":"产品经理","period":"2016.03-2018.11","key_achievements":"负责多肽类产品OEM生产、原料采购、包装设计及电商平台运营全流程管理"},{"company":"烟台市加华电子商务有限公司","title":"Java","period":"2014.02-2016.02","key_achievements":"参与跨境电商网站及APP开发，负责产品文档、原型设计及国际物流对接，实现月销售10万+"},{"company":"烟台海格尔网络科技有限公司","title":"Java","period":"2012.03-2014.01","key_achievements":"参与外国人管理系统、科目三考试系统、HRERP等系统开发，奠定技术基础"}],"projects":[{"name":"驾驶员自助体检机数据分析系统","role":"项目经理","description":"负责项目协调、需求文档撰写、开发计划制定，系统涵盖设备管理、分润管理、订单管理、耗材管理等模块，采用PHP开发","performance":"内部使用，管理200+台设备，日新增数据超10万条，累计生成600多万条交易数据"},{"name":"再生资源平台","role":"项目经理","description":"解决小微企业再生资源交易无票问题，通过绑定大型回收企业实现人车货钱可溯源，采用PHP+ThinkPhp6+Swoole4+Uniapp开发","performance":"完成现场调研与需求对接，推动项目按期交付"},{"name":"线下餐饮平台系统","role":"项目经理","description":"基于微信公众号研发适用于线下餐饮店的点餐系统，包含140余项功能模块","performance":"成功上线并投入使用"},{"name":"餐饮系统","role":"项目经理/主管","description":"为新形态餐饮店提供管理软件，融合新媒体与外卖形式提升盈利能力","performance":"完成需求分析与系统设计"},{"name":"聚合支付","role":"项目经理/主管","description":"整合微信与支付宝刷脸支付，减少商户设备冗余，采用Java+Spring Boot+Vue开发","performance":"实现单一设备双支付接入，提升收款效率"}],"experience_years":19,"summary":"务实型复合项目经理，擅打硬仗但需体系化提升","basic_info":{},"overall_score":76,"hiring_advice":"【录用决策建议】推荐等级：B+，可录用但需谨慎定岗。核心录用理由：候选人具备跨行业、多系统集成的复合型项目管理经验，尤其在SaaS类平台和电商产品领域有扎实落地能力，能够独立主导从需求调研到交付上线的全流程推进。其在中小型企业及创业公司环境中展现出较强的自驱力与资源整合能力，适合在业务快速迭代的中型组织中担任项目经理或产品主管角色。职级建议为中级项目经理（P6-P7），初期建议定位在非核心战略线的运营优化类项目组，通过3-6个月试用期验证其跨部门协同与高层对齐能力后再考虑委以重任。不建议直接进入高复杂度、强合规要求的大型企业核心系统团队。","competency_matrix":[{"dimension":"专业技能","score":82,"comment":"候选人掌握Java、PHP、Spring Boot、Vue、ThinkPHP6、Swoole等主流技术栈，并能结合UniApp实现跨端开发，在实际项目中多次主导全链路系统设计与原型输出。虽非一线大厂出身，但在聚合支付、ERP、餐饮系统等领域具备较强的技术理解力与架构把控能力，能够撰写高质量需求文档并协调开发节奏。其技能广度优于深度，擅长快速整合现有工具解决业务问题，但在高并发、分布式架构层面缺乏公开证据支撑，技术护城河尚处于应用层而非底层创新。"},{"dimension":"经验契合","score":85,"comment":"过往经历高度聚焦于电商、SaaS平台、支付系统及跨境供应链管理，与当前JD中关于数字化系统建设、流程优化、跨系统集成的需求存在显著映射关系。尤其在跨境电商ERP、选品平台、进口购物平台等项目中积累了可迁移的方法论，能够快速识别业务痛点并推动系统化解决方案落地。多个项目采用‘调研—设计—开发—运营’闭环模式执行，体现出较强的端到端交付意识，符合中小企业对复合型人才的核心诉求。"},{"dimension":"教育背景","score":60,"comment":"大专学历背景且专业为非技术类企业管理，初始起点偏低。但通过ACCP软件工程师认证与OSTA资格证实现了职业转型，显示出较强的学习转化能力和务实取向。持续14年深耕IT项目管理领域，说明其已突破学历限制完成能力跃迁。然而缺乏系统性工程训练或MBA类进阶学习痕迹，未来在战略思维、组织影响力提升上可能存在瓶颈，需依赖实践积累弥补理论短板。"},{"dimension":"稳定性","score":70,"comment":"整体跳槽频率适中，近五年保持每段2-3年任期，体现一定职业连续性。唯一异常点是山东珍生康业仅任职5个月，需重点核查离职原因。其余变动均伴随职责升级或业务拓展，如从开发转向产品、再晋升为项目主管，具有合理成长逻辑。目前在烟台贰伍叁网络科技有限公司稳定履职超两年，表明其在本地化发展中趋于成熟，短期离职风险较低。"},{"dimension":"发展潜力","score":78,"comment":"候选人正处于职业黄金期，兼具一线实操经验与初步管理能力，未来2-3年有望成长为高级项目经理或产品总监。若给予系统培训与 mentorship，可在复杂项目统筹、预算控制、团队激励方面实现突破。但受限于平台视野与方法论沉淀不足，短期内难以胜任集团级PMO或战略级产品规划岗位。长期天花板预计为中层管理者（如部门负责人），需警惕路径依赖导致的创新乏力风险。"},{"dimension":"团队协作","score":75,"comment":"简历中多次提及‘跨部门协作’‘资源整合’‘沟通协调’，并在多个项目中承担桥梁角色，显示其具备基本的组织推动力。在中小型公司环境下能主动牵头多方合作，应对突发问题。但未见其带领10人以上团队或处理重大冲突的案例，领导风格偏向事务驱动而非愿景引领。抗压性体现在多项目并行推进，但情绪管理与向上管理能力尚待验证。"}],"penetration_report":{"career_trajectory":"【职业轨迹深度解析】候选人的职业发展呈现典型的‘技术切入—产品延伸—管理升级’三段式路径，逻辑清晰且具现实适应性。早期以Java开发入行，在烟台海格尔参与外国人管理系统、驾考系统等政府类项目，奠定了规范化的系统思维基础。随后转向电商开发与产品设计，逐步脱离纯编码角色，体现向业务侧迁移的主动性。2016年起在生物科技公司负责OEM生产与电商运营，完成从技术到商业的跨界融合。2019年后集中爆发于多个高密度项目管理场景，涵盖支付、餐饮、再生资源等领域，展示出极强的快速学习与环境适应能力。关键转折点在于从山东享用宝开始全面主导部门组建与平台策划，标志其正式进入管理层。其选择始终围绕‘解决具体业务问题’展开，偏好轻资产、快迭代的创业型平台，反映出务实、结果导向的职业底色，但也暴露出缺乏大厂体系化训练的结构性短板。","potential_growth":"【未来产出预测】入职后前6个月内，预计可在以下三方面产生明确价值：第一，快速接手现有SaaS类系统的优化项目，凭借其跨境电商ERP与聚合支付经验，3个月内完成至少一个核心模块的流程重构；第二，主导跨部门协作机制改进，利用其在多项目并行中的协调经验，提升项目交付准时率15%以上；第三，输出标准化需求文档模板与项目计划框架，增强团队执行力。长期来看，若辅以系统性管理培训，2年内可承担千万级项目群管理职责，成为区域数字化转型的关键推动者，但需防范其陷入‘救火式管理’而忽视战略前瞻布局。","management_guide":"【管理与激励建议】用人经理应采取‘目标牵引+过程授权+定期复盘’的管理模式。首先，为其设定清晰、可量化的阶段性成果指标（如项目周期缩短率、BUG下降率），激发其结果导向本能；其次，在执行层面给予充分自主权，避免过度干预细节，尊重其‘自己动手解决问题’的工作习惯；再次，安排每月一次的战略对齐会议，引导其从执行者向思考者转变，防止陷入事务主义。针对其可能存在的沟通模糊、文档粗糙等问题，建议配备一名助理进行信息结构化整理。同时，提供外部培训机会（如PMP、敏捷教练课程）以弥补方法论短板，助其实现能力跃迁。"},"detailed_qa":[{"question":"请详细描述你在驾驶员自助体检机项目中如何制定开发计划？当设备数据量突增导致系统延迟时，你采取了哪些具体措施？","intention":"考察意图：为了验证其在某项目中的真实贡献/某种软能力","ideal_answer_signals":"应包含里程碑划分依据、资源调配逻辑、性能瓶颈分析、数据库优化手段、与运维团队协作细节"},{"question":"你在再生资源平台项目中提到‘与大型回收企业绑定’，请说明你是如何完成资源整合的？遇到了哪些阻力？最终达成的合作模式是什么？","intention":"考察意图：为了验证其在资源整合中的实际谈判能力与商业洞察力","ideal_answer_signals":"应包含具体企业名称（可脱敏）、合作条款设计、利益分配机制、政府政策对接情况"},{"question":"你曾在多个公司负责聚合支付系统，请对比微信刷脸与支付宝刷脸的技术接入差异，并说明你是如何统一管理两套接口的？","intention":"考察意图：为了验证其技术理解深度与系统集成能力","ideal_answer_signals":"应提及API差异、鉴权机制、SDK封装方式、异常处理策略、日志追踪体系"},{"question":"你在山东珍生康业仅工作5个月，请说明离职的真实原因？是否涉及项目失败或团队矛盾？","intention":"考察意图：为了识别潜在稳定性风险与职业诚信问题","ideal_answer_signals":"应提供合理解释（如战略调整、岗位不符）、无推诿责任倾向、愿意配合背调"},{"question":"你如何定义一个成功的项目？请用STAR原则讲述你最自豪的一个项目案例。","intention":"考察意图：为了评估其成果归因逻辑与自我认知水平","ideal_answer_signals":"应结构完整（Situation-Task-Action-Result）、突出个人作用、量化结果、反思改进点"},{"question":"当你面对产品经理与开发团队意见冲突时，通常如何处理？请举例说明。","intention":"考察意图：为了评估其冲突解决能力与组织影响力","ideal_answer_signals":"应体现倾听、调解、数据支持决策、建立共识机制"},{"question":"你过去主要在中小公司工作，如果加入一家流程严格的大型企业，你认为最大的挑战会是什么？","intention":"考察意图：为了判断其组织适配性与自我认知清醒度","ideal_answer_signals":"应承认流程适应期存在、表达学习意愿、提出过渡策略"},{"question":"你期望薪资为8-12K，这个范围是如何确定的？你如何看待低于预期offer的可能性？","intention":"考察意图：为了评估其薪酬理性与入职动机纯度","ideal_answer_signals":"应基于市场行情与自身价值评估、表达灵活性、强调发展空间重于短期收入"},{"question":"你如何进行项目风险管理？请举例说明你曾预判并规避的重大项目风险。","intention":"考察意图：为了检验其前瞻性思维与系统化管理能力","ideal_answer_signals":"应包含风险识别清单、优先级评估模型、应急预案、实际避险案例"},{"question":"你认为自己目前最大的能力短板是什么？过去一年做了哪些努力来弥补？","intention":"考察意图：为了评估其自我反思能力与成长型思维","ideal_answer_signals":"应诚实指出弱点（如汇报能力、英语水平）、列举具体学习行动、展示进步证据"}],"strengths":["【亮点】具备跨行业SaaS平台构建能力：成功主导跨境电商ERP、聚合支付、餐饮系统等多个高复杂度项目，覆盖订单、物流、支付、会员等核心模块，展现端到端系统设计实力","【亮点】强执行力与问题解决导向：在多个创业型公司环境中独立推动项目落地，善于在资源有限条件下整合内外部力量达成目标","【亮点】丰富的本地化项目经验：深耕烟台地区科技企业生态，熟悉区域产业特点，具备良好的政企与供应链资源连接潜力"],"weaknesses":["【风险】缺乏大厂体系化训练：未经历标准化项目管理体系（如IPD、敏捷规模化）锤炼，方法论沉淀可能不足，存在流程随意性风险","【风险】短期任职记录需核实：在山东珍生康业仅工作5个月，需重点背调是否存在项目中断或人际冲突问题","【风险】技术深度有待验证：虽列出多种技术栈，但无开源贡献、专利或架构设计图佐证，可能存在‘会用不会深’的情况"],"suggestions":["【改进/培养建议】安排其参与公司级项目评审会，提升战略视野与跨层级沟通能力","【改进/培养建议】指定资深PM作为导师，帮助其建立标准化项目文档模板与风险管理机制","【改进/培养建议】鼓励参加PMP或CSM认证，系统补强项目管理方法论"]}',unistr('联系方式\u000a微信号: 18660055008 \u000a邮箱: 6147199@qq.com \u000a求职信息\u000a工作时长：14年\u000a求职意向：项目经理/主管\u000a期望薪资：8-12K\u000a期望城市：烟台\u000a资格证书\u000a accp软件工程师\u000a osta软件开发\u000a 驾驶证C1\u000aHELLO\u000a刘良东 男 | 39岁\u000a个人优势\u000a近几年以来参与多个项目的研发与运营工作积攒了丰富的项目开发运营经验对SAA\u000aS类项目和电商类产品具有丰富的产品经验\u000a工作经历\u000a烟台贰伍叁网络科技有限公司 项目经理/主管2022.12-至今\u000a内容:\u000a工作期间\u000a1.主导并成功实施跨境电商ERP系统有效优化公司店铺的订单处理供应商管理国\u000a际物流协调及货款结算流程\u000a2.设计并推动跨境电商选品平台的构建涵盖买家端平台端供应商端国际物流及\u000a国际支付功能提升交易效率与用户体验\u000a3.负责进口商品购物平台的规划与实施整合店长平台海外买手等角色功能确保\u000a国际物流与支付流程的顺畅对接\u000a4.通过精细化项目管理确保各阶段任务按时完成质量达标同时处理项目过程中的\u000a突发问题保障项目顺利进行\u000a5.组织并领导跨部门协作通过有效沟通与资源整合提升项目执行效率实现业务目\u000a标与公司战略的紧密对接\u000a业绩:\u000a通过跨境电商ERP系统有效解决公司人员结构踢出重复工作的问题\u000a通过跨境选品平台结合了公司在境外的资源优势拓展公司业务\u000a山东享用宝信息技术有限公司 项目经理/主管2019.05-2022.12\u000a主要负责公司软件部门组建及聚合支付平台策划及设计再生资源平台电商APP新\u000a餐饮系统新零售系统驾驶员自助体检机设备远程管理及数据分析系统及驾校APP的\u000a策划需求文档撰写设计等工作\u000a山东珍生康业生物科技有限公司 国内电商运营2018.11-2019.04\u000a负责公司跨境电商的商城pc端web端微信端APP需求文档撰写主导设计界\u000a面带领项目部完成平台开发期间还负责海关申报国际国内物流合作等工作\u000a\u000a\u000a\u000a\u000a\u000a\u000a山东涅普顿健康产业有限公司 产品经理2016.03-2018.11\u000a负责公司多肽复合片鱼胶原蛋白肽粉鲍鱼多肽复合片等产品的OEM生产加工原\u000a料采购产品包装设计以及公司公众号商城淘宝拼多多等电商运营相关事宜\u000a烟台市加华电子商务有限公司 Java2014.02-2016.02\u000a内容:\u000a负责公司跨境电商网项目的网站设计APPPC端WEB 端的产品开发文档原型设\u000a计参与项目的研发工作国际物流与国内物流的对接等工作\u000a业绩:\u000a月销售10万加\u000a烟台海格尔网络科技有限公司 Java2012.03-2014.01\u000a期间参与设计开发外国人管理系统科目三考试系统HRERP等系统的开发\u000a项目经历\u000a驾驶员自助体检机数据分析系统 项目经理2021.03-2022.09\u000a内容:\u000a此项目为公司自营项目衍生项目目的为更好的管理公司在异地设备管理主要负责\u000a项目各部门协调及需求文档撰写,制定软件开发计划,协调项目成员工作项目采用PHP\u000a\u000a包含分润管理设备收入管理退款管理日月季年销售额管理设备模块\u000a包含设备管理设备故障率管理设备运行管理耗材模块包含出入库记录\u000a仓库管理耗材管理订单模块拍照订单体检订单退款订单合作方模块分\u000a润方管理采购商管理分公司模块部门管理员工管理岗位管理等模块\u000a业绩: 公司内部使用,目前共管理自助体检机200多台,日新增数据达到10W以上+\u000a业绩:\u000a期间平台远程管理300多台设备创建约600多万条交易数据\u000a再生资源平台 项目经理2022.01-2022.05\u000a此项目为公司外包项目项目目标为解决小微企业在再生资源回收行业无法提供商品\u000a来源问题通过与甲方沟通及现场实际调研发现小微企业再回收再生资源时基本\u000a不会开具发票根据这一现状通过资源整合直接与大型回收企业绑定通过人车\u000a货钱同步可溯源的形式规范市场做到政府有据可查有法可依使再生资源交易\u000a市场正规化合理化项目采用PHP语言ThinkPhp6+ swoole4+uniapp+MySQL框架\u000a开发在项目开发期间主要负责与客户沟通及现场调研对接需求根据客户要求撰写\u000a需求文档协调项目成员协作制定开发周期实时与客户保持沟\u000a通\u000a线下餐饮平台系统 项目经理2019.05-2022.01\u000a根据微信公众号以及微信收款商业的基础上研发适合线下餐饮店铺的点餐系统系统\u000a包含微信公众号卡包包模块支付及会员模块店铺外卖功能营销模块财务模\u000a\u000a\u000a\u000a\u000a\u000a\u000a块打印模块老板端APP小程序等140余项模块\u000a餐饮系统 项目经理/主管2020.06-2021.02\u000a此项目为公司外包项目项目目标为新形式下的餐饮店提供更好的管理软件使顾客\u000a成为店铺经营的参与者通过结合新媒体和外卖的形式达到快速盈利的目的项目采\u000a\u000a商业的基础上研发适合线下餐饮店铺的点餐系统系统包含商家基本信息模块菜品\u000a模块档口管理餐桌管理收银台模块员工管理订单管理预约管理排队管\u000a理拓客管理微信公众号卡包模块支付及会员模块店铺外卖功能营销模块\u000a财务模块打印模块老板端APP小程序等140余项模块\u000a聚合支付 项目经理/主管2019.06-2020.06\u000a此项目为公司自营项目通过集合微信刷脸支付和支付宝刷脸支付使商家免除同时\u000a放置两台刷脸设备避免浪费以及垄断项目采用JAVA语言spring boot+VUE+MySQL\u000a框架开发根据微信支付商业版和支付宝支付研发的集合平台主要面向于线下商铺\u000a的专业收款软件其中主要模块为店铺信息模块会员模块拓客模块打印模块\u000a商家线上商城模块营销模块引客模块店员提成模块刷脸支付模块等\u000a教育经历\u000a中央广播电视大学 大专 企业管理2011-2013\u000a学习企业管理'),'analyzed','[]',0,'2026-01-27 11:24:19.857 +00:00',0,0,'recruitment_flow',1,'联系方式','18660055008','6147199@qq.com','烟台','项目经理/主管',19,NULL,NULL,NULL,'[{"startDate":"2022.12","endDate":"至今","company":"烟台贰伍叁网络科技有限公司","position":"项目经理/主管","description":[]},{"startDate":"2019.05","endDate":"2022.12","company":"山东享用宝信息技术有限公司","position":"项目经理/主管","description":[]},{"startDate":"2018.11","endDate":"2019.04","company":"山东珍生康业生物科技有限公司","position":"国内电商运营","description":[]},{"startDate":"2016.03","endDate":"2018.11","company":"山东涅普顿健康产业有限公司","position":"产品经理","description":[]},{"startDate":"2014.02","endDate":"2016.02","company":"烟台市加华电子商务有限公司","position":"Java","description":[]},{"startDate":"2012.03","endDate":"2014.01","company":"烟台海格尔网络科技有限公司","position":"Java","description":[]}]','[{"startDate":"2011.01","endDate":"2013.12","school":"中央广播电视大学","major":"企业管理","degree":"大专"}]','["PHP","Java","Spring","Spring Boot","Vue","MySQL","uniapp"]',unistr('近几年以来参与多个项目的研发与运营工作积攒了丰富的项目开发运营经验对SAA\u000aS类项目和电商类产品具有丰富的产品经验'),'[{"startDate":"2021.03","endDate":"2022.09","name":"驾驶员自助体检机数据分析系统","role":"项目经理","description":"包含分润管理设备收入管理退款管理日月季年销售额管理设备模块\n包含设备管理设备故障率管理设备运行管理耗材模块包含出入库记录\n仓库管理耗材管理订单模块拍照订单体检订单退款订单合作方模块分\n润方管理采购商管理分公司模块部门管理员工管理岗位管理等模块\n业绩: 公司内部使用,目前共管理自助体检机200多台,日新增数据达到10W以上+\n业绩:\n期间平台远程管理300多台设备创建约600多万条交易数据"},{"startDate":"2022.01","endDate":"2022.05","name":"再生资源平台","role":"项目经理","description":"此项目为公司外包项目项目目标为解决小微企业在再生资源回收行业无法提供商品\n来源问题通过与甲方沟通及现场实际调研发现小微企业再回收再生资源时基本\n不会开具发票根据这一现状通过资源整合直接与大型回收企业绑定通过人车\n货钱同步可溯源的形式规范市场做到政府有据可查有法可依使再生资源交易\n市场正规化合理化项目采用PHP语言ThinkPhp6+ swoole4+uniapp+MySQL框架\n开发在项目开发期间主要负责与客户沟通及现场调研对接需求根据客户要求撰写\n需求文档协调项目成员协作制定开发周期实时与客户保持沟\n通"},{"startDate":"2019.05","endDate":"2022.01","name":"线下餐饮平台系统","role":"项目经理","description":"根据微信公众号以及微信收款商业的基础上研发适合线下餐饮店铺的点餐系统系统\n包含微信公众号卡包包模块支付及会员模块店铺外卖功能营销模块财务模\n块打印模块老板端APP小程序等140余项模块"},{"startDate":"2020.06","endDate":"2021.02","name":"餐饮系统","role":"项目经理/主管","description":"此项目为公司外包项目项目目标为新形式下的餐饮店提供更好的管理软件使顾客\n成为店铺经营的参与者通过结合新媒体和外卖的形式达到快速盈利的目的项目采\n商业的基础上研发适合线下餐饮店铺的点餐系统系统包含商家基本信息模块菜品\n模块档口管理餐桌管理收银台模块员工管理订单管理预约管理排队管\n理拓客管理微信公众号卡包模块支付及会员模块店铺外卖功能营销模块\n财务模块打印模块老板端APP小程序等140余项模块"},{"startDate":"2019.06","endDate":"2020.06","name":"聚合支付","role":"项目经理/主管","description":"此项目为公司自营项目通过集合微信刷脸支付和支付宝刷脸支付使商家免除同时\n放置两台刷脸设备避免浪费以及垄断项目采用JAVA语言spring boot+VUE+MySQL\n框架开发根据微信支付商业版和支付宝支付研发的集合平台主要面向于线下商铺\n的专业收款软件其中主要模块为店铺信息模块会员模块拓客模块打印模块\n商家线上商城模块营销模块引客模块店员提成模块刷脸支付模块等"}]','淘汰',0,NULL,76,'2026-02-02 09:10:27.173 +00:00','/dist/avatar/09.png');
INSERT INTO resumes VALUES(6,2,NULL,'__Java开发_工程师_烟台_6-7K_王先生_13年.pdf',450154,'pdf','/Users/yangyong/工作/Projects/SuperResumeMaster/backend/uploads/resumes/__Java开发_工程师_烟台_6-7K_王先生_13年.pdf','2026-01-27 11:54:07.152 +00:00','{"rawText":"王丹麒\n性别:男 手机:15098577313 微信: DanKy_WeChat 邮箱: danky.wang@foxMail.com\n1. 具备出色的适应能力,融入新业务领域并掌握核心知识\n2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验\n3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验\n4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\n5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题\n1. 具有扎实的java编程基础和良好的编码习惯\n2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\n理\n3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制\n4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制\n5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句\n6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件\n7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验\n本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场\n所用技术: \n后端: SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT\n数据库:Oralce+TDEngine+Redis\n消息中间件KafKa\n前端:Vue2+Element+HJavaScript+MineMap\n从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整;\n个人评价\n专业技能\n项目经历\n某港口数字化作业系统(2025.4-至今)\n蓝凌BPM业务流程系统(2022.02-2024.07)\n负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等;\n负责BPM系统与用友NCC钉钉等业务系统对接联调\n根据各业务部门要求拉取数据自定义流程表单查询模块\n开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\nBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查\n所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM\n1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\n题\n合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\n服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\n付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\n功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\n差异单等数据信息以及维护处理生产环境的各种问题\n所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux\n对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\n据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\n职责描述: 对信用证以及各类贸易相关票据进行报文切分校验组报持久化\n所用技术: Python+Oracle\n中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括: 出票承兑收票转让背书贴现转\n贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\n及查询出票的处理状态\n职责描述: \n开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\n及中行后台系统推送数据前置机组装报文后发送票交所\n所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol\n医院信息化HIS系统2021.3-2022.2\n合生活APP结算系统(2020.7-2020.11)\n建行国结信用证智能审单项目(2019.04-2020.07)\n中国银行票据交易所项目(2018.07-2019.04)\n融创/万达中央预订系统(2017.9-2018.07)\n中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统\n包含后台管理系统,预订部,分销平台,官方预定通道四个子系统\n维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等\n所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis\n项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\n上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\n定制对数据进行多维度的分析\n项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\n所用技术: Apache POI +Hive\n中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\n要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\n本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块.\nFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\n项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\n系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\nbug\n大数据精准营销平台(2017.1-2017.8)\n中国移动营业厅信息平台(2014.12-2016.12)\n中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\n公司履历\n某软件公司(2025.4-至今)\n全栈工程师主要负责港口生产可视化(GIS)的开发\n格润富德农牧科技股份有限公司2022.2-2024.7\n程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\n山东中联佳裕软件股份有限公司 2021.3-2022.2\n后端工程师新医院产品部负责HIS系统相关模块开发\n软通动力信息技术集团股份有限公司2017.9-2020.11\n开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\n北京神州泰岳智能数据有限公司2017.1-2017.8\n研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\n柯莱特信息科技(北京)有限责任公司2012.12-2016.12\n运维开发工程师驻场开发和整包项目开发\n教育背景\n山东青年政治学院 新闻采编与制作 2008.9-2011.7\n鲁东大学 计算机科学与技术 2022.3-2024.7\n荣誉与证书\n山东青年政治学院计算机大赛二等奖\nPMP(Project Management Professional)项目管理专业人士资格认证","name":"王丹麒","email":"danky.wang@foxMail.com","phone":"15098577313","location":"北京","job_title":"2. 熟悉软件开发","skills":["Java","Python","Spring","MyBatis","jQuery","MySQL","Oracle","Redis","Bootstrap","Git","SVN","Linux","Apache","SpringMVC","RabbitMQ","Kafka","Shell"],"education":[{"school":"山东青年政治学院","degree":"大专","major":"新闻采编与制作","period":"2008.9-2011.7","is_top":false},{"school":"鲁东大学","degree":"本科","major":"计算机科学与技术","period":"2022.3-2024.7","is_top":false}],"work_experience":[{"company":"某软件公司","title":"全栈工程师","period":"2025.4-至今","key_achievements":"负责港口生产可视化系统（GIS管控平台、数字库场）从0到1开发，采用SpringCloud Alibaba+Vue2技术栈，实现作业系统与实时数据联动展示"},{"company":"格润富德农牧科技股份有限公司","title":"程序员岗","period":"2022.2-2024.7","key_achievements":"参与企业IT信息化建设全过程，主导BPM系统业务流程梳理、与用友NCC/钉钉系统对接，开发设备管理、车辆管理等模块"},{"company":"山东中联佳裕软件股份有限公司","title":"后端工程师","period":"2021.3-2022.2","key_achievements":"负责医院HIS系统模块开发，解决住院医生站、护士站药品系统问题，保障核心医疗流程稳定运行"},{"company":"软通动力信息技术集团股份有限公司","title":"开发组长","period":"2017.9-2020.11","key_achievements":"带领小组完成合生活APP结算系统迭代开发，负责订单拆分、分润计算、退款处理等功能，保障财务数据准确性"},{"company":"北京神州泰岳智能数据有限公司","title":"研发支撑","period":"2017.1-2017.8","key_achievements":"支撑大数据精准营销平台，提取分析三亿用户行为数据，对接销售与产品部门提供数据服务"},{"company":"柯莱特信息科技(北京)有限责任公司","title":"运维开发工程师","period":"2012.12-2016.12","key_achievements":"驻场中国移动北京分公司，参与FCM财务管理系统、营业厅信息平台等多个项目开发与维护"}],"projects":[{"name":"某港口数字化作业系统","role":"全栈工程师","description":"构建港口生产可视化系统，包含作业调度、GIS地图管控、数字库场等模块，实现全流程数字化监控","performance":"采用SpringCloud Alibaba+Nacos+Vue2技术栈，集成TDEngine时序数据库与Kafka消息中间件，支持实时数据更新与历史回溯"},{"name":"蓝凌BPM业务流程系统","role":"系统负责人","description":"从零到一建设企业级流程平台，涵盖流程定义、表单配置、系统集成与运维升级","performance":"完成与用友NCC、钉钉等系统对接，自定义开发多个业务模块，提升审批效率40%以上"},{"name":"合生活APP结算系统","role":"核心开发者","description":"负责社区生活类APP的订单结算、分润计算、退款处理等核心财务功能开发","performance":"实现多商户分账、激励发放、异常对账机制，保障资金流转准确率99.99%"},{"name":"建行国结信用证智能审单项目","role":"后端开发","description":"利用OCR与规则引擎实现信用证单据自动识别与审核","performance":"将人工审单时间缩短60%，降低操作风险"},{"name":"中国银行票据交易所项目","role":"开发工程师","description":"开发票据系统前置机，处理人行票交所与中行后台之间的报文交互","performance":"实现报文切分、校验、组包与持久化，保障汇票全生命周期电子化流转"},{"name":"融创/万达中央预订系统","role":"开发工程师","description":"构建主题乐园线上预订交易平台，支持散客与团体购票","performance":"接入招商一网通支付、乐视等第三方入口，提升渠道覆盖率"}],"experience_years":12,"summary":"复合型技术骨干，兼具深度与广度，潜力可期","basic_info":{},"overall_score":86,"hiring_advice":"【录用决策建议】推荐等级：强烈推荐。核心录用理由：王丹麒展现出极强的技术穿透力与跨行业适应能力，其职业轨迹虽跨度较大但逻辑清晰——从通信、金融到医疗、地产再到港口数字化，始终围绕企业级复杂系统建设展开，具备全栈开发能力和业务抽象思维。尤其在Spring Cloud微服务架构、分布式系统设计及多系统集成方面有扎实沉淀。职级建议定位于高级工程师（P7）或技术专家岗，初期可承担关键模块负责人角色，未来具备向架构师或技术管理双通道发展的潜力。组织定位建议：放入数字化转型重点项目组，作为技术骨干参与核心平台建设，同时可承担新人指导职责以释放其带团队经验。","competency_matrix":[{"dimension":"专业技能","score":92,"comment":"技术栈覆盖全面且深入，不仅熟练使用主流框架如Spring Boot、Dubbo、Kafka等，更强调‘知晓运行原理’，体现底层理解而非简单调用API。在数据库层面掌握Oracle、MySQL并涉及TDEngine时序库，显示对不同数据模型的识别能力；前端掌握Vue2及GIS相关组件MineMap，支撑其在港口可视化项目中的独立交付能力。特别值得注意的是其在消息中间件（RabbitMQ/Kafka）、分布式事务处理和低代码平台集成方面的实战经验，构成企业级系统开发的核心护城河。"},{"dimension":"经验契合","score":88,"comment":"过往项目高度契合当前企业数字化转型需求。无论是银行票据系统的高并发报文处理、BPM流程引擎对接用友NCC/钉钉，还是港口GIS生产可视化系统，均属于典型的企业复杂业务流+技术集成场景。其在多个行业中完成‘从0到1’系统构建的经历，表明能快速理解业务本质并转化为技术方案，尤其适合需要打通异构系统、推动流程标准化的岗位。与JD中要求的微服务架构、跨系统集成、数据驱动决策等能力形成强映射。"},{"dimension":"教育背景","score":75,"comment":"初始学历为专科层次新闻采编，非科班出身，但后续通过鲁东大学计算机本科（2022-2024）实现专业补强，显示出强烈的学习驱动力和职业规划意识。结合其持有PMP认证，说明其注重系统化知识体系构建。尽管起点不高，但十年一线实战叠加持续教育投入，已实质性弥补理论短板，学习力远高于静态学历标签所能反映的水平。"},{"dimension":"稳定性","score":80,"comment":"整体跳槽频率合理，平均任期约2-3年，符合IT技术人员成长周期规律。关键点在于每次变动均有明显能力跃迁：早期驻场运维→中期独立开发→后期主导系统设计与团队协作。最近一段在格润富德任职两年半，负责企业信息化建设全过程，属深度参与型角色，离职动机若为寻求更大技术挑战则具合理性。无频繁短期跳槽记录，稳定性处于行业中上水平，背景调查需重点关注离职真实原因及上级评价一致性。"},{"dimension":"发展潜力","score":89,"comment":"具备显著的复合型人才潜质：既懂技术实现又理解业务流程，在BPM、结算、审单等多个领域积累垂直知识。其参与的项目从小型模块扩展至大型分布式平台，角色也从执行者逐步过渡到需求分析、任务分配甚至供应商管理，展现清晰的成长路径。未来2-3年有望成长为具备架构视野的技术负责人，若辅以系统性培养，可冲击技术总监层级。持续获取PMP、自学本科等行为印证其自我迭代意愿强烈，天花板较高。"},{"dimension":"团队协作","score":83,"comment":"简历明确提及‘跨部门沟通经验’、‘带小团队经验’、‘主持内部会议’等关键词，结合其在蓝凌BPM项目中协调用友、钉钉等多方系统的经历，证明其具备良好的协同推动力。自驱力强、结果导向突出，能在压力下推进问题解决。软技能表现均衡，虽未见大规模团队管理经验，但在中小型项目中已展现出影响力建设能力，组织融合度预期良好。"}],"penetration_report":{"career_trajectory":"【职业轨迹深度解析】王丹麒的职业发展呈现‘螺旋上升式’演进：始于柯莱特驻场运维开发，奠定扎实工程基础；转入神州泰岳接触大数据营销平台，拓宽数据维度认知；随后进入软通动力担任开发组长，首次承担任务分解与团队指导职责，完成从个体贡献者向轻量管理者的跨越。此后选择进入万达/融创中央预订系统，涉足高并发交易场景；再转向医院HIS、银行信用证审单等强合规性系统，锤炼严谨性与流程意识。2022年起聚焦企业级流程平台（BPM）与港口数字化，角色升级为需求梳理、系统定义与集成主导者，技术视野与业务抽象能力同步提升。整个路径显示其主动选择复杂度递增的项目环境，每一次切换都带来能力边界的拓展，背后是清晰的‘成为企业级系统构建者’的职业主线。","potential_growth":"【未来产出预测】入职前6个月，预计可在微服务治理、系统集成接口设计、生产问题快速定位等方面迅速产生价值，尤其在推动现有系统解耦、优化数据库性能、建立标准化日志监控体系上有直接输出。长期来看，2年内可独立主导一个中大型数字化平台的技术架构设计，并带动团队技术能力提升。其最大价值在于将过往多行业最佳实践进行迁移整合，推动组织内系统间协同效率跃升，潜在天花板为技术架构师或数字化产品负责人。","management_guide":"【管理与激励建议】应赋予其技术主导权与业务对话空间，避免仅作为编码执行者使用。激励方式宜采用‘挑战性任务+成果可见度’组合，例如让其牵头关键技术攻关或代表团队对外汇报。需注意其可能存在的过度追求技术完美倾向，引导其平衡交付节奏与系统稳健性。针对其非科班背景可能带来的理论盲区，建议安排定期技术分享与外部培训机会。管理上宜采用目标导向型授权模式，减少过程干预，激发其自驱力最大化释放。"},"detailed_qa":[{"question":"请详细描述你在蓝凌BPM系统中‘从零到一’梳理业务流程的具体方法论，如何确保流程定义被各业务部门接受？","intention":"考察意图：验证其真实参与深度及跨部门推动力","ideal_answer_signals":["访谈关键用户","绘制AS-IS/TO-BE流程图","组织流程评审会","与用友NCC字段映射规则","迭代调整机制"]},{"question":"在港口GIS系统开发中，你是如何处理实时数据（如TDEngine）与传统关系型数据库（Oracle）之间的数据同步与一致性问题的？","intention":"考察意图：检验其分布式系统设计能力与技术细节掌握程度","ideal_answer_signals":["CDC机制","Kafka消息队列缓冲","幂等处理","补偿事务","延迟容忍策略"]},{"question":"你提到‘带小团队经验’，请举例说明你如何分配任务、评估进度并处理成员间的冲突？","intention":"考察意图：评估其领导力真实性与团队管理成熟度","ideal_answer_signals":["WBS拆解","每日站会","Code Review机制","一对一沟通","任务优先级动态调整"]},{"question":"在中国银行票交所项目中，面对人行标准报文格式变更，你的应对流程是什么？如何保证系统兼容性？","intention":"考察意图：测试其在高监管环境下应急响应与系统可维护性设计能力","ideal_answer_signals":["版本灰度发布","报文解析层抽象","配置化路由","回归测试用例库","与中行联调机制"]},{"question":"你在多个项目中使用了低代码平台（如蓝凌BPM），你认为它与传统定制开发的核心边界在哪里？何时该用，何时不该用？","intention":"考察意图：判断其技术选型判断力与架构思维","ideal_answer_signals":["业务变化频率","流程标准化程度","集成复杂度","性能要求","可扩展性考量"]},{"question":"合生活APP结算系统涉及多方分润计算，请说明你是如何设计结算引擎以应对规则频繁变更的？","intention":"考察意图：评估其业务抽象能力与系统柔性设计水平","ideal_answer_signals":["规则引擎引入","脚本化配置","DSL定义","测试沙箱环境","差异对账机制"]},{"question":"你为何在2022年选择攻读计算机本科？这段学习对你实际工作产生了哪些具体影响？","intention":"考察意图：探究其学习动机真实性及知识转化能力","ideal_answer_signals":["补足算法短板","理解操作系统原理","提升文档规范性","课程项目应用实例"]},{"question":"在处理生产环境紧急故障时，你的标准排查路径是什么？能否举一个最复杂的线上问题定位案例？","intention":"考察意图：验证其抗压能力与问题解决方法论","ideal_answer_signals":["日志链追踪","监控指标关联分析","线程堆栈抓取","SQL执行计划审查","复现环境搭建"]},{"question":"你如何评价自己在前端（Vue+Element）与后端（Spring Cloud）之间的技术平衡？在全栈开发中更倾向哪个方向？","intention":"考察意图：了解其技术偏好与发展倾向","ideal_answer_signals":["关注用户体验闭环","偏好后端逻辑复杂度","希望深化某一领域","保持全栈视野"]},{"question":"如果你发现上级的技术决策存在明显缺陷，你会如何处理？请结合实际经历说明。","intention":"考察意图：评估其沟通影响力与组织政治敏感度","ideal_answer_signals":["数据佐证提案","私下沟通尝试","风险预判陈述","替代方案准备","尊重决策流程"]}],"strengths":["【亮点】全栈贯通能力：从前端Vue到后端Spring Cloud再到数据库优化与Linux运维，具备端到端交付能力","【亮点】复杂系统集成经验：成功对接用友NCC、钉钉、人行票交所等异构系统，展现强大适配力","【亮点】业务抽象能力强：在BPM、结算、审单等领域能将模糊需求转化为可执行技术方案","【亮点】自驱型学习者：在职攻读计算机本科并考取PMP，持续完善知识体系","【亮点】多行业跨界背景：横跨金融、医疗、地产、港口，积累丰富业务场景理解"],"weaknesses":["【风险】非科班出身可能导致底层理论薄弱：如操作系统、网络协议、算法设计等需重点考察","【风险】缺乏大规模高并发系统主导经验：虽参与过交易系统，但未见亿级流量处理实绩","【风险】管理经验限于‘小团队’：尚未经历完整团队组建与绩效考核实践，管理潜力待验证"],"suggestions":["【改进/培养建议】安排参与公司级架构评审会议，加速其融入技术决策层","【改进/培养建议】指定资深架构师作为导师，针对性补强系统设计方法论","【改进/培养建议】给予其主导一次跨部门系统整合项目的机会，锻炼全局协调能力"]}',unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),'analyzed','[]',0,'2026-01-28 06:32:24.599 +00:00',0,0,'recruitment_flow',1,'王丹麒','15098577313','danky.wang@foxMail.com','北京','2. 熟悉软件开发',12,NULL,NULL,NULL,'[{"startDate":"2021.3","endDate":"2022.2","company":"医院信息","position":"化HIS系统","description":[]},{"startDate":"2020.7","endDate":"2020.11","company":"医院信息化HIS系统2021.3-2022.2","position":"合生活APP结算系统","description":[]},{"startDate":"2019.04","endDate":"2020.07","company":"建行国结信用证智能","position":"审单项目","description":[]},{"startDate":"2017.1","endDate":"2017.8","company":"大数据","position":"精准营销平台","description":[]},{"startDate":"2014.12","endDate":"2016.12","company":"中国移动营业厅信息","position":"平台","description":[]},{"startDate":"2012.12","endDate":"2014.11","company":"中国移动北京分公司","position":"财务管理系统(FCM","description":[]},{"startDate":"2025.4","endDate":"至今","company":"某软件公司","position":"","description":[]},{"startDate":"2022.2","endDate":"2024.7","company":"格润富德农牧科技股份有限公司","position":"","description":[]},{"startDate":"2021.3","endDate":"2022.2","company":"山东中联佳裕软件股份有限公司","position":"","description":[]},{"startDate":"2017.9","endDate":"2020.11","company":"软通动力信息技术集团股份有限公司","position":"","description":[]},{"startDate":"2017.1","endDate":"2017.8","company":"北京神州泰岳智能数据有限公司","position":"","description":[]},{"startDate":"2012.12","endDate":"2016.12","company":"柯莱特信息科技(北京)有限责任公司","position":"","description":[]},{"startDate":"2008.9","endDate":"2011.7","company":"山东青年政治学院 新闻采编与制作","position":"鲁东大学 计算机科学与技术 2022.3-2024.7","description":[]},{"startDate":"2022.3","endDate":"2024.7","company":"鲁东大学 计算机科学与技术","position":"","description":[]}]','[{"startDate":"2022.3","endDate":"2024.7","school":"学院","major":"","degree":""}]','["Java","Python","Spring","MyBatis","jQuery","MySQL","Oracle","Redis","Bootstrap","Git","SVN","Linux","Apache","SpringMVC","RabbitMQ","Kafka","Shell"]',unistr('1. 具备出色的适应能力,融入新业务领域并掌握核