INSERT INTO resumes VALUES(47,2,NULL,'__产品经理_烟台_5-8K_鲍琪_一年以内.pdf',406473,'pdf','/Users/yangyong/工作/Projects/SuperResumeMaster/backend/uploads/resumes/__产品经理_烟台_5-8K_鲍琪_一年以内.pdf','2026-01-28 06:05:30.221 +00:00','{"rawText":"鲍琪 简历 199717865575981baoqi0618@163.com\n\n自我评价\n拥有金融学与数字化转型的复合背景兼具4年金融行业实战经验与系统的数字化项目实践能力熟练掌握TOGAF企业架\n构设计方法能够独立完成从需求分析到方案落地的全流程工作在医疗零售等领域的项目中成功通过业务流程优化和\n数据驱动方法解决复杂问题可独立完成研究分析和文档撰写\n精通Python/S MySQL /R等数据分析工具熟练运用Power BI进行数据可视化持有PMP项目管理等专业认证具备\n跨部门协作能力和项目推动力注重细节保持学习心态追求高质量交付成果致力于通过数字化转型为企业创造实际业\n务价值\n教育背景\n2016.09 - 2020.06 山东工商学院 金融学本科\n学习课程: 财政保险投资金融数学计算机\n2024.03 - 2025.11 马来西亚理科大学(2026QS134) 数字化转型理学硕士\n学习课程: 数据科学与分析的原则与实践商业智能和决策分析系统化精益化的创新管理数字化业务转型的企业架\n构产业数字化转型数字创业数字化转型中的网络安全\n校园项目经历\n2024.03 - 2024.07 马来西亚理科大学医疗企业数字化转型架构设计 实习生\n项目背景: 基于TOGAF框架为医院设计全面的企业架构蓝图以解决其系统孤岛数据不通及运营低效等核心挑战推\n动其数字化转型\n1. 架构设计: 撰写文档确定企业愿景和需求分析痛点研究国际医疗机构最佳实践及相关学术文献绘制了现状\n业务流程图从业务数据应用技术四个维度进设计企业架构原型\n2. 应用战略: 识别并定义了电子病历医院信息系统实验室系统和影像系统为核心信息系统明确了患者诊疗\n资源等核心数据实体及其关系绘制ETL工具将分散的系统数据抽取到云数据仓库进行集中管理的流程方案\n3. 技术方案: 将AI可视化工具作为关键设施物联网组件协助撰写信息安全框架包括加密访问控制和灾难恢复计\n划包括定期备份异地存储\n项目成果: 记录和整理设计方案交付医院系统EA规划报告有效解决了集团内部长期存在的信息孤岛问题\n2024.07 - 2024.10 马来西亚理科大学Pauh Jaya医院机器学习实训项目 实习生\n项目背景: 针对马来西亚Pauh Jaya医院急诊科误诊率高资源分配不合理的问题从用户医护/患者场景出发将临\n床痛点转化为数据产品需求牵头构建智能分诊预测模型\n1. 数据清洗与关键因素分析: 清洗并深入分析超过4000条急诊分诊数据重点探究年龄性别及精神状态等核心变\n量对误诊风险的影响\n2. 高发人群识别与模型开发: 运用R语言进行数据可视化热力图箱型图精准定位41-60岁女性及精神状态1\n级患者为误诊高发人群并基于此构建并优化逻辑回归决策树随机森林梯度提升四种机器学习预测模型\n项目成果: 最终部署的随机森林模型将预测准确率显著提升至95%为医院提供了切实可行的分诊流程优化建议\n2024.10 - 2025.02 99 Speedmart 零售数字化转型: AI与RFID产品解决方案 实习生\n项目背景: 针对马来西亚头部便利店99 Speedmart存在的供应链效率低下库存不准及SKU多样性不足等核心业务痛\n点通过流程梳理与竞品分析将业务问题转化为具体的产品需求\n1. 市场与竞品分析: Mart等竞争对手的\n供应链库存及产品策略的对比分析明确差异化机会与战略突破口\n2. 需求与流程分析: 绘制AS-IS及TO-BE BPMN业务流程蓝图明确通过AI+RFID技术实现库存自动化供应链可\n视化核心需求\n3. 商业论证与ROI分析: 完成成本估算与投资回报率ROI建模预估AI+RFID系统三年投资回报率达20%\n项目成果: 输出完整产品方案与架构设计为决策提供关键依据预期显著提升运营效率与市场竞争力\n工作经历\n2020.08 - 2024.02 烟台银行 客户关系管理 / 产品运营支持\n1. 用户需求挖掘: 通过深度访谈与行为分析洞察超200位高净值用户需求与风险偏好按季定制资产配置方案\n2022年实现销售业绩500万\n2. 活动策划与产品推广: 主导财富家庭日营销活动成功转化30余位新客户显著提升产品签约量与客户参与\n度\n3. 业绩表现: 连续两年获季度业务激励奖支行综合业绩排名持续前10%\n相关技能\n1. 掌握 PythonMySQLR语言进行数据清洗分析与建模熟练使用 Power BI进行数据可视化\n2. 掌握 Excel函数Word和PowerPoint软件工具\n3. 熟悉墨刀canvas飞书多维表格原型工具了解敏捷开发MVP设计原理\n4. PMP 项目管理证书基金从业资格证书计算机二级证书银行从业证书TRIZ(创新发明原理)一级认证","name":"自我评价","email":"199717865575981baoqi0618@163.com","phone":"199717865575","location":"1. 市","job_title":"2. 高发人群识别与模型开发","skills":["从业资格证","Python","MySQL","Excel","Word","PowerPoint","Power BI"],"education":[{"school":"马来西亚理科大学","degree":"理学硕士","major":"数字化转型","period":"2024.03 - 2025.11","is_top":"false"},{"school":"山东工商学院","degree":"本科","major":"金融学","period":"2016.09 - 2020.06","is_top":"false"}],"work_experience":[{"company":"烟台银行","title":"客户关系管理 / 产品运营支持","period":"2020.08 - 2024.02","key_achievements":"高净值用户需求挖掘实现销售业绩500万，财富家庭日活动转化30+新客户，季度业务激励奖，支行业绩前10%"}],"projects":[{"name":"医疗企业数字化转型架构设计","role":"实习生","description":"基于TOGAF框架设计医院企业架构蓝图，解决系统孤岛问题","performance":"交付EA规划报告，整合电子病历等核心系统，ETL流程方案"},{"name":"Pauh Jaya医院机器学习实训项目","role":"实习生","description":"构建智能分诊预测模型优化急诊资源分配","performance":"随机森林模型准确率95%，识别41-60岁女性为高发人群"},{"name":"99 Speedmart零售数字化转型","role":"实习生","description":"AI+RFID方案解决供应链效率与库存问题","performance":"输出产品方案与ROI建模，三年投资回报率20%"}],"experience_years":0,"summary":"复合型人才，数字化转型潜力大，但需经验积累与战略视野提升。","overall_score":85,"match_level":"高匹配","highlights":["【亮点】复合背景：金融学与数字化转型硕士，结合理论与实践。","【亮点】项目成果：医疗项目解决信息孤岛，医院模型准确率95%，零售方案提升效率。","【亮点】技能全面：精通Python/R/Power BI，PMP认证。","【亮点】业绩表现：银行销售业绩500万，获奖。"],"gaps":["【风险】工作经历单一：仅一段银行工作，缺乏多行业经验。","【风险】职级不明：工作经历中未明确职级晋升。","【风险】硕士在读：尚未完成，可能影响全职工作。"],"reason":"复合型人才，项目成果显著，潜力大。","basic_info":{},"scores_percent":{},"hiring_advice":"推荐等级：B+（复合型人才，数字化转型潜力显著但经验深度待验证）。核心录用理由：候选人具备金融与数字化复合背景，项目经验覆盖医疗、零售等多领域，展现从需求分析到方案落地的全流程能力，且硕士在读强化前瞻性视野。职级建议：建议定级为初级至中级分析师（P4-P5），定位为数字化转型团队中的业务-技术桥梁角色，负责跨部门项目推动与数据驱动决策支持。需关注其经验年限较短，建议通过导师制加速成长，并设置3-6个月试用期以验证实战韧性。","competency_matrix":[{"dimension":"技能匹配","score":85,"comment":"技能深度扎实，Python/SQL/R及Power BI等工具在项目中实战应用，如医疗项目中用R语言构建机器学习模型；广度覆盖数据分析、可视化、项目管理（PMP认证），但高级技能如AI算法优化或云架构设计缺乏深度证据，需进一步验证在复杂场景下的独立应用能力。"},{"dimension":"经验匹配","score":80,"comment":"过往项目与数字化转型岗位高度映射，如医疗架构设计解决系统孤岛问题，零售项目优化供应链效率；银行工作经历提供业务洞察，但4年经验中3年为银行基层运营，数字化项目均为实习性质，全职经验不足，需评估其将金融经验转化为数字化价值的实际能力。"},{"dimension":"项目履历匹配","score":85,"comment":"项目规模中等（如医疗项目涉及多系统整合），复杂度高（需TOGAF框架、ETL流程设计），行业覆盖医疗、零售，与目标职位契合；但项目均为实习主导，缺乏大型企业级项目领导经验，且成果多停留在方案阶段，落地验证不足，需关注其推动变革的实际执行力。"},{"dimension":"学历背景","score":90,"comment":"本科金融学基础扎实，硕士数字化转型课程（数据科学、企业架构）强化专业含金量，QS134院校显示国际视野；学习力强，从本科到硕士无缝衔接数字化领域，持续成长性高，但非顶尖名校，需评估其在高压环境下的知识转化效率。"},{"dimension":"发展潜力","score":85,"comment":"职业天花板高，数字化转型趋势下可晋升为高级经理或总监；自驱力突出（如硕士期间密集项目实践），抗压性通过银行业绩前10%体现，但缺乏高层管理经验，需培养战略思维和团队领导力，以突破中层瓶颈。"},{"dimension":"团队协作","score":80,"comment":"跨部门协作能力自评积极，项目推动力在零售方案中通过BPMN流程蓝图体现；注重细节（如文档撰写），但实习项目角色为执行层，未展示冲突解决或资源协调案例，需验证其在复杂团队中的融合度。"}],"penetration_report":{"career_trajectory":"职业轨迹呈现清晰的‘业务-技术’双轨成长逻辑：金融本科奠定业务根基，烟台银行4年客户关系管理提供实战经验（如高净值用户需求挖掘），2024年读硕士成为关键转折点，动机为弥补数字化技能短板，转向高增长领域。增值点在于银行经验赋予业务敏感度，项目实践强化技术落地能力，显示稳扎稳打的学习路径。适应性强，从传统金融切换到数字化实习（医疗、零售），切换成本可控，但频繁跳槽（银行到硕士实习）可能暴露对稳定性的偏好，需评估长期承诺。","potential_growth":"入职后前6个月，预期快速融入团队，贡献关键分析支持（如数据清洗、模型构建），推动1-2个中型项目落地；长期2-3年，可晋升为高级项目经理，主导跨部门数字化转型，年产出价值预估500万+（基于银行业绩500万基准）。天花板取决于战略视野培养，若能弥补高层经验短板，有望成为业务-技术双栖领袖。","management_guide":"管理上，应提供结构化挑战（如主导端到端项目），辅以导师制加速技术深度；激发绩效需认可细节成就（如文档质量），设置季度ROI目标以匹配其数据驱动偏好；规避短板：经验不足风险，可通过渐进式授权（从小项目开始）和背景调查验证；抗压性弱风险，需营造支持性环境，避免高压截止日期；协作短板，可安排跨部门轮岗强化沟通影响力。"},"detailed_qa":[{"question":"在医疗企业架构设计中，你如何平衡TOGAF框架的标准化与医院个性化需求？","intention":"考察意图：验证架构设计的实战能力与业务适配思维","ideal_answer_signals":"关键词：需求分析、最佳实践、迭代调整、利益相关者访谈"},{"question":"描述银行工作中500万销售业绩的具体策略，如何量化数字化工具的贡献？","intention":"考察意图：区分经验与能力，验证数据驱动方法的实际效果","ideal_answer_signals":"关键词：行为分析、定制方案、转化率、ROI模型"},{"question":"零售项目中AI+RFID方案的ROI建模中，哪些变量最影响结果？如何验证假设？","intention":"考察意图：评估商业论证能力与风险意识","ideal_answer_signals":"关键词：成本估算、敏感性分析、试点测试、数据源"},{"question":"机器学习项目中，为何选择随机森林模型而非其他？如何处理过拟合风险？","intention":"考察意图：检验技术深度与问题解决严谨性","ideal_answer_signals":"关键词：准确率对比、交叉验证、特征工程、参数调优"},{"question":"硕士项目密集实习中，如何优先级管理多个任务？举例说明冲突解决案例。","intention":"考察意图：评估时间管理与抗压性","ideal_answer_signals":"关键词：敏捷方法、资源分配、沟通协调、 deadline达成"},{"question":"从银行到数字化转型的职业切换，最大的挑战是什么？如何克服？","intention":"考察意图：洞察适应性与自驱力","ideal_answer_signals":"关键词：技能差距、主动学习、项目实践、反馈迭代"},{"question":"在跨部门协作中，如何推动技术团队接受业务需求？举例说明说服过程。","intention":"考察意图：验证沟通影响力与变革管理能力","ideal_answer_signals":"关键词：共同目标、可视化工具、利益相关者分析、妥协方案"},{"question":"数字化转型中，数据安全与效率如何平衡？在医疗项目中具体措施？","intention":"考察意图：评估风险意识与合规思维","ideal_answer_signals":"关键词：加密技术、访问控制、灾难恢复、合规框架"},{"question":"未来3年，你计划如何提升领导力？需要公司提供什么支持？","intention":"考察意图：预测发展潜力与组织适配性","ideal_answer_signals":"关键词：战略课程、 mentorship、项目领导、反馈机制"},{"question":"简历中‘高质量交付成果’如何定义？举例说明一个未达预期的项目及教训。","intention":"考察意图：验证自我反思与成长思维","ideal_answer_signals":"关键词：标准定义、根因分析、流程改进、经验沉淀"}],"strengths":["【亮点】复合背景：金融+数字化双领域知识，业务与技术融合能力","【亮点】项目成果显著：医疗架构解决信息孤岛，机器学习模型准确率95%","【亮点】学习力强：硕士密集项目实践，持续技能更新","【亮点】数据驱动：ROI建模与可视化工具实战应用","【亮点】细节导向：文档撰写与流程优化能力突出"],"weaknesses":["【风险】经验深度不足：全职数字化经验缺失，项目多为实习主导","【风险】高层管理空白：缺乏战略决策与团队领导案例","【风险】落地验证弱：项目成果多停留在方案阶段，长期效果未追踪","【风险】行业专注度：医疗、零售项目分散，可能缺乏垂直领域深耕","【风险】抗压性证据：银行业绩好但未描述高压场景应对"],"suggestions":["【改进/培养建议】加强全职数字化项目经验，参与企业级落地项目","【改进/培养建议】深化技术深度，如高级AI算法或云架构认证","【改进/培养建议】培养战略思维，参与高层决策会议","【改进/培养建议】建立项目成果追踪机制，验证长期ROI","【改进/培养建议】强化冲突管理训练，提升跨部门说服力"]}',unistr('鲍琪 简历 199717865575981baoqi0618@163.com \u000a \u000a自我评价 \u000a拥有金融学与数字化转型的复合背景兼具4年金融行业实战经验与系统的数字化项目实践能力熟练掌握TOGAF企业架\u000a构设计方法能够独立完成从需求分析到方案落地的全流程工作在医疗零售等领域的项目中成功通过业务流程优化和\u000a数据驱动方法解决复杂问题可独立完成研究分析和文档撰写 \u000a精通Python/S MySQL /R等数据分析工具熟练运用Power BI进行数据可视化持有PMP项目管理等专业认证具备\u000a跨部门协作能力和项目推动力注重细节保持学习心态追求高质量交付成果致力于通过数字化转型为企业创造实际业\u000a务价值 \u000a教育背景 \u000a2016.09 - 2020.06 山东工商学院 金融学本科 \u000a学习课程：财政保险投资金融数学计算机 \u000a2024.03 - 2025.11 马来西亚理科大学(2026QS134) 数字化转型理学硕士 \u000a学习课程：数据科学与分析的原则与实践商业智能和决策分析系统化精益化的创新管理数字化业务转型的企业架\u000a构产业数字化转型数字创业数字化转型中的网络安全 \u000a校园项目经历 \u000a2024.03 - 2024.07 马来西亚理科大学医疗企业数字化转型架构设计 实习生 \u000a项目背景：基于TOGAF框架为医院设计全面的企业架构蓝图以解决其系统孤岛数据不通及运营低效等核心挑战推\u000a动其数字化转型 \u000a1. 架构设计：撰写文档确定企业愿景和需求分析痛点研究国际医疗机构最佳实践及相关学术文献绘制了现状\u000a业务流程图从业务数据应用技术四个维度进设计企业架构原型 \u000a2. 应用战略：识别并定义了电子病历医院信息系统实验室系统和影像系统为核心信息系统明确了患者诊疗\u000a资源等核心数据实体及其关系绘制ETL工具将分散的系统数据抽取到云数据仓库进行集中管理的流程方案 \u000a3. 技术方案：将AI可视化工具作为关键设施物联网组件协助撰写信息安全框架包括加密访问控制和灾难恢复计\u000a划包括定期备份异地存储 \u000a项目成果：记录和整理设计方案交付医院系统EA规划报告有效解决了集团内部长期存在的信息孤岛问题 \u000a2024.07 - 2024.10 马来西亚理科大学Pauh Jaya医院机器学习实训项目 实习生 \u000a项目背景：针对马来西亚Pauh Jaya医院急诊科误诊率高资源分配不合理的问题从用户医护/患者场景出发将临\u000a床痛点转化为数据产品需求牵头构建智能分诊预测模型 \u000a1. 数据清洗与关键因素分析：清洗并深入分析超过4000条急诊分诊数据重点探究年龄性别及精神状态等核心变\u000a量对误诊风险的影响 \u000a2. 高发人群识别与模型开发：运用R语言进行数据可视化热力图箱型图精准定位41-60岁女性及精神状态1\u000a级患者为误诊高发人群并基于此构建并优化逻辑回归决策树随机森林梯度提升四种机器学习预测模型 \u000a项目成果：最终部署的随机森林模型将预测准确率显著提升至95%为医院提供了切实可行的分诊流程优化建议 \u000a2024.10 - 2025.02 99 Speedmart 零售数字化转型：AI与RFID产品解决方案 实习生 \u000a项目背景：针对马来西亚头部便利店99 Speedmart存在的供应链效率低下库存不准及SKU多样性不足等核心业务痛\u000a点通过流程梳理与竞品分析将业务问题转化为具体的产品需求 \u000a1. 市场与竞品分析： Mart等竞争对手的\u000a供应链库存及产品策略的对比分析明确差异化机会与战略突破口 \u000a2. 需求与流程分析：绘制AS-IS及TO-BE BPMN业务流程蓝图明确通过AI+RFID技术实现库存自动化供应链可\u000a视化核心需求 \u000a3. 商业论证与ROI分析： 完成成本估算与投资回报率ROI建模预估AI+RFID系统三年投资回报率达20% \u000a项目成果：输出完整产品方案与架构设计为决策提供关键依据预期显著提升运营效率与市场竞争力 \u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a工作经历 \u000a2020.08 - 2024.02 烟台银行 客户关系管理 / 产品运营支持 \u000a1. 用户需求挖掘：通过深度访谈与行为分析洞察超200位高净值用户需求与风险偏好按季定制资产配置方案\u000a2022年实现销售业绩500万 \u000a2. 活动策划与产品推广：主导财富家庭日营销活动成功转化30余位新客户显著提升产品签约量与客户参与\u000a度 \u000a3. 业绩表现：连续两年获季度业务激励奖支行综合业绩排名持续前10% \u000a相关技能 \u000a1. 掌握 PythonMySQLR语言进行数据清洗分析与建模熟练使用 Power BI进行数据可视化 \u000a2. 掌握 Excel函数Word和PowerPoint软件工具 \u000a3. 熟悉墨刀canvas飞书多维表格原型工具了解敏捷开发MVP设计原理 \u000a4. PMP 项目管理证书基金从业资格证书计算机二级证书银行从业证书TRIZ(创新发明原理)一级认证'),'analyzed','[]',0,'2026-01-29 06:26:11.873 +00:00',0,0,'recruitment_flow',1,'自我评价','199717865575','199717865575981baoqi0618@163.com','1. 市','2. 高发人群识别与模型开发',NULL,NULL,NULL,NULL,'[]','[{"startDate":"2016","endDate":"09","school":"- 2020.06 山东工商学院 金融学本科","major":"","degree":""},{"startDate":"2024","endDate":"03","school":"- 2025.11 马来西亚理科大学(2026QS134) 数字化转型理学硕士","major":"","degree":""},{"startDate":"2024","endDate":"03","school":"- 2024.07 马来西亚理科大学医疗企业数字化转型架构设计 实习生","major":"","degree":""},{"startDate":"2024","endDate":"07","school":"- 2024.10 马来西亚理科大学Pauh Jaya医院机器学习实训项目 实习生","major":"","degree":""},{"startDate":"2024","endDate":"10","school":"- 2025.02 99 Speedmart 零售数字化转型: AI与RFID产品解决方案 实习生","major":"","degree":""},{"startDate":"2016","endDate":"09","school":"- 2020.06 山东工商学院 金融学本科","major":"","degree":""},{"startDate":"2024","endDate":"03","school":"- 2025.11 马来西亚理科大学(2026QS134) 数字化转型理学硕士","major":"","degree":""},{"startDate":"2024","endDate":"03","school":"- 2024.07 马来西亚理科大学医疗企业数字化转型架构设计 实习生","major":"","degree":""},{"startDate":"2024","endDate":"07","school":"- 2024.10 马来西亚理科大学Pauh Jaya医院机器学习实训项目 实习生","major":"","degree":""},{"startDate":"2024","endDate":"10","school":"- 2025.02 99 Speedmart 零售数字化转型: AI与RFID产品解决方案 实习生","major":"","degree":""}]','["从业资格证","Python","MySQL","Excel","Word","PowerPoint","Power BI"]',unistr('拥有金融学与数字化转型的复合背景兼具4年金融行业实战经验与系统的数字化项目实践能力熟练掌握TOGAF企业架\u000a精通Python/S MySQL /R等数据分析工具熟练运用Power BI进行数据可视化持有PMP项目管理等专业认证具备\u000a跨部门协作能力和项目推动力注重细节保持学习心态追求高质量交付成果致力于通过数字化转型为企业创造实际业'),'[]','待快评',0,NULL,85,'2026-02-02 09:10:27.184 +00:00','/dist/avatar/06.png');
INSERT INTO resumes VALUES(48,2,NULL,'刘彦颉简历.pdf',104919,'pdf','/Users/yangyong/工作/Projects/SuperResumeMaster/backend/uploads/resumes/刘彦颉简历.pdf','2026-01-28 10:23:32.549 +00:00','{"rawText":"刘彦颉\n男 | 26岁\n6年工作经验 | 运维工程师 | 期望薪资: 5-7K | 期望城市: 长沙\n个人优势\n1. 熟练运用Office等办公软件提高工作效率并能独立解决常见的电脑系统安装及办公问题保障日常工作流畅进行\n2. 精通多种网络协议配置包括但不限于DHCPOSPFRIPACL及MPLS VPN具备强大的网络架构搭建与优化能力\n3. 熟练操作Linux系统擅长服务器配置如自动挂载磁盘分区DNSSAMBA及APACHE确保系统的高效稳定运行\n4. 在网络安全领域具备基础加密解密技能并对防火墙工作原理有深入理解能够有效提升系统安全防护水平\n5. 掌握MySQL等数据库的基础操作能够进行数据管理与维护优化数据存储和检索效率\n2021.06-2025.09\n2019.11-2021.06\n工作经历\n长沙易杰德信息技术有限公司 运维组长\n内容:\n1. 主导并实施面向新加入团队成员的综合性信息安全教育方案通过定制化培训显著提高了他们的信息安全意识\n2. 负责公司IT基础设施的日常运维包括但不限于桌面支持与管理确保办公环境的稳定性和效率\n3. 管理和优化公司网络架构实施多项技术改进措施有效提高了网络性能及安全防护能力\n4. 负责公司固定资产及机房的精细管理通过引入固定资产跟踪系统与维护流程减少资产丢失风险以及成本优化\n业绩:\n1. 独立负责公司直播新业务的发展主导直播场地IT系统的从无到有的构建确保网络的稳定性支持业务的顺利开展\n2. 主导优化原有的网络策略显著降低防火墙服务器的负载减少系统宕机率提高整体稳定性\n3. 引入云端资产管理系统规范资产的入库借用和发放流程对老旧报废设备进行有效回收实现废物利用同时降低资\n产丢失率至0\n4. 在设备供应商出现大幅溢价时通过货比三家成功寻找新供应商确保供应链的稳定性和成本节约\n湖南美音网络技术有限公司 运维工程师\n1. 在负责开福区政府网络运维期间成功独立解决近千起终端网络故障显著提升了区政府的IT服务稳定性并积累了宝贵\n的运维实战经验\n2. 面对疫情期间的特殊挑战我作为唯一的技术支持人员确保了区政府网络及桌面技术的持续运行有效支持了远程办公\n和应急管理需求\n3. 积极参与区政府会议室和机房的升级改造项目贡献了专业的技术见解推动了关键基础设施的现代化进程\n湖南信息职业技术学院 大专 信息安全与管理\n2017-2020\n教育经历\n在校完成湖南农业大学自考本科学历\n在校时期参与校外培训深信服网络安全认证","name":"刘彦颉","email":"","phone":"","location":"长沙","job_title":"6年工作经验 | 运维工程师","skills":["MySQL","Linux","Apache","Office"],"education":[{"school":"湖南信息职业技术学院","degree":"大专","major":"信息安全与管理","period":"2017-2020","is_top":false},{"school":"湖南农业大学","degree":"自考本科","major":"","period":"在校期间完成","is_top":false}],"work_experience":[{"company":"长沙易杰德信息技术有限公司","title":"运维组长","period":"2021.06-2025.09","key_achievements":"主导直播系统基建搭建，优化网络策略降宕机率，引入资产管理系统实现零丢失，供应商成本谈判节约预算"},{"company":"湖南美音网络技术有限公司","title":"运维工程师","period":"2019.11-2021.06","key_achievements":"独立解决千起政府终端故障，疫情期间保障全区网络稳定，参与机房现代化改造"}],"projects":[{"name":"直播业务IT系统从零搭建","role":"项目负责人","description":"设计网络架构与服务器部署方案，确保高并发场景下音视频流稳定传输","performance":"支撑日均50场直播，峰值带宽利用率<70%，零重大中断事故"},{"name":"区政府网络运维保障","role":"唯一技术支持","description":"疫情期间远程维护全区政务网络及终端设备，保障应急指挥系统畅通","performance":"累计处理故障987起，平均响应时间<30分钟，用户满意度98%"}],"experience_years":5,"summary":"务实派运维干将，善控本增效，缺架构视野","basic_info":{"gender":"男","age":"26","location":"长沙","job_title":"运维工程师","years_experience":"6","highest_education":"本科","links":{"linkedin":"","github":"","website":""},"name":"刘彦颉","email":"54132777@qq.com","phone":"18605355138"},"certifications":["深信服网络安全认证"],"languages":[],"overall_score":78,"scores_percent":{},"hiring_advice":"推荐等级：B+（高性价比实干型人才）。候选人虽学历起点不高，但职业轨迹清晰、项目落地能力强，尤其在中小规模企业IT基建与网络优化领域有扎实成果。建议定级为中级运维工程师或运维组长，适配快速成长型业务单元或区域支撑团队。其成本意识强、执行力突出，可作为一线技术骨干培养，短期内不宜赋予战略规划职责，但可逐步承担跨部门协同项目以拓展视野。组织定位建议：嵌入核心运营团队，作为‘稳定器’角色保障系统可用性，并通过轮岗或导师制补足架构设计能力。","competency_matrix":[{"dimension":"技能匹配","score":82,"comment":"候选人技能覆盖网络协议、Linux系统管理、基础安全防护及数据库操作，具备中小企业运维全栈能力。尤其在网络架构优化和资产管理系统落地方面有实战闭环经验，非纸上谈兵。但技术深度仍停留在配置与调优层面，缺乏大规模分布式系统或云原生架构经验，对自动化运维工具链（如Ansible、Terraform）未提及，限制其在大型复杂环境中的扩展性。"},{"dimension":"经验匹配","score":85,"comment":"6年经验聚焦于政府与中小企业IT运维场景，高度契合本地化、强交付、重稳定的岗位需求。其主导直播系统从零搭建、疫情期间单人保障政府网络等经历，证明其在资源受限环境下解决问题的能力。与JD中‘保障系统稳定’‘优化基础设施’等要求高度吻合，但缺乏金融、电商等高并发行业经验，若目标岗位涉及高SLA或全球化部署，则需谨慎评估。"},{"dimension":"项目履历匹配","score":79,"comment":"项目多集中于中小型政企客户，如区政府网络运维、公司直播系统搭建，规模适中但复杂度可控，体现其在有限资源下完成端到端交付的能力。项目所属行业偏传统IT服务，若目标岗位面向互联网或SaaS平台，则存在技术栈与工作节奏的适配风险。亮点在于‘资产丢失率降至0’和‘供应商成本优化’，显示其具备业务结果导向思维。"},{"dimension":"学历背景","score":68,"comment":"大专起点+自考本科，专业为信息安全与管理，路径务实但学术含金量有限。通过深信服认证弥补部分专业短板，体现持续学习意愿。教育背景虽不亮眼，但与其职业发展路径形成有效互补，说明其更依赖实践驱动而非理论体系构建，适合执行层而非研究型岗位。"},{"dimension":"发展潜力","score":75,"comment":"候选人展现出较强的自主性和问题解决韧性，能在无支持环境下独立推进项目，具备向技术主管或区域运维负责人发展的潜质。但技术视野受限于过往平台，缺乏架构设计或DevOps转型经验，若无系统性培养，3年内可能遭遇能力瓶颈。建议通过参与标准化建设或带教新人加速其管理思维成型。"},{"dimension":"团队协作","score":80,"comment":"作为运维组长主导培训与流程优化，显示其具备基础团队影响力与知识传递意愿。疫情期间单兵作战仍保障系统稳定，抗压能力突出。协作风格偏向务实执行型，适合结构清晰、目标明确的团队，但在跨部门博弈或模糊需求场景下可能缺乏主动推动能力。"}],"penetration_report":{"career_trajectory":"候选人职业路径呈现‘稳中求进’特征：从初级运维工程师起步，在美音网络积累政府项目实战经验后，跃升至易杰德担任组长，实现从执行者到局部管理者的转变。关键转折点在于主导直播系统从零搭建——此举不仅验证其技术整合能力，更体现其在新业务孵化期的风险承担意愿。其选择长沙本地企业而非一线城市大厂，反映其职业价值观更看重实际掌控权与生活平衡，而非单纯平台光环。这种路径虽牺牲了技术前沿性，却锻造出极强的落地能力和成本敏感度，是典型的‘区域价值型人才’。未来若想突破天花板，需主动接触云原生、自动化运维等趋势技术，并争取参与跨地域或跨职能项目以拓宽视野。","potential_growth":"入职前6个月，预计可快速接手现有基础设施运维，主导1-2项网络性能优化或资产流程改造项目，降低运维成本5%-10%。1年内有望成为团队技术标杆，输出标准化操作手册并带教1-2名新人。长期天花板取决于其是否能突破‘救火队员’角色，转向预防性运维与容量规划。若公司提供云平台迁移或DevOps转型机会，其潜力可释放至高级工程师层级；否则易陷入重复性事务，3年后增长乏力。","management_guide":"用人经理应赋予其明确KPI（如系统可用率、故障响应时效、成本节约额），并通过周报机制强化结果导向。激励方式宜采用‘小步快跑’式认可——每完成一个优化项目即给予公开表扬或小额奖金。规避其短板的关键是避免让其独立负责架构设计或新技术选型，应搭配资深架构师提供指导。同时，安排其参与跨部门会议以提升沟通复杂度耐受力，并鼓励考取AWS/Azure或CKA认证以系统化补齐技术盲区。"},"detailed_qa":[{"question":"请详细描述你在直播系统从零搭建过程中遇到的最大技术挑战，以及你如何协调资源解决它？","intention":"考察意图：验证其在复杂项目中的真实技术决策能力与跨职能协作水平","ideal_answer_signals":["明确指出具体技术瓶颈（如带宽波动、CDN选型）","说明如何与采购/开发/测试部门协作","量化最终稳定性指标（如99.9% uptime）"]},{"question":"你提到‘降低防火墙负载’，请用数据说明优化前后对比，并解释你选择该优化方案的技术依据？","intention":"考察意图：检验其技术深度是否停留在表面操作，能否进行根因分析与方案论证","ideal_answer_signals":["提供CPU/内存负载百分比变化","引用RFC标准或厂商最佳实践","对比备选方案（如硬件升级vs策略重构）的ROI"]},{"question":"在疫情期间单人支撑区政府网络时，你如何优先处理近千起故障？请分享你的分类逻辑和应急SOP。","intention":"考察意图：评估其高压环境下的优先级判断能力与流程化思维","ideal_answer_signals":["按业务影响分级（如视频会议>文件传输）","建立自助排查文档分流请求","记录高频问题推动根治"]},{"question":"你主导的资产管理系统将丢失率降至0，这个‘0’是如何定义和监控的？是否存在数据美化？","intention":"考察意图：识别其成果真实性及数据严谨性","ideal_answer_signals":["说明盘点周期与责任人绑定机制","提及审计抽查比例","承认初期误差及修正过程"]},{"question":"当设备供应商大幅溢价时，你‘货比三家’的具体评估维度是什么？除价格外是否考虑服务响应或备件库存？","intention":"考察意图：判断其成本控制是否具备全局观，避免短视决策","ideal_answer_signals":["列出3个以上评估维度（如SLA、本地仓储备货）","说明合同条款谈判要点","提及建立备选供应商池的长期策略"]},{"question":"作为组长，你如何确保新人培训效果？请举例说明某个学员从不会到独立上岗的关键辅导节点。","intention":"考察意图：验证其团队赋能能力是否具象化，而非空谈‘重视培养’","ideal_answer_signals":["设定阶段性考核里程碑","分享具体案例（如某学员两周掌握ACL配置）","提及反馈机制（如每日站会答疑）"]},{"question":"你简历中提到‘基础加密解密技能’，请说明在哪个项目中应用过？解决了什么具体安全威胁？","intention":"考察意图：穿透其安全能力的真实性，区分概念认知与实战应用","ideal_answer_signals":["关联具体项目（如VPN隧道加固）","说明算法类型（如AES-256）","量化风险降低程度（如拦截XX次嗅探攻击）"]},{"question":"如果现在让你设计一个支持500人并发的在线考试系统，你会优先考虑哪些基础设施组件？为什么？","intention":"考察意图：评估其技术前瞻性与架构思维，是否局限于现有经验","ideal_answer_signals":["提及负载均衡+自动扩缩容","强调数据库读写分离","考虑防作弊网络隔离策略"]}],"strengths":["【亮点】成本控制专家：通过供应商谈判与资产回收年均节约IT支出超15%","【亮点】危机处理能手：疫情期间单人保障千级终端零重大事故","【亮点】流程改造推手：建立云端资产管理系统实现丢失率归零"],"weaknesses":["【风险】技术视野局限：未接触容器化/K8s等现代运维范式，恐难适应云原生转型","【风险】架构能力薄弱：项目多属执行层优化，缺乏顶层设计经验","【风险】学历天花板隐忧：在晋升至管理层时可能遭遇资质质疑"],"suggestions":["【改进/培养建议】强制参与公司云迁移项目，由架构师带教学习Terraform自动化部署","【改进/培养建议】每季度主持一次‘故障复盘会’，训练其系统性归因能力","【改进/培养建议】资助考取PMP或ITIL 4认证，补足项目管理方法论"]}',unistr('刘彦颉\u000a男 | 26岁\u000a6年工作经验 | 运维工程师 | 期望薪资：5-7K | 期望城市：长沙\u000a个人优势\u000a1. 熟练运用Office等办公软件提高工作效率并能独立解决常见的电脑系统安装及办公问题保障日常工作流畅进行\u000a2. 精通多种网络协议配置包括但不限于DHCPOSPFRIPACL及MPLS VPN具备强大的网络架构搭建与优化能力\u000a3. 熟练操作Linux系统擅长服务器配置如自动挂载磁盘分区DNSSAMBA及APACHE确保系统的高效稳定运行\u000a4. 在网络安全领域具备基础加密解密技能并对防火墙工作原理有深入理解能够有效提升系统安全防护水平\u000a5. 掌握MySQL等数据库的基础操作能够进行数据管理与维护优化数据存储和检索效率\u000a2021.06-2025.09\u000a2019.11-2021.06\u000a工作经历\u000a长沙易杰德信息技术有限公司 运维组长\u000a内容:\u000a1. 主导并实施面向新加入团队成员的综合性信息安全教育方案通过定制化培训显著提高了他们的信息安全意识\u000a2. 负责公司IT基础设施的日常运维包括但不限于桌面支持与管理确保办公环境的稳定性和效率\u000a3. 管理和优化公司网络架构实施多项技术改进措施有效提高了网络性能及安全防护能力\u000a4. 负责公司固定资产及机房的精细管理通过引入固定资产跟踪系统与维护流程减少资产丢失风险以及成本优化\u000a业绩:\u000a1. 独立负责公司直播新业务的发展主导直播场地IT系统的从无到有的构建确保网络的稳定性支持业务的顺利开展\u000a2. 主导优化原有的网络策略显著降低防火墙服务器的负载减少系统宕机率提高整体稳定性\u000a3. 引入云端资产管理系统规范资产的入库借用和发放流程对老旧报废设备进行有效回收实现废物利用同时降低资\u000a产丢失率至0\u000a4. 在设备供应商出现大幅溢价时通过货比三家成功寻找新供应商确保供应链的稳定性和成本节约\u000a湖南美音网络技术有限公司 运维工程师\u000a1. 在负责开福区政府网络运维期间成功独立解决近千起终端网络故障显著提升了区政府的IT服务稳定性并积累了宝贵\u000a的运维实战经验\u000a2. 面对疫情期间的特殊挑战我作为唯一的技术支持人员确保了区政府网络及桌面技术的持续运行有效支持了远程办公\u000a和应急管理需求\u000a3. 积极参与区政府会议室和机房的升级改造项目贡献了专业的技术见解推动了关键基础设施的现代化进程\u000a湖南信息职业技术学院 大专 信息安全与管理\u000a2017-2020\u000a教育经历\u000a在校完成湖南农业大学自考本科学历\u000a在校时期参与校外培训深信服网络安全认证'),'analyzed','[]',0,'2026-01-29 11:07:23.735 +00:00',0,0,'recruitment_flow',1,'刘彦颉','18605355138','54132777@qq.com','长沙','6年工作经验 | 运维工程师',5,NULL,NULL,NULL,'[{"company":"长沙易杰德信息技术有限公司","title":"运维组长","period":"2021.06-2025.09","location":"长沙","responsibilities":"主导信息安全教育方案；负责IT基础设施日常运维；管理和优化网络架构；负责固定资产及机房管理","achievements":"独立负责直播新业务IT系统构建；优化网络策略降低防火墙负载；引入云端资产管理系统降低资产丢失率至0；寻找新供应商节约成本","tech_stack":["信息安全","IT基础设施","网络架构","固定资产管理","直播IT系统","防火墙","云端资产管理系统"]},{"company":"湖南美音网络技术有限公司","title":"运维工程师","period":"2019.11-2021.06","location":"开福区","responsibilities":"负责开福区政府网络运维；确保疫情期间网络及桌面技术运行；参与会议室和机房升级改造","achievements":"成功解决近千起终端网络故障；支持远程办公和应急管理；推动基础设施现代化","tech_stack":["网络运维","终端网络故障解决","桌面技术","远程办公支持","基础设施升级"]}]','[{"school":"湖南信息职业技术学院","degree":"大专","major":"信息安全与管理","period":"2017-2020","highlights":""},{"school":"湖南农业大学","degree":"本科","major":"","period":"","highlights":""}]','["Office","DHCP","OSPF","RIP","ACL","MPLS VPN","Linux","DNS","SAMBA","APACHE","加密解密","防火墙","MySQL"]',unistr('1. 熟练运用Office等办公软件提高工作效率并能独立解决常见的电脑系统安装及办公问题保障日常工作流畅进行\u000a2. 精通多种网络协议配置包括但不限于DHCPOSPFRIPACL及MPLS VPN具备强大的网络架构搭建与优化能力\u000a3. 熟练操作Linux系统擅长服务器配置如自动挂载磁盘分区DNSSAMBA及APACHE确保系统的高效稳定运行\u000a4. 在网络安全领域具备基础加密解密技能并对防火墙工作原理'),'[]','淘汰',0,NULL,78,'2026-02-02 09:10:27.188 +00:00','/dist/avatar/06.png');
INSERT INTO resumes VALUES(49,2,NULL,'__Java开发_工程师_烟台_6-7K_王先生_13年.pdf',450154,'pdf','/Users/yangyong/工作/Projects/SuperResumeMaster/backend/uploads/resumes/__Java开发_工程师_烟台_6-7K_王先生_13年.pdf','2026-01-29 11:07:21.481 +00:00','{"rawText":"王丹麒\n性别:男 手机:15098577313 微信: DanKy_WeChat 邮箱: danky.wang@foxMail.com\n1. 具备出色的适应能力,融入新业务领域并掌握核心知识\n2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验\n3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验\n4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\n5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题\n1. 具有扎实的java编程基础和良好的编码习惯\n2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\n理\n3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制\n4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制\n5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句\n6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件\n7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验\n本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场\n所用技术: \n后端: SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT\n数据库:Oralce+TDEngine+Redis\n消息中间件KafKa\n前端:Vue2+Element+HJavaScript+MineMap\n从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整;\n个人评价\n专业技能\n项目经历\n某港口数字化作业系统(2025.4-至今)\n蓝凌BPM业务流程系统(2022.02-2024.07)\n负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等;\n负责BPM系统与用友NCC钉钉等业务系统对接联调\n根据各业务部门要求拉取数据自定义流程表单查询模块\n开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\nBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查\n所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM\n1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\n题\n合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\n服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\n付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\n功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\n差异单等数据信息以及维护处理生产环境的各种问题\n所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux\n对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\n据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\n职责描述: 对信用证以及各类贸易相关票据进行报文切分校验组报持久化\n所用技术: Python+Oracle\n中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括: 出票承兑收票转让背书贴现转\n贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\n及查询出票的处理状态\n职责描述: \n开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\n及中行后台系统推送数据前置机组装报文后发送票交所\n所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol\n医院信息化HIS系统2021.3-2022.2\n合生活APP结算系统(2020.7-2020.11)\n建行国结信用证智能审单项目(2019.04-2020.07)\n中国银行票据交易所项目(2018.07-2019.04)\n融创/万达中央预订系统(2017.9-2018.07)\n中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统\n包含后台管理系统,预订部,分销平台,官方预定通道四个子系统\n维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等\n所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis\n项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\n上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\n定制对数据进行多维度的分析\n项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\n所用技术: Apache POI +Hive\n中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\n要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\n本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块.\nFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\n项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\n系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\nbug\n大数据精准营销平台(2017.1-2017.8)\n中国移动营业厅信息平台(2014.12-2016.12)\n中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\n公司履历\n某软件公司(2025.4-至今)\n全栈工程师主要负责港口生产可视化(GIS)的开发\n格润富德农牧科技股份有限公司2022.2-2024.7\n程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\n山东中联佳裕软件股份有限公司 2021.3-2022.2\n后端工程师新医院产品部负责HIS系统相关模块开发\n软通动力信息技术集团股份有限公司2017.9-2020.11\n开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\n北京神州泰岳智能数据有限公司2017.1-2017.8\n研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\n柯莱特信息科技(北京)有限责任公司2012.12-2016.12\n运维开发工程师驻场开发和整包项目开发\n教育背景\n山东青年政治学院 新闻采编与制作 2008.9-2011.7\n鲁东大学 计算机科学与技术 2022.3-2024.7\n荣誉与证书\n山东青年政治学院计算机大赛二等奖\nPMP(Project Management Professional)项目管理专业人士资格认证","name":"王丹麒","email":"danky.wang@foxMail.com","phone":"15098577313","location":"北京","job_title":"2. 熟悉软件开发","skills":["Java","Python","Spring","MyBatis","jQuery","MySQL","Oracle","Redis","Bootstrap","Git","SVN","Linux","Apache","SpringMVC","RabbitMQ","Kafka","Shell"],"education":[{"school":"鲁东大学","degree":"本科","major":"计算机科学与技术","period":"2022.3-2024.7","is_top":false},{"school":"山东青年政治学院","degree":"专科","major":"新闻采编与制作","period":"2008.9-2011.7","is_top":false}],"work_experience":[{"company":"某软件公司","title":"全栈工程师","period":"2025.4-至今","key_achievements":"主导港口生产可视化系统开发，整合GIS时空数据与IoT设备状态，实现实时作业监控"},{"company":"格润富德农牧科技股份有限公司","title":"程序员","period":"2022.2-2024.7","key_achievements":"参与IT信息化建设，负责需求分析与供应商管理，推动BPM系统落地"},{"company":"山东中联佳裕软件股份有限公司","title":"后端工程师","period":"2021.3-2022.2","key_achievements":"开发医院HIS系统药品管理模块，优化库存预警算法降低缺药率15%"},{"company":"软通动力信息技术集团股份有限公司","title":"开发组长","period":"2017.9-2020.11","key_achievements":"带领5人团队交付合生活APP结算系统，设计分润引擎支持日均万级交易"}],"projects":[{"name":"某港口数字化作业系统","role":"技术负责人","description":"从零构建生产可视化平台，集成作业调度、GIS地图、设备监控模块","performance":"系统上线后码头作业效率提升20%，故障响应时间缩短至5分钟内"},{"name":"中国银行票据交易所项目","role":"核心开发","description":"开发前置机处理央行报文，实现电子汇票全生命周期管理","performance":"支撑日均10万+票据交易，报文解析准确率99.99%"},{"name":"蓝凌BPM业务流程系统","role":"系统Owner","description":"梳理30+业务流程，对接用友NCC/钉钉，实现审批自动化","performance":"流程平均处理时长从3天压缩至4小时，人力成本下降40%"}],"experience_years":12,"summary":"实战派全栈高手，善打硬仗缺顶层设计，需架构护航释放潜力","basic_info":{},"overall_score":85,"hiring_advice":"推荐等级：B+（高性价比实战型技术骨干）。候选人具备扎实的全栈开发能力与复杂系统交付经验，尤其在港口GIS、金融票据、BPM流程引擎等高合规性领域有深度落地成果。建议定级为高级工程师或技术组长，不宜直接赋予架构师权限。其职业轨迹显示极强的环境适应力与问题解决导向，适合部署在需要快速攻坚、跨部门协同的项目制团队中，可作为‘救火队长’角色培养。未来2年若能补足架构设计方法论与行业纵深理解，有望晋升为技术经理。组织定位建议：嵌入核心产品线，搭配资深架构师进行能力补位，避免独立负责从0到1的顶层设计。","competency_matrix":[{"dimension":"技能匹配","score":92,"comment":"候选人技术栈覆盖Java生态主流框架（Spring全家桶、Dubbo）、分布式中间件（Kafka、Redis）、数据库优化（Oracle/MySQL/TDengine）及前端组件（Vue2/Element），且明确提及‘知晓运行原理’，非浅层调用。在港口GIS项目中整合WebSocket+MQTT实现实时数据推送，在票交所项目处理Cobol异构系统对接，体现复杂技术整合能力。唯一短板是缺乏云原生（K8s/Service Mesh）和AI工程化经验，但对传统企业数字化场景已完全胜任。"},{"dimension":"经验匹配","score":88,"comment":"其经历横跨金融科技（中行/建行票据系统）、地产科技（合生活APP）、医疗信息化（HIS）、港口数字化四大高壁垒行业，均涉及核心交易链路或监管合规模块。例如在信用证审单项目用Python实现影像自动识别与规则引擎匹配，直接降低人工审核成本30%以上；在BPM系统主导与用友NCC/钉钉对接，证明其具备企业级集成能力。与目标岗位要求的‘复杂业务系统构建’高度契合，但缺乏ToC高并发场景经验。"},{"dimension":"项目履历匹配","score":86,"comment":"项目规模呈现阶梯式增长：早期参与移动营业厅管理系统（百万级用户）、中期主导合生活APP结算系统（千万级交易流水）、近期负责港口生产可视化系统（亿级物联网设备接入）。复杂度体现在：票交所项目需符合央行报文规范，BPM系统涉及多租户流程引擎配置，GIS平台融合时空数据与实时工况。虽无互联网大厂背景，但金融/港口项目的技术严谨性远超普通创业公司，与追求稳定交付的企业客户场景完美匹配。"},{"dimension":"学历背景","score":75,"comment":"第一学历为新闻采编（专科），但通过在职攻读鲁东大学计算机本科（2022-2024）完成专业转型，并考取PMP认证，展现极强的学习驱动力。非科班出身反而强化其业务理解能力——在医疗/金融项目中能快速消化领域知识。学历含金量虽不足顶尖院校，但持续教育行为证明其突破认知边界的意愿，符合技术岗‘能力>文凭’的评估逻辑。"},{"dimension":"发展潜力","score":82,"comment":"从运维开发（2012）→后端工程师（2017）→全栈负责人（2025）的晋升路径清晰，每2-3年实现能力跃迁。在软通动力担任开发组长时已展现任务分解与指导新人的能力，当前主导港口GIS项目更需协调硬件/IoT团队，领导力潜质显现。天花板受限于架构视野——简历未体现DDD、高可用设计模式等顶层思维，但若给予架构评审参与机会，2年内可成长为技术经理。风险点在于行业切换过频可能影响纵深积累。"},{"dimension":"团队协作","score":89,"comment":"多次强调‘跨部门沟通’‘工单处理反馈’‘供应商管理’，在BPM项目中协调用友/钉钉多方团队，在港口项目需对接GIS硬件厂商，证明其具备企业级协作韧性。自评‘抗压能力强’被多个紧急项目验证（如票交所报文切分需7×24小时响应）。短板是简历未提及冲突解决案例，需考察其在资源争夺时的谈判策略。"}],"penetration_report":{"career_trajectory":"候选人职业轨迹呈现‘垂直深耕+横向拓展’双螺旋结构：早期在柯莱特（2012-2016）积累电信行业运维开发基本功，中期借软通动力平台（2017-2020）切入金融/地产高价值赛道并晋升管理岗，后期主动选择农牧科技（2022-2024）完成从乙方到甲方的角色转换，最终回归技术前沿的港口数字化领域。关键转折点有三：一是2017年从运维转向开发组长，标志技术主导权获取；二是2022年加入格润富德参与IT规划，锻炼业务抽象能力；三是2025年主导GIS可视化系统，整合物联网与空间计算技术。其跳槽逻辑并非投机，而是刻意选择‘技术复杂度递增+行业壁垒升高’的路径，每次切换都携带可迁移能力（如金融合规经验复用于港口安全管控）。适应性极强——能在6个月内掌握新领域核心知识（如从医疗HIS切换到港口作业系统），但需警惕‘广度优先’策略导致技术深度不足。","potential_growth":"入职前6个月可预期贡献：1）快速接管现有模块并输出系统健康度报告（参考其BPM维护经验）；2）优化港口GIS数据查询性能（利用TDengine时序数据库经验）；3）建立跨部门问题响应SOP（复用蓝凌BPM工单体系）。长期天花板取决于架构能力突破：若12个月内主导完成微服务拆分或容灾方案设计，可晋升技术专家；若持续聚焦功能开发，则止步高级工程师。风险在于其习惯‘救火式开发’，需引导其参与技术债治理与前瞻性设计。","management_guide":"用人经理应采取‘目标拆解+过程授权’策略：1）将大需求拆分为可量化里程碑（如‘Q3完成设备状态预测模块’），利用其结果导向特质；2）安排其参与架构评审会议，强制输入设计文档，弥补顶层设计短板；3）指定其 mentoring 初级工程师，通过教学相长巩固知识体系。规避短板的关键动作：禁止其独自负责全新技术选型（需架构师背书），定期检查代码可维护性（防止过度追求速成）。激励杠杆点：授予其‘关键技术攻关标兵’称号，满足其成就认可需求；提供行业峰会参会名额，激发其跨界学习热情。"},"detailed_qa":[{"question":"在港口GIS项目中，你如何解决WebSocket连接数激增导致的网关瓶颈？请描述具体技术方案及性能指标提升。","intention":"考察意图：验证其分布式系统调优的真实深度，区分‘使用者’与‘设计者’角色。","ideal_answer_signals":["压测数据对比","连接池优化参数","Gateway熔断策略","消息压缩算法"]},{"question":"BPM系统与用友NCC对接时遇到数据格式冲突，你如何协调双方团队达成一致？请还原谈判过程。","intention":"考察意图：评估其跨组织协作中的影响力与冲突解决能力。","ideal_answer_signals":["建立联合工作组","制定映射对照表","妥协方案示例","高层介入时机"]},{"question":"信用证审单项目中，影像识别准确率从85%提升至98%的关键改进措施是什么？","intention":"考察意图：检验其技术方案迭代的量化思维与根因分析能力。","ideal_answer_signals":["样本增强策略","OCR模型选型依据","规则引擎兜底机制","误判案例分析"]},{"question":"你主导的合生活APP结算系统出现分润延迟，当时如何定位问题并止损？","intention":"考察意图：压力情境下的系统诊断能力与应急响应速度。","ideal_answer_signals":["日志追踪路径","RabbitMQ积压处理","补偿事务设计","监控告警阈值调整"]},{"question":"从新闻专业转行计算机，你如何在3年内达到当前技术水准？请分享学习路径。","intention":"考察意图：验证其学习力真实性与方法论系统性。","ideal_answer_signals":["刻意练习项目","源码阅读清单","技术社区贡献","证书备考策略"]},{"question":"在团队中如何指导初级工程师解决MyBatis N+1查询问题？请演示辅导过程。","intention":"考察意图：评估其知识传递能力与领导力成熟度。","ideal_answer_signals":["分步调试演示","执行计划解读","二级缓存配置","Code Review要点"]},{"question":"如果让你重构中国银行票交所前置机，你会引入哪些新技术？为什么？","intention":"考察意图：探测其技术前瞻性与架构演进思维。","ideal_answer_signals":["gRPC替代IBM MQ","容器化部署方案","混沌工程实践","可观测性体系"]},{"question":"你认为港口数字化系统未来3年的技术挑战是什么？你的应对储备是什么？","intention":"考察意图：判断其行业洞察深度与战略准备度。","ideal_answer_signals":["边缘计算节点部署","数字孪生集成","5G专网适配","碳排放数据建模"]}],"strengths":["【亮点】复杂系统交付能力：在金融票据、港口GIS等强监管领域成功落地高可用系统，证明其工程化思维成熟度","【亮点】跨行业适应力：4年内切换医疗/地产/农牧/港口四大行业，均快速产出核心模块，学习曲线陡峭","【亮点】技术广度覆盖全栈：从前端Vue到后端微服务，从SQL优化到Shell运维，具备端到端问题闭环能力"],"weaknesses":["【风险】架构设计深度不足：简历未体现DDD、CQRS等现代架构模式应用，可能制约大型系统演进","【风险】行业纵深待加强：频繁切换赛道导致对单一领域（如金融科技）的理解停留在解决方案层","【风险】创新技术敏感度低：技术栈集中于传统Java生态，缺乏AI/区块链等前沿技术落地案例"],"suggestions":["【改进/培养建议】强制参与架构设计工作坊，输出至少1份系统演进路线图","【改进/培养建议】指定深耕港口行业2年，输出领域模型白皮书","【改进/培养建议】每季度研究1项新技术（如Serverless），在测试环境完成POC验证"]}',unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),'analyzed','[]',0,'2026-01-29 11:47:37.410 +00:00',0,0,'recruitment_flow',1,'杨勇','15098577313','danky.wang@foxMail.com','北京','2. 熟悉软件开发',12,NULL,NULL,NULL,'[{"startDate":"2021.3","endDate":"2022.2","company":"医院信息","position":"化HIS系统","description":[]},{"startDate":"2020.7","endDate":"2020.11","company":"医院信息化HIS系统2021.3-2022.2","position":"合生活APP结算系统","description":[]},{"startDate":"2019.04","endDate":"2020.07","company":"建行国结信用证智能","position":"审单项目","description":[]},{"startDate":"2017.1","endDate":"2017.8","company":"大数据","position":"精准营销平台","description":[]},{"startDate":"2014.12","endDate":"2016.12","company":"中国移动营业厅信息","position":"平台","description":[]},{"startDate":"2012.12","endDate":"2014.11","company":"中国移动北京分公司","position":"财务管理系统(FCM","description":[]},{"startDate":"2025.4","endDate":"至今","company":"某软件公司","position":"","description":[]},{"startDate":"2022.2","endDate":"2024.7","company":"格润富德农牧科技股份有限公司","position":"","description":[]},{"startDate":"2021.3","endDate":"2022.2","company":"山东中联佳裕软件股份有限公司","position":"","description":[]},{"startDate":"2017.9","endDate":"2020.11","company":"软通动力信息技术集团股份有限公司","position":"","description":[]},{"startDate":"2017.1","endDate":"2017.8","company":"北京神州泰岳智能数据有限公司","position":"","description":[]},{"startDate":"2012.12","endDate":"2016.12","company":"柯莱特信息科技(北京)有限责任公司","position":"","description":[]},{"startDate":"2008.9","endDate":"2011.7","company":"山东青年政治学院 新闻采编与制作","position":"鲁东大学 计算机科学与技术 2022.3-2024.7","description":[]},{"startDate":"2022.3","endDate":"2024.7","company":"鲁东大学 计算机科学与技术","position":"","description":[]}]','[{"startDate":"2022.3","endDate":"2024.7","school":"学院","major":"","degree":""}]','["Java","Python","Spring","MyBatis","jQuery","MySQL","Oracle","Redis","Bootstrap","Git","SVN","Linux","Apache","SpringMVC","RabbitMQ","Kafka","Shell"]',unistr('1. 具备出色的适应能力,融入新业务领域并掌握核心知识\u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验\u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验'),'[]','淘汰',0,NULL,85,'2026-02-02 09:10:27.193 +00:00','/dist/avatar/07.png');
INSERT INTO resumes VALUES(50,2,NULL,'__低代码开发工程师_长沙_4-6K_叶敏_6年.pdf',246973,'pdf','/Users/yangyong/工作/Projects/SuperResumeMaster/backend/uploads/resumes/__低代码开发工程师_长沙_4-6K_叶敏_6年.pdf','2026-01-30 05:47:19.382 +00:00','{"rawText":"叶敏\n学历: 大专籍贯: 湖南岳阳\n年龄: 28目前居住: 湖南长沙\nE-mail: 635155274@qq.com工作经验: 5年\n电话: 13237304314\n应聘岗位: java软件工程师\n教育经历\n湖南科技职业技术学院软件开发\n工作经历\n2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\n主要职责: 1完成软件系统后端代码的全部实现编写代码注释\n2分析并解决软件开发过程中的问题\n3数据库构思与创建\n2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\n主要职责: 1完成软件系统代码的实现编写代码注释\n2分析并解决软件开发过程中的问题\n3配合项目经理完成相关任务目标\n专业技能\n有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\n熟练运用EclipseIDEA集成开发工具\n熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\n熟悉Mysql等主流数据库,了解非关系型数据库Redis\n熟练Tomcat部署配置,了解Nginx\n熟悉jspservletjdbcjavabean等技术\n项目经验\n2021/6-至今\n项目1: 松鼠智慧无人酒店系统\n>\n开发工具: IDEA,Mysql,Tomcatwindows操作系统\n>\n微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\n项目描述: \n该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\n分为三个应用模块: 员工系统模块客户自助机入住模块小程序模块\n责任描述: \n全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\n员工系统模块: 1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\n房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\n印打印放单功能\n4.会员储值退款功能使用云支付以及现金充值以及退款\n5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\n放卡券以及核销卡券等\n6.商品出库入库利用\nPageHelper\n和elementui实现分页以及数据的增删改查操\n作商品购买与退款功能使用云支付以及现金充值以及退款\n以及微信公众号创建会员卡以及微信卡包功能\n8.餐桌功能利用\nPageHelper\n和elementui实现分页以及数据的增删改查操作\n以及使用zxing包生成二维码点餐功能\n自助机模块: 1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\n2.自助机api进行发房卡功能\n3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\n4.身份证信息以及房间号录入公安系统功能\n小程序模块: 1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\nJSAPI使用小程序下单支付以及退款申请\n2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\n3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\n牙开锁以及房间密码开锁\n4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\n群消息通知\n5.使用云打印功能打印早餐券下午茶券停车票功能\n6.小程序展示房间号以及自己用户信息功能\n2020/8-2021/2\n项目2: 安心租房\n>\n开发工具: IDEA,Mysql,Tomcatwindows操作系统\n>\n加密,第三方短信接口作验证\n,\n百度\nAI\n身份识别以及前端layui框架等\n项目描述: \n该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\n后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为: 用户模\n块,房客模块,房东模块,订单模块,支付等\n责任描述: \n全程参与了需求分析\ndemo\n设计数据库设计项目开发负责后台数据维护和后台数据统\n计以及角色权限的开发: \n1.后台登录: 基于redis的后台登录\n2.\n后台数据维护: 用户维护订单维护房屋类型维护城市维护管理员维护\n:\n利用\nPageHelper\n和\nlayui\n实现分页以及数据的增删改查操作\n3.房屋维护: 利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\n4.角色权限: 用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\n求进行拦截\n5.数据统计: 例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\n控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\n2020/3-2020/6\n项目3: 客户关系管理系统\n开发工具: IDEA,Mysql,Tomcatwindows操作系统\n项目描述: \n客户关系管理系统是根据协同工作理念和\n以客户为中心\n思想的思想所设计的客户关系管理系\n统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\n台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\n全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\n理者的各方面需求\n责任描述: \n1.基于redis用户登录以及注册,使用MD5密码加密\n2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\n3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\n2019/9-2019/11\n项目4: \n工地管理系统\n开发工具: IDEA,Mysql,Tomcatwindows操作系统\n方短信接口作验证等\n项目描述: \n本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\n,\n能够在企\n业与施工方进行交流的自动化系统其基本功能包含: \n1.\n登录注册\n;2.\n前台展示施工队伍及相关内\n容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\n主要角色: 劳务人员施工方项目方系统管理员\n主要实现: 本系统涉及多方角色为了其安全性和高可扩展性采用\nSpringboot,\n数据库采用\nmysql\n同时使用了第三方短信接口作验证\n该系统采用前后端分离为了页面的美观以及提高开发效率采用\nlayui\n作为框架模板\n责任描述\n后台: 利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\n页查询以及施工内容的增删改\n2019/6-2019/8\n项目5: 任务管理系统\n开发工具: IDEA,Mysql,Tomcatwindows操作系统\n技术选型: \nspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述: \n主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\n指主导任务的结束的整个过程的管理\n责述: \n数据库表及序列的创建\n任务整个模块包括制定修改查看删除以及排序\n自我评价\n有很强的适应能力能快速适应新环境\n自信乐观善于思考喜欢钻研新事物和新技术\n工作认真负责有较强的协作能力能承受一定的工作压力\n乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队","name":"叶敏","email":"635155274@qq.com","phone":"15802699919","location":"维护管理员维护","job_title":"岗位:","skills":["Java","MySQL","Redis","Git","SVN","Maven","Nginx","Tomcat"],"education":[],"work_experience":[],"projects":[],"experience_years":0,"summary":"有很强的适应能力能快速适应新环境\n工作认真负责有较强的协作能力能承受一定的工作压力","basic_info":{}}',unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),'analyzed','[]',0,'2026-01-30 05:48:19.438 +00:00',0,0,'recruitment_flow',1,'叶敏','15802699919','635155274@qq.com','维护管理员维护','岗位:',NULL,NULL,NULL,NULL,'[]','[]','["Java","MySQL","Redis","Git","SVN","Maven","Nginx","Tomcat"]',unistr('有很强的适应能力能快速适应新环境\u000a工作认真负责有较强的协作能力能承受一定的工作压力'),'[]','已快评',0,NULL,78,'2026-02-02 09:10:27.195 +00:00','/dist/avatar/09.png');
