INSERT INTO interview_sessions VALUES('f533d817-4f29-473b-b740-61b2facb8b12',1,1,unistr('长沙昂晟信息科技有限公司 Java\u000a2025.03-2025.08\u000a湖南晟医智能科技有限公司 Java\u000a2022.04-2024.12\u000a湖南九芝堂股份有限公司 Java\u000a2020.02-2022.03\u000a湖南盛鼎科技发展有限责任公司 Java\u000a2018.11-2019.12\u000a物业平台管理系统 Java开发\u000a2025.05-2025.08\u000a曾镇杨\u000a男 | 年龄：29岁 | 15575906607 | 1109642771@qq.com\u000a8年工作经验 | 求职意向：Java | 期望城市：长沙\u000a个人优势\u000a1.熟练使用 SpringBootMybatisjeecgboot ruoyi等开发框架\u000a2.熟练使用 IDEAVSCode gitHbuilderapifox等各种开发及接口管理工具\u000a3.熟练使用 KettleFineReport等工具参与开发过数据仓库及数据报表开发\u000a4.熟练掌握 mysql数据库,了解OracleSqlServer等数据库\u000aUl等前端框架\u000a6.掌握linux基本操作命令\u000a工作经历\u000a1.参与系统项目前后端代码开发\u000a2.完成领导交办的其他任务\u000a1.参与公司系统开发并在完成时出差到客户处部署和维护系统\u000a2.根据需求使用工具整理公司和客户的数据(kettle开发工具)\u000a1.根据业务需求设计程序接口,实现接口业务逻辑,编写接口文档\u000a2.日常维护公司部署的后台系统\u000a3.参与制作数据仓库用于管理公司后台物料数据\u000a4.针对数据仓库中归类好的数据制作可视化帆软报表,\u000a参与公司农村集体产权项目后台开发,负责对公司所收集到的农村土地信息业务做数据服务处理\u000a项目经历\u000a内容:\u000a物业平台管理系统是一种综合性的信息化解决方案旨在帮助管理者实现全方位精细化的运营管理该系统包含租户信息维护\u000a租赁合同管理财务管理场地管理仓库管理等模块\u000a业绩:\u000a原系统后台是用PHP搭建经过商议需要全部改造成Java框架我这边负责改造了系统登录第三方登录系统登出用户角\u000a色权限资源管理模块合同管理模块等\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a农商银行征信系统 Java开发\u000a2025.03-2025.04\u000a融合投影 Java开发\u000a2024.09-2024.11\u000aOsce无人执考 Java开发\u000a2024.04-2024.07\u000a进修生管理系统 Java开发\u000a2023.12-2024.01\u000a虚拟仿真数据平台 Java开发\u000a2023.10-2023.11\u000a学员点播平台 Java开发\u000a2023.07-2023.09\u000a学院数据迁移 数据开发工程师\u000a2023.04-2023.06\u000a内容:\u000a给银行经理使用的征信系统可以查看对应客户的征信情况并且提供PDF文件导出和打印功能系统整体采用ruoyi框架开发负\u000a责前后端代码开发以及bug修复\u000a业绩:\u000a在征信管理模块中新增导出功能更新列表样式及导入功能原有逻辑修复查看PDF预览时的样式bug\u000a内容:\u000a将维护的虚拟仿真数据进行可视化组装用户可在页面上自由搭配医疗场景搭配完成后再与unity组合成虚拟考试场景来帮助学\u000a员完成考试\u000a业绩:\u000a负责该项目所有后端代码开发项目完成后一同参与了项目部署该项目已在益阳医学院搭建完成并投入使用\u000a内容:\u000aosce是一种客观结构化临床考试提供一种客观的有序的有组织的考核框架通过模拟临床场景来测试医学生的临床能力\u000a考站设置分长站短站时间从5分钟到20分钟不等由主考人或SP对考生进行评价\u000a业绩:\u000a负责项目后端开发完成了考官登录验证所有语音维护与开考提示等代码项目完成后一同在广州珠江医院参与了项目部署与运\u000a行\u000a内容:\u000a用于医学院进修生所使用的管理系统学员可在上面进行个人信息登记与录取通知书记录\u000a业绩:\u000a负责前后端开发更新了学员信息录取通知书上传与下载等功能的版本\u000a内容:\u000a公司虚拟仿真部门需要在医学院展示3D投影因此搭建了一套数据记录平台\u000a业绩:\u000a负责该平台前后端代码编写在公司现有的cloud框架中新增了虚拟仿真子模块里面包含医教案列场景患者一系列数据维护\u000a内容:\u000a用于学生学习的视频平台教师和管理员登录后可发布课程学生可观看视频学习并进行考试系统可以通过学生学习进度和考试\u000a情况进行统计\u000a业绩:\u000a负责完成前后端代码编写完成了老师个人信息课程发布学生学习情况与考试统计等功能模块\u000a内容:\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a数据报表 Java开发\u000a2023.01-2023.03\u000a数据大屏 数据开发工程师\u000a2022.10-2022.12\u000a教师指标统计系统 Java开发\u000a2022.05-2022.09\u000a可视化驾驶舱 数据开发工程师\u000a2021.09-2022.02\u000aBI报表制作 数据开发工程师\u000a2021.04-2021.07\u000a数据仓库搭建 数据开发工程师\u000a2020.12-2021.03\u000a智能制造运行监控管理系统 java\u000a2020.06-2020.11\u000a由于益阳医学院服务器需要升级需要将原有的数据进行整体迁移\u000a使用kettle开发工具进行迁移\u000a业绩:\u000a完成了医学院数据库所有数据转移工作\u000a根据医学院提供的需求信息制作对应的报表,包含指标达标报表学员指标报表学员毕业信息报表等\u000a使用KettleFineReport10.0MySQL(开发工具)\u000a责任描述:负责作业开发与报表制作\u000a基于医学院服务器内的大数据制作可视化驾驶舱,将医学院关联的学院指标信息进行展示\u000a使用Kettle FineReport10.0MySQL(开发工具)\u000a责任描述:负责完成学院指标内容的报表展示\u000a\u000a编写,页面文件部署在Nglnx上,数据库为MySQL\u000a业绩:参与完成教师指标系统查询模块业务开发,\u000a驾驶舱是一款为企业内部领导及相关高管提供的指标分析型系统打破数据隔离,实现指标分析及决策场景落地通过详尽的指标\u000a体系,实时反映企业的运行状态,将采集的数据形象化直观化具体化是一个为高层管理层提供的"一站式"(One\u000aStop)决策支持的信息中心系统\u000a使用Kettle FineReport10.0 Oracle(开发工具)\u000a责任描述:负责完善财务大屏,仓储大屏,采购大屏中指定模块的数据可视化展示,所有驾驶舱都制作了二级下钻报表可查看物料更为\u000a详细的信息\u000a\u000a对外进行展示,帆软管理平台还可以搭建在企业微信中,员工可通过手机企业微信来查看报表状态\u000aKettle FineReport10.0Oracle(开发工具)\u000a责任描述:完成金蝶财务系统,英克进销存系统,仓库管理系统等数据可视化工作\u000a\u000a可以保存极大量的数据供分析使用,数据仓库的数据来自于各种数据库中,将所需数据从原来的数据中抽取出来进行加工与集成用于\u000a制作分析报表作为展示\u000aKettle Oracle(开发工具)\u000a责任描述:协助完成了公司金蝶EAS财务系统数据库的数据转移工作\u000a基于智慧工厂理念设计的一套全方面运行监控系统,系统包括设备实时状态检测,运行绩效,人员排班等模块,采用前后端分离设计,后\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中南林业科技大学 本科 软件工程\u000a2023-2025\u000a湖南电子科技职业学院 大专 软件工程\u000a2014-2016\u000a页面文件部署在Nginx上,数据库为MySQL\u000a业绩:完成绩效报表模块业务,对机组指标完成计算与展示\u000a教育经历'),3,0,'[{"content":"请做一个简单的自我介绍。","type":"open","userAnswer":null},{"content":"你为什么应聘这个职位？","type":"open","userAnswer":null},{"content":"你认为自己最大的优势是什么？","type":"open","userAnswer":null}]','CREATED','2026-01-27 08:40:00.000 +00:00',NULL,'2026-01-27 08:40:10.406 +00:00','2026-01-27 08:40:10.406 +00:00',NULL);
INSERT INTO interview_sessions VALUES('17c50dbd-93fb-4247-a199-d2ed01f83fc6',46,49,unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),8,0,'[{"questionIndex":1,"question":"在港口数字化作业系统中，你选择了SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT技术栈。请详细说明为什么选择这些技术，以及它们如何协同工作来满足系统的实时性和高并发需求？在实施过程中，遇到的最具挑战性的技术问题是什么，你是如何解决的？最终带来了哪些量化的性能提升或业务价值？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在蓝凌BPM业务流程系统中，你负责与用友NCC和钉钉等业务系统对接联调。请描述对接过程中遇到的主要技术难点，比如数据格式不一致或接口兼容性问题，你是如何解决的？此外，在开发安防信息管理系统模块时，如何确保模块的可扩展性和可维护性？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在合生活APP结算系统中，你主要负责迭代系统开发任务，生成结算单、退款单等。请解释结算系统的核心业务逻辑，以及如何处理订单拆分、差异单等复杂场景？在维护生产环境时，遇到的最棘手的bug是什么，如何定位和修复的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"你提到熟练掌握Spring Boot框架并知晓其运行原理。请解释Spring Boot的自动配置机制是如何工作的，以及在微服务架构中，如何利用Spring Boot实现服务的快速启动和配置管理？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"你具有微服务框架Spring Cloud Alibaba和Dubbo的使用经验。请比较这两种框架在服务发现、负载均衡和容错机制方面的差异，并说明在什么场景下你会选择使用Dubbo而不是Spring Cloud？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在简历中，你提到熟悉分布式系统的设计和应用，包括分布式缓存和消息队列。请设计一个高可用的分布式系统架构，用于处理港口生产可视化系统中的实时数据流，并解释如何使用Redis和Kafka来确保数据一致性和系统可靠性。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"你提到有带小团队经验。请分享一个你作为开发组长，指导初中级工程师完成项目的经历。在项目中，如何分配任务、解决团队冲突，并确保项目按时交付？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设在生产环境中，港口可视化系统突然出现性能下降，用户报告延迟增加。作为负责人，你会采取哪些步骤来诊断和解决这个问题？请描述你的排查流程和决策过程。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-01-31 14:11:00.000 +00:00',NULL,'2026-01-31 14:12:36.405 +00:00','2026-01-31 14:12:36.405 +00:00',NULL);
INSERT INTO interview_sessions VALUES('01d6f381-0748-472b-bbba-d24523b715de',46,49,unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),8,0,'[{"questionIndex":1,"question":"在港口数字化作业系统中，你从零到一负责BPM系统业务流程需求梳理。请详细描述你在需求梳理过程中遇到的最大技术挑战（如跨部门需求冲突或业务逻辑复杂性），以及你如何通过技术手段（如流程引擎配置或数据建模）解决这个挑战？最终带来了哪些量化的业务改进（如流程效率提升或错误率降低）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在蓝凌BPM业务流程系统中，你负责与用友NCC、钉钉等业务系统对接联调。请分享一个具体的对接难点（如数据格式不一致或实时性要求高），你是如何分析并解决这个问题的？解决方案中涉及了哪些关键技术（如API网关或消息队列），以及如何确保系统稳定性和数据一致性？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"你在简历中提到熟练掌握Spring Boot和Spring MVC，并知晓其运行原理。请解释Spring Boot的自动配置机制（如@Conditional注解）是如何工作的，以及在港口项目中，你如何利用它来简化配置并提高开发效率？请结合一个具体场景说明。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"你具备系统数据库设计和规划能力，并优化SQL语句。在合生活APP结算系统中，请分享一个你遇到的SQL性能问题（如高并发下的查询延迟），你是如何通过索引优化或查询重构解决的？优化后的性能指标（如响应时间减少百分比）如何量化？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在港口项目中，你使用了Spring Cloud Alibaba技术栈（包括Nacos、OpenFeign等）。请解释你为什么选择Nacos作为服务注册中心，而不是其他选项（如Eureka）？在微服务架构中，你是如何设计服务间通信（如Feign客户端配置）来处理高并发和故障转移的？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"你熟悉分布式系统的设计，包括分布式缓存和消息队列。在合生活APP结算系统中，你使用了Redis和RabbitMQ。请描述你如何设计Redis缓存策略（如缓存穿透或雪崩防护）来处理高并发场景，以及如何确保RabbitMQ消息的可靠投递（如事务消息或死信队列）？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"你在简历中提到有带小团队经验（如开发组长）。请分享一个你指导初中级开发工程师的经历，例如在需求分解或任务分配中遇到的挑战（如技能差异或进度延迟）。你是如何通过沟通和结果导向来激励团队并确保项目按时交付的？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"模拟一个工作场景：在港口生产可视化系统中，用户突然报告系统性能下降（如GIS地图加载延迟增加）。作为负责人，你会采取哪些步骤来快速定位问题（如日志分析或压力测试）？请详细描述你的排查流程和解决方案，包括如何与跨部门团队协作恢复系统。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-01-31 14:12:00.000 +00:00',NULL,'2026-01-31 14:12:51.200 +00:00','2026-01-31 14:12:51.200 +00:00',NULL);
INSERT INTO interview_sessions VALUES('037eaf8a-d8f8-4f01-921b-ac9611d96517',46,49,unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),8,0,'[{"questionIndex":1,"question":"在港口生产可视化系统中，你选择了SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebSocket+MQTT的技术栈。请详细说明在GIS实时数据展示场景下，这些技术如何协同工作？当设备状态数据量激增时，你如何通过WebSocket和MQTT的配合解决消息积压问题？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"蓝凌BPM系统与用友NCC、钉钉的对接过程中，你提到遇到数据格式不一致的挑战。请具体描述你设计的中间适配层方案，包括数据转换规则和异常处理机制。在系统升级维护时，如何确保业务流程的连续性？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在合生活APP结算系统中，你负责处理分润单、结算单等核心业务数据。当订单拆分出现异常时，你如何通过Redis和RabbitMQ设计分布式事务补偿机制？请说明具体的数据一致性保障方案。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"简历中提到你具备系统数据库设计和规划能力。在港口生产可视化系统中，Oracle和TDEngine的混合使用场景下，请说明你如何设计数据分层存储策略？针对GIS时空查询，你有哪些SQL优化技巧？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在Spring Cloud Alibaba微服务架构中，Nacos作为配置中心时，如何处理服务实例动态扩缩容时的配置热更新问题？当Gateway路由规则变更时，如何避免配置不一致导致的流量异常？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"作为开发组长带领团队时，当项目进度严重滞后且技术方案存在重大分歧，你如何协调资源并推动决策？请结合一个具体案例说明你的冲突解决方法和最终成果。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设在港口生产可视化系统上线后，突然出现大面积设备状态数据异常，用户反馈系统响应超时。作为技术负责人，请描述你的应急响应流程：从问题定位、临时恢复到根因分析的完整步骤。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在TDEngine处理GIS时空数据时，你如何设计数据分片策略以优化查询性能？当历史数据需要归档时，如何通过分区管理实现存储成本与查询效率的平衡？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-01 03:47:00.000 +00:00',NULL,'2026-02-01 03:47:46.851 +00:00','2026-02-01 03:47:46.851 +00:00',NULL);
INSERT INTO interview_sessions VALUES('b1cbe0ae-7131-4f00-a974-6996f84402e2',46,49,unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),8,0,'[{"questionIndex":1,"question":"在港口数字化作业系统中，你选择SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT作为技术栈的原因是什么？在实施过程中遇到的最具挑战性的技术问题是什么，你是如何解决的？最终带来了哪些量化的性能提升或业务价值？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在蓝凌BPM业务流程系统中，你负责与用友NCC和钉钉等系统的对接联调。请描述一个具体的对接挑战（如数据格式不一致或实时性问题），以及你如何设计解决方案来确保数据一致性和系统稳定性？过程中是否涉及技术选型调整，为什么？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"请解释Spring Boot的自动配置原理，并结合你在合生活APP结算系统中的使用经验，说明你是如何利用它来简化配置的？在处理分布式事务时，遇到了哪些具体问题，你是如何通过Redis或RabbitMQ来解决的？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在HIS系统开发中，你遇到了一个性能瓶颈的SQL查询。请描述你如何分析并优化这个查询（包括使用的工具如EXPLAIN或性能监控），以及优化后的具体性能提升（如响应时间减少百分比）？这体现了你对数据库底层原理的哪些理解？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在港口数字化作业系统的微服务架构设计中，你使用了Spring Cloud Alibaba。请解释你如何设计服务间的通信机制（如OpenFeign和Gateway），以及如何处理分布式事务问题（如使用Seata或本地消息表）？架构设计如何支持高并发和可扩展性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"请分享一个你在项目中与跨部门团队（如业务部门、运维团队）协作解决复杂问题的经历。你如何确保沟通顺畅并达成共识？过程中是否遇到过冲突，你是如何处理的？这体现了你的哪些软技能？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设在生产环境中，合生活APP结算系统突然出现大量退款失败的问题。作为负责人，你会如何快速定位问题（如日志分析或监控工具）、协调团队解决（如开发、运维、测试），并制定预防措施（如自动化测试或监控告警）？请描述你的应急响应流程。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在中国银行票据交易所项目中，你负责开发前置机来处理报文。请描述一个你在处理报文解析或持久化过程中遇到的技术难题（如报文格式复杂或性能瓶颈），以及你的解决方案（如自定义解析逻辑或优化存储）？这如何影响了系统的可靠性和效率？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-01 03:57:00.000 +00:00',NULL,'2026-02-01 03:58:00.738 +00:00','2026-02-01 03:58:00.738 +00:00',NULL);
INSERT INTO interview_sessions VALUES('b97683cb-9d53-4d52-a906-fbb633746d0c',9,9,unistr('15635372021\u000a15635372021@163.com\u000a女\u000a本科\u000a\u000a态页面熟悉页面架构和布局\u000a\u000a性的经验和方案\u000a\u000a\u000a运用Axios库处理跨域问题确保前后端数据交互的安全和可靠性\u000a5熟练运用微信开发者工具构建微信小程序使用uni-app框架能够快速开发跨平台应用\u000a\u000a度并提供丰富的UI组件工具和功能构建灵活高效的用户界面vue3\u000a\u000a库能够快速构建复杂的界面和功能\u000a8可以使用Git进行代码版本管理具备良好的代码规范和团队协作经验\u000a9熟悉前后端分离开发模式和接口规范熟悉与后台开发人员的联调流程能够高效合作并实现\u000a需求\u000a10使用ps完成基本页面设计和蓝湖进行切图\u000a1负责前端web交互和展现的开发设计工作整合开发产品\u000a2参与网站的产品技术方案的设计并能制定相关的前端开发流程和规范\u000a3负责业务应用和后台管理页面的开发\u000a郝泽枫\u000a求职意向：Web前端\u000a\u000a\u000a4与UI设计师产品经理紧密合作产出高质量的产品前端层\u000a5持续优化前端产品的使用体验执行性能可拓展性和兼容性\u000a6按照项目计划与项目组其他成员协同工作在保证质量的前提下按时完成开发任务\u000a\u000a本项目为了监督政府相关部门有没有去具体处理和落实广大群众提交的留\u000a言问题督察对象包括一些环境保护食品安全安全生产城市管理教\u000a育医疗卫生等领域我们结合互联网开发了这样一个互联网+督察系统便\u000a于上级领导方便及时监督和检查各部门对收到的留言是否进行了落实和处理\u000a：vue2+elementui+axios\u000a1.使用ElementUI中表单表格对话框等组件快速构建美观易用\u000a的用户界面\u000a2.内部管理系统使用组件传值指令判断根据账号权限级别将其分\u000a配到不同的角色包括收文员经办人领导以及内设的三个职位根\u000a据不同的权限可以访问和操作系统中的特定功能和数据根据不同的\u000a操作实现增删改查功能\u000a3.使用Axios库在前端与后台进行数据通信通过Axios发送异步请求\u000a从后台获取数据这样可以实现留言内容的显示以及各部门处理情\u000a况的展示方便上级领导监督和检查\u000a4.进行项目优化优化前端代码和页面加载速度提升用户体验\u000a对接口请求\u000a进行优化减少响应时间提高系统性能,优化系统的可扩展性和可维护\u000a性方便后续功能拓展和维护\u000a：绩效\u000a子\u000a系统为用户提供了绩效考核服务实现了督促检查和绩效考核的紧密结合\u000a用户可以通过系统完成考核指标制定跟踪评估等工作以督促考以\u000a\u000a考保督确保各项决策部署的落实系统主要功能模块包括：基础数据管理\u000a监控台指标分解与制定过程管理与督查阶段评估年度综合考评\u000a综合分析与总结应用等\u000a\u000a维护的应用\u000a\u000a实现了一个美观易用的用户界面\u000a3.实现了部门成绩汇总功能通过获取和处理后端API返回的数据将\u000a部门成绩进行汇总并展示给用户实现了评价打分功能用户可以\u000a根据设定的评分标准对特定项目或人员进行评价并将评分结果提交\u000a给后端进行处外理\u000a4.运用路由传参通过配置路由和参数实现了页面之间的参数传递保证\u000a页面效果\u000a5.运用本地存储将用户的操作和数据保存在本地以便在页面刷新\u000a或用户返回时可以重新加载之前的数据这样可以实现数据的持久性\u000a和用户体验的连续性\u000a家电购商城系统是基于web浏览器的电子商务系统通过互联网实现商品的\u000a线上电子化销售及业务流程处理该系统主要以系统会员及普通游客为服务目标\u000a提供快捷方便的商品展示和线上购物\u000a使用Uniapp跨平台开发框架进行开发结合Vant-UI组件库进行面的搭建\u000a和开发\u000a2.实现了商品列表的展示和分类筛选功能\u000a3.设计并开发购物车模块实现商品的添加数量修改和删除等功能\u000a4.实现订单管理模块包括订单列表的展示订单详情的查看和取消订单等功能\u000a5.使用前端技术进行页面布局样式设计和交互效果的实现\u000a\u000a本项目着重阐述了银行业务管理系统的整体开发过程介绍了系统的开发环境\u000a以及开发工具对于设计思想和设计流程也做出了全面的叙述,该项目皆在\u000a帮助银行提高业务效率管理风险增强用户体验该项目为用户提供账户管\u000a理转账汇款缴费理财购买等服务用户可以直接在线办理业务项目\u000a主要有账户管理个人储蓄个人贷款用户转账投资理财申请信用卡等\u000a1.主要负责开发贷款信息录入页面和还款页面根据产品需求和设计提供的\u000a界面原型使用Vue框架和Vue2技术实现这两个页面的开发确保页面的\u000a交互和功能实现\u000a2.利用正则表达式实现登录注册功能对用户的输入进行验证和格式化处理\u000a确保用户信息的准确性和安全性同时实现用户信息修改管理功能包\u000a括密码加密等安全措施保障用户的个人信息安全\u000a3.使用Axios库实现与后端的数据交互通过发送异步请求获取各种数据\u000a如用户信息贷款数据等并将获取的数据展示在相应的页面上确保前\u000a后端数据的交互正常保证页面展示效果和数据的准确性\u000a这个项目是一个健身类的微信小程序项目旨在帮助用户方便地进行健身课\u000a程预约和管理个人健身计划小程序要求用户可以通过微信登录或手机号登\u000a录并根据用户身份生成二维码供用户到店时进行扫码识别除此之外\u000a小程序还要提供课程排名功能推荐适合用户的健身课程以及展示课程详\u000a情和咨询方式用户可以根据自己的时间选择合适的课程并进行预约同时\u000a小程序还具备用户的个人首页展示个人信息历史预约记录等功能\u000a1.实现用户界面：负责将设计团队提供的界面设计转化为具体的网页或移\u000a动应用界面确保用户界面美观友好和易用\u000a2.使用微信小程序开发工具和微信API集成登录功能确保用户可以通过\u000a不同方式登录小程序实现微信登录和手机号登录功能并生成用户身\u000a份相关的二维码供到店时扫码识别\u000a\u000a3\u000a.实现了历史预约记录在首页点击历史预约记录用户可以查看之前预\u000a约的记录使用axios封装确保前后端数据的交互正常保证页面展示效\u000a果和数据的准确性\u000a广州妈妈网是服务于广州母婴得一个平台之一专注于为广州地区的孕妇新\u000a妈妈和家庭提供优质的母婴服务和信息它为用户提供了丰富的内容和资源\u000a涵盖了怀孕分娩育儿等各个阶段的信息和指导\u000a\u000a2.主要负责用户得登录注册首页我的主页圈子几个模块包括还实\u000a现了用户发表帖子兑换积分通过积分兑换一些礼品得功能\u000a3.用户可以在我主页查看我的帖子还实现了我的收藏功能\u000a\u000a助超市管理人员高效管理和监控超市的各项业务该系统涵盖了商品管理库存\u000a管理销售统计员工管理订单管理等功能模块为超市提供了全面的管理解\u000a决方案\u000a：vue3+elementuiPlus+axios+ts\u000a\u000a2.主要负责用户得商品管理库存管理销售统计几个模块\u000a3.商品管理中我实现了商品的录入商品价格数量名字分类的管理\u000a以及数据的查询和导出功能\u000a4.销售统计是使用echarts进行数据可视化将数据直观的展示到用户面前\u000a\u000a在过去的工作经历中我参与了十多个项目的开发我不仅能够独立完成任务还能与团\u000a队成员协同工作按时保质的完成项目开发任务具备良好的服务意识责任心较强的\u000a学习能力优秀的团队沟通与协作能力能承受一定的工作压力并且可以接受公司外派\u000a出差驻场等安排'),8,0,'[{"questionIndex":1,"question":"在您的简历中提到使用Vue3开发项目（如超市管理系统）。请解释Vue3相比Vue2的主要优势，以及您在项目中如何利用这些优势（如Composition API）来解决实际问题？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在互联网+督察系统中，您实现了基于账号权限级别的角色分配（如收文员、经办人、领导）。请详细说明这个模块的技术选型原因（为什么选择ElementUI的组件和指令），开发过程中遇到的最难问题（如权限冲突或数据隔离），以及您是如何解决的？最终有什么量化的产出（如性能提升或错误率降低）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在职责中，您提到持续优化前端产品的性能和可扩展性。请描述一个您在前端项目中（如绩效子系统或超市管理系统）实施的具体性能优化策略（如代码分割或懒加载），并量化其效果（如页面加载时间减少百分比或用户满意度提升）。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在绩效子系统中，您使用了本地存储来保存用户操作数据（如历史记录）。请解释为什么选择本地存储而不是其他方案（如Vuex或后端存储），以及在使用本地存储时如何处理数据一致性和安全性问题（如防止数据篡改或丢失）？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在超市管理系统中，您使用echarts进行数据可视化（如销售统计）。请描述您是如何设计数据流和组件结构来确保图表的性能和可维护性的？如果有大量数据（如实时销售数据），如何优化渲染速度和交互体验？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"您在简历中提到与UI设计师和产品经理紧密合作（如在多个项目中）。请分享一个您在项目中与设计师或产品经理沟通挑战的经历（如需求变更或设计冲突），以及您是如何解决这个挑战以确保项目顺利进行的？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"在银行业务管理系统中，您实现了登录功能并使用正则表达式进行输入验证。请模拟一个场景：如果用户反馈登录页面加载缓慢，您会如何诊断和优化这个问题（如网络请求或渲染瓶颈）？同时，如何确保用户输入验证的安全性（如防止XSS攻击）？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在健身微信小程序项目中，您实现了用户登录和二维码生成功能。请详细说明技术选型原因（为什么选择微信开发者工具和uni-app框架），开发过程中遇到的最难问题（如二维码生成或数据同步），以及您是如何解决的？最终有什么量化的产出（如用户留存率或功能使用率）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-01 05:54:00.000 +00:00',NULL,'2026-02-01 05:54:43.581 +00:00','2026-02-01 05:54:43.581 +00:00',NULL);
INSERT INTO interview_sessions VALUES('a3b3822c-ddb9-4ddf-bd7a-85d025241def',46,49,unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),8,0,'[{"questionIndex":1,"question":"在港口数字化作业系统中，你使用了SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT等技术栈。请详细说明你选择这些技术的原因，以及在实际项目中遇到的最具挑战性的技术难题是什么？你是如何解决的？最终带来了哪些量化的性能提升或业务价值？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"简历中提到你熟悉微服务框架Spring Cloud Alibaba/Dubbo。请解释Dubbo的运行机制，特别是在分布式系统中，它如何处理服务发现、负载均衡和容错？你在一个项目中如何优化Dubbo的性能？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在港口数字化作业系统中，你使用了分布式缓存Redis和消息队列Kafka。请描述你设计的分布式架构中，如何确保数据一致性、高可用性和可扩展性？特别是在处理高并发请求时，你采取了哪些措施？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"简历中提到你“优秀的表达与沟通能力，对跨部门沟通和协作有相当的经验”。请分享一个你在项目中与跨部门团队协作的具体案例，包括遇到的挑战、你的沟通策略以及最终如何达成共识。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"假设你在港口生产可视化系统中，突然出现一个严重的性能问题，导致系统响应缓慢。作为负责人，你会如何快速定位问题、分析原因并采取哪些步骤来恢复系统？请描述你的应急处理流程。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在蓝凌BPM业务流程系统中，你负责开发安防信息管理系统的设备保养与维修模块。请详细说明你在该模块中遇到的技术难点，以及如何利用蓝凌BPM低代码平台和SSM框架解决的？最终模块上线后，对业务效率的提升有哪些量化指标？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"简历中提到你“熟练掌握MySQL,Oracle等关系型数据库使用及底层原理，具备系统数据库设计和规划能力，优化SQL语句”。请举例说明你在项目中如何优化一个复杂的SQL查询，使其性能提升显著？你使用了哪些工具或方法来诊断和优化？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在合生活APP结算系统中，你使用了SpringCloud Alibaba+Dubbo+Redis+RabbitMQ+MySQL。请解释你设计的微服务架构中，如何处理服务间的通信和数据同步？特别是在结算系统中，如何确保订单拆分、结算、退款等事务的原子性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-01 11:17:00.000 +00:00',NULL,'2026-02-01 11:18:00.497 +00:00','2026-02-01 11:18:00.497 +00:00',NULL);
INSERT INTO interview_sessions VALUES('9d7a635e-307e-487d-8051-8f61dd834282',46,49,unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),8,0,'[{"questionIndex":1,"question":"在港口生产可视化系统中，你提到使用了TDEngine作为时序数据库。请详细说明选择TDEngine而非传统关系型数据库的原因，以及在实际应用中是如何解决其与Oracle和Redis的数据同步问题的？最终系统在数据处理性能上取得了哪些量化的提升？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在蓝凌BPM系统中，你负责了与用友NCC和钉钉的对接工作。请描述在对接过程中遇到的最具挑战性的技术问题是什么？你是如何解决的？这个对接对业务流程效率的提升带来了哪些具体改变？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在合生活APP结算系统中，你负责处理订单拆分、结算、退款等核心业务。在高并发场景下，如何保证数据的一致性？请详细说明你设计的解决方案，并举例说明该方案如何应对退款和激励单的异常处理。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"简历中提到你熟练掌握Spring Cloud Alibaba，请解释Nacos在微服务架构中的作用，以及你如何利用Nacos实现服务注册、发现和配置管理的？在服务调用失败时，你是如何进行熔断和降级的？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"你提到具备系统数据库设计和规划能力，并优化SQL语句。请举例说明你曾经遇到的一个复杂SQL查询，你是如何通过优化索引或查询逻辑来提升性能的？优化前后的性能指标（如响应时间）分别是多少？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在港口生产可视化系统的微服务架构中，你是如何进行服务拆分的？在服务拆分过程中，你主要考虑了哪些因素？如何解决服务间的分布式事务问题？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"简历中提到你具有优秀的跨部门沟通和协作经验，并有带小团队经验。请分享一个你带领团队与跨部门（如产品、测试、运维）协作完成项目的经历，其中遇到了哪些沟通障碍，你是如何解决的？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设在港口生产可视化系统的上线初期，突然出现GIS地图渲染延迟严重，用户反馈系统卡顿。作为负责人，你会如何带领团队快速定位问题并解决？请描述你的排查步骤和解决方案。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-02 02:28:00.000 +00:00',NULL,'2026-02-02 02:29:12.381 +00:00','2026-02-02 02:29:12.381 +00:00',NULL);
INSERT INTO interview_sessions VALUES('39c32f68-1159-418a-ad91-d9dd30cde032',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统的员工模块中，你使用了WebSocket实现消息推送和企业微信机器人通知。请详细说明WebSocket的连接建立机制、消息格式设计，以及如何解决消息丢失或延迟问题？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"安心租房项目采用基于Redis的后台登录机制，请解释为什么选择Redis而非传统Session存储？具体如何设计Redis的Key结构来存储登录状态？在并发登录场景下如何保证数据一致性？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"客户关系管理系统中，你独立实现了客户管理模块的分页排序优化。请具体说明优化前后的性能差异，采用了哪些技术手段（如索引优化、SQL改写等）？如何验证优化效果？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"工地管理系统涉及劳务人员、施工方等多角色权限隔离，请描述你设计的数据库表结构如何实现RBAC模型？在SpringBoot中如何通过拦截器实现动态权限校验？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"你在多个项目中使用Redis处理登录状态和缓存，请说明Redis的持久化机制（RDB/AOF）如何选择？在支付场景下如何设计Redis缓存策略避免缓存雪崩？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"项目经验中多次使用PageHelper实现分页，请解释其底层实现原理？当数据量超过百万级时，如何优化深度分页（如查询第10000页）的性能？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设需要为松鼠酒店系统设计高并发支付模块，支持微信支付/余额支付/现金支付，请描述你的技术选型（如分布式事务方案）、架构设计（如服务拆分）及关键性能指标（如TPS）？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在项目上线前发现身份证识别模块在高峰期响应超时，作为后端负责人你会如何排查？请描述从日志分析到系统调优的完整排查流程。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-02 02:47:00.000 +00:00',NULL,'2026-02-02 02:48:42.354 +00:00','2026-02-02 02:48:42.354 +00:00',NULL);
INSERT INTO interview_sessions VALUES('4c35eddf-cc87-4260-8f3a-1e8eefb0a97b',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统的后端开发中，你负责实现WebSocket进行消息推送和企业微信机器人通知功能。请详细说明你选择WebSocket而非轮询或长轮询的技术选型原因，以及在实际实现中遇到的最大挑战（如连接稳定性或消息延迟）是什么？你是如何解决的？最终带来了哪些量化的性能提升（如消息延迟降低百分比）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在安心租房项目中，你独立实现了角色权限系统，包括数据库表设计和拦截器开发。请具体描述你如何设计数据库表结构来支持动态授权（如角色-权限映射表），以及拦截器如何根据用户角色拦截数据请求？在实现过程中，你遇到了哪些权限边界模糊的问题，如何通过代码逻辑解决的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在客户关系管理系统中，你提到对客户管理模块的分页排序功能进行了优化。请详细说明你采用了哪些具体优化方法（如索引设计、SQL查询优化或缓存策略），以及优化前后的性能对比数据（如查询响应时间从多少毫秒降低到多少毫秒）？这些优化如何影响了系统的整体用户体验？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在工地管理系统（项目4）中，你采用Springboot框架并整合了第三方短信接口。请解释你选择Springboot而非传统Spring/SpringMVC的技术选型原因，以及它如何简化了项目开发（如自动配置或依赖管理）？在集成短信接口时，你遇到了哪些高并发或安全性的挑战，如何通过Springboot特性解决的？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"简历中提到你有扎实的Java基础和熟悉面向对象编程。请结合你在项目1（松鼠智慧无人酒店系统）中的具体代码实现，解释面向对象编程的封装原则如何应用于数据库操作类的设计（如封装JDBC连接池），以及多态如何体现在支付模块（如微信支付、现金支付的统一接口）？这些设计如何提高了代码的可维护性？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在项目1和项目2中，你多次使用PageHelper实现分页功能（如商品管理和房屋维护）。请详细说明你如何优化PageHelper的SQL查询性能（如避免全表扫描或使用索引），以及在实际项目中遇到分页数据量过大时的处理策略（如游标分页或缓存）？这些优化带来了哪些具体的性能提升（如分页查询时间减少）？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"自我评价中提到你“有较强的协作能力能承受一定的工作压力”。请分享一个在项目1（松鼠智慧无人酒店系统）开发过程中，面对高并发需求（如微信支付和蓝牙开锁同时上线）时，你如何与团队协作解决压力？具体描述你的沟通策略和问题解决步骤，以及最终如何确保项目按时交付？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设你被分配到一个新项目，需要快速实现一个类似项目1的微信支付功能，但要求支持多渠道支付（如支付宝、银联）。请描述你会如何从零开始设计技术方案（包括技术选型、风险评估），以及如何利用你在简历项目中的经验（如Redis缓存或WebSocket）来加速开发？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-02 02:57:00.000 +00:00',NULL,'2026-02-02 02:58:23.508 +00:00','2026-02-02 02:58:23.508 +00:00',NULL);
INSERT INTO interview_sessions VALUES('4e2164ff-1189-47d1-8940-b5315b77fa79',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统中，你负责后端全部开发，涉及微信支付、WebSocket消息推送和蓝牙开锁等功能。请详细描述你在实现这些功能时遇到的最具挑战性的技术问题（例如高并发或数据一致性），以及你如何通过技术选型（如Redis或WebSocket）解决的？最终带来了哪些量化的业务改进（如响应时间缩短或错误率降低）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在安心租房项目中，你实现了基于Redis的后台登录和角色权限系统。请解释你选择Redis而非传统Session存储的原因，以及如何设计数据库表和拦截器来确保不同角色的权限隔离？在实现过程中，你遇到了哪些安全或性能问题，如何优化解决的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在客户关系管理系统中，你独立实现了用户营销管理模块，并对分页和排序功能进行了优化。请具体说明你使用了哪些技术（如PageHelper或索引优化）来提升查询效率？优化前后的性能对比数据如何？例如，查询时间或数据量处理能力的提升。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"简历中提到你有扎实的Java基础和良好的编程习惯。请结合面向对象编程原则，解释在松鼠智慧无人酒店系统的员工模块中，你如何利用封装、继承和多态来设计代码结构？例如，如何处理支付方式（云支付、现金、余额）的扩展性？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在多个项目中，你都使用了MySQL数据库。请描述在安心租房的数据统计模块中，你如何优化数据库查询性能（例如，针对每月用户增长量的折线图数据）？具体使用了哪些技术（如索引、分表或缓存）？效果如何量化？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在松鼠智慧无人酒店系统中，系统采用前后端分离架构，并涉及高并发场景（如微信支付和开锁）。请解释你设计的后端架构如何处理这些场景？例如，是否使用了消息队列、负载均衡或分布式事务？如何确保系统的可扩展性和稳定性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"自我评价中提到你‘能承受一定的工作压力’和‘乐于与同事沟通’。请分享一个在松鼠智慧无人酒店系统开发中，面对紧急需求变更或技术难题时，你如何与团队协作解决？具体沟通策略和抗压措施是什么？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设你正在开发一个新的酒店会员储值功能，需要集成微信支付和Redis缓存。在测试阶段发现高并发下数据不一致问题。请描述你会如何分析问题根源、制定重构计划，并与项目经理沟通以推进解决方案？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-02 02:58:00.000 +00:00',NULL,'2026-02-02 03:00:01.678 +00:00','2026-02-02 03:00:01.678 +00:00',NULL);
INSERT INTO interview_sessions VALUES('d2b8c2fd-726e-4d97-8b5f-f984a17b8e75',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统中，你负责后端全部开发，并使用了WebSocket进行消息推送和企业微信机器人通知。请详细描述你在实现WebSocket时遇到的最具挑战性的技术问题，以及你是如何解决这个问题的，并说明最终对系统性能的量化影响（如响应时间或消息延迟的改善）。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在安心租房项目中，你选择了基于Redis的后台登录方案，而不是传统的Session机制。请解释这个技术选型的具体原因，包括对高并发场景的考虑，以及在实际应用中Redis登录可能带来的潜在风险（如数据一致性或缓存穿透问题），你是如何应对这些风险的？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"你的简历提到在客户关系管理系统中对分页功能进行了优化。请具体说明你采用了哪些优化技术（如SQL索引调整或缓存策略），并解释这些优化如何解决了分页查询中的性能瓶颈，例如在处理大量用户数据时的查询效率提升百分比。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在工地管理系统中，你使用了FTP服务器来处理房东提交的房屋图片审核。请描述FTP集成的具体实现过程，包括如何确保图片上传的安全性（如防止恶意文件上传）和效率（如大文件处理），以及遇到的最难问题是什么，你是如何解决的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"你在多个项目中（如松鼠智慧无人酒店系统和安心租房）都采用了前后端分离架构。请阐述这种架构的核心优势，并说明在设计RESTful API时，你是如何确保接口的稳定性和可扩展性的，例如在版本控制或错误处理方面的实践。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"假设在松鼠智慧无人酒店系统中，微信支付接口突然出现故障，导致用户无法完成支付，且自助机入住模块受到影响。作为后端开发，你会采取哪些步骤来快速诊断问题（如日志分析或接口测试），并制定临时解决方案，同时如何与团队协作确保系统恢复？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"你的简历提到“能承受一定的工作压力”和“乐于与同事以及领导沟通”。请结合一个具体项目例子（如松鼠智慧无人酒店系统的紧急上线），描述你在高压环境下如何管理压力，以及通过沟通快速解决项目问题的实例，包括沟通的具体方式和效果。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在安心租房项目中，你实现了基于数据库表的动态角色权限系统，并编写了拦截器进行请求拦截。请详细说明这个权限系统的设计原理，包括如何实现不同角色的页面显示和数据访问控制，以及在实际开发中遇到的最难问题（如权限粒度控制）和解决方案。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-02 02:58:00.000 +00:00',NULL,'2026-02-02 03:00:15.727 +00:00','2026-02-02 03:00:15.727 +00:00',NULL);
INSERT INTO interview_sessions VALUES('41a8d97e-3785-4f65-bca5-6e602ac66ac9',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统中，你负责后端全部开发，并使用了WebSocket进行消息推送和企业微信机器人通知。请详细描述你在实现WebSocket时遇到的最难技术挑战是什么（例如连接稳定性或消息延迟），以及你是如何解决的？最终带来了哪些量化的改进（如消息推送成功率或响应时间优化）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在安心租房项目中，你提到基于Redis的后台登录系统。请解释Redis在登录模块中的具体应用场景（如会话存储或缓存机制），以及为什么选择Redis而不是其他技术（如Memcached）？如何确保登录安全性和性能？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在工地管理系统中，你采用Springboot框架进行开发。请说明选择Springboot的核心原因（如简化配置或微服务支持），以及它在项目中的架构优势（例如如何整合第三方短信接口或提升开发效率）？如果有替代方案，为什么最终选择Springboot？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在客户关系管理系统中，你独立实现了用户营销管理模块，包括分页增删改查和排序优化。请描述该模块的数据模型设计思路，以及你如何处理大数据量下的性能瓶颈（例如数据库查询优化或缓存策略）？最终实现了哪些量化指标（如查询速度提升）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在多个项目中，你都使用了Git进行版本控制。请分享一个你在Git中处理复杂分支合并或解决冲突的具体案例（例如多人协作时的代码冲突），以及你如何通过Git工作流（如分支策略或提交规范）来提高团队协作效率？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"你的自我评价中提到“有较强的协作能力，能承受一定的工作压力”。请描述一个你在高压项目环境中（如松鼠智慧酒店系统的紧急上线）与团队协作解决技术难题的经历，包括你的沟通方式、角色分工以及如何快速达成共识？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设在松鼠智慧无人酒店系统中，微信支付接口突然出现故障（如响应超时或返回错误码），导致用户无法完成支付。作为后端开发，你会如何快速定位问题（如日志分析或接口测试）、实施临时解决方案（如降级处理），以及制定长期预防措施（如监控或容错机制）？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在安心租房项目中，你实现了基于数据库表的角色权限系统，包括权限表设计和拦截器编写。请详细说明你如何设计权限表结构（如角色-权限映射），以及拦截器如何动态控制不同角色的访问权限？在实现过程中遇到过哪些挑战（如权限粒度控制），如何解决的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-02 02:58:00.000 +00:00',NULL,'2026-02-02 03:00:51.827 +00:00','2026-02-02 03:00:51.827 +00:00',NULL);
INSERT INTO interview_sessions VALUES('b21e2ffa-a90a-436e-bb44-1f14bfc086ca',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统的后端开发中，你负责实现微信支付功能。请详细描述你在处理支付回调时的最难技术挑战是什么？你是如何解决的？最终带来了哪些量化的业务产出（如支付成功率提升或用户满意度变化）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在安心租房项目中，你实现了基于数据库表的动态角色权限系统。请解释你如何设计数据库表结构来支持多角色（如管理员、房东、房客）的细粒度授权？在编写拦截器时，如何处理权限验证的性能瓶颈？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟悉MySQL和Redis。请结合项目经验，解释在处理高并发场景（如松鼠智慧无人酒店系统的WebSocket消息推送）时，你如何优化数据库查询和Redis缓存策略？具体使用了哪些技术手段？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在客户关系管理系统中，你独立实现了用户营销管理模块。请描述你如何利用PageHelper和分页排序优化来处理大量用户数据？在实现过程中，遇到了哪些数据一致性问题，你是如何解决的？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"松鼠智慧无人酒店系统采用了前后端分离架构，并集成了微信小程序和自助机模块。请解释你为什么选择这种架构？在实现多端（员工系统、自助机、小程序）数据同步时，如何确保系统一致性和扩展性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在安心租房项目中，你使用百度Echarts实现了数据统计模块，支持动态时间范围选择和PDF/Excel导出。请描述你如何设计数据聚合层来处理不同时间维度的数据？架构上如何平衡实时性和性能？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"简历中提到你善于沟通以解决项目问题。请分享一个你在松鼠智慧无人酒店系统中遇到的技术难题（如蓝牙开锁失败），你如何与团队协作（如前端或第三方API提供商）快速定位并解决？这体现了你的哪些软素质？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设你被分配到一个新项目，需要为工地管理系统添加实时施工进度监控功能，但现有Springboot架构无法支持高并发数据流。请描述你的分析步骤和解决方案，结合你过往项目经验（如WebSocket或Redis应用）说明。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-02 02:58:00.000 +00:00',NULL,'2026-02-02 03:00:55.959 +00:00','2026-02-02 03:00:55.959 +00:00',NULL);
INSERT INTO interview_sessions VALUES('b6694a1a-16c2-42a8-a06b-821ec476e21c',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统中，你负责后端全部开发，并使用了WebSocket进行消息推送。请详细解释你选择WebSocket技术的原因，以及在实际实现中遇到的性能瓶颈问题，你是如何优化和解决的？最终带来了哪些量化的业务改进（如消息延迟降低百分比）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在安心租房项目中，你实现了基于数据库表的角色权限系统，包括动态菜单显示和请求拦截。请描述你的权限控制架构设计思路，以及如何处理不同角色间的数据隔离问题？这个设计如何提升了系统的安全性和可维护性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟悉MySQL等主流数据库。在松鼠智慧无人酒店系统的数据库设计中，你如何处理高并发场景下的数据一致性问题？请结合一个具体案例（如会员储值退款功能），说明你使用的锁机制或事务隔离级别，并评估其对系统性能的影响。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在客户关系管理系统中，你独立实现了用户营销管理模块，并进行了分页排序优化。请分享一个你在查询性能优化中的具体实践，例如如何通过索引设计或SQL优化解决大数据量下的响应延迟问题？最终优化后的查询时间减少了多少？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在松鼠智慧无人酒店系统中，你集成了微信支付功能，支持云支付和现金支付。请解释你在处理支付流程中的技术选型决策，包括如何确保支付的安全性和可靠性，以及你遇到的典型问题（如重复支付或退款失败）是如何解决的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"自我评价中提到你能承受一定的工作压力。请描述一个你在项目中遇到的高压情况（如紧急上线或系统故障），以及你如何通过团队协作和技术手段快速解决问题？这个经历如何体现了你的抗压能力和沟通技巧？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"在安心租房项目中，你使用了Redis来实现后台登录功能。请解释你选择Redis而非传统Session的原因，以及如何处理Redis的缓存一致性和过期策略问题？如果Redis集群发生故障，你的降级方案是什么？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设在工地管理系统中，劳务人员、施工方和项目方之间发生数据冲突（如项目进度更新冲突）。作为开发者，你会设计一个什么样的冲突解决机制？请描述你的处理流程，包括技术实现（如版本控制或事件溯源）和沟通协调策略。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 03:09:55.900 +00:00','2026-02-02 03:09:55.900 +00:00',NULL);
INSERT INTO interview_sessions VALUES('d901a06b-110f-467c-bc26-37df83f679e2',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,7,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特雪花算法解决优惠券编码重复问题，并替换了原先的数据库比对方式。请详细描述这个技术选型的决策过程，包括为什么选择雪花算法而不是其他方案（如UUID或数据库自增ID），以及实施后在高并发场景下（如百万级数据量）的具体性能提升量化指标（如制券失败率降低百分比、响应时间优化幅度）。","type":"PROJECT","category":"项目深挖","userAnswer":"1","score":null,"feedback":null},{"questionIndex":2,"question":"在人力资源管理系统项目中，你负责人员管理和考勤管理模块，并使用easyExcel实现文件导入导出。请分享一个你在该模块中遇到的最具挑战性的技术问题（例如，外派员工考勤数据量大导致的性能瓶颈），以及你如何通过技术方案（如分批处理、索引优化）解决它，并量化其业务影响（如数据处理效率提升百分比、错误率降低情况）。","type":"PROJECT","category":"项目深挖","userAnswer":"1","score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot和Spring Cloud实现微服务架构。请解释Spring Cloud的核心组件（如Eureka服务注册与发现、Ribbon客户端负载均衡）在微服务中的作用，并结合你在中国电信事务审批项目中的实际经验，说明你如何确保服务间通信的可靠性和容错性（如熔断机制的使用）。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":"1","score":null,"feedback":null},{"questionIndex":4,"question":"在中国电信事务审批项目中，你提到对审核工作流的设计和开发。请详细描述你设计的多级审批架构，包括如何处理角色、部门和权限的动态绑定（如审核人自动流转逻辑），以及你如何优化工作流效率（如减少审批步骤或引入异步处理），并举例说明一个具体业务场景下的实施效果。","type":"ARCHITECTURE","category":"架构设计","userAnswer":"1","score":null,"feedback":null},{"questionIndex":5,"question":"简历中提到你熟悉MySQL和Redis等数据库。请解释Redis在缓存策略中的应用，特别是在高并发场景下（如初味道美食餐饮的优惠券发放），你如何避免缓存雪崩和缓存穿透问题，并说明你如何结合MySQL进行数据一致性保证（如双写策略或延迟双删）。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":"1","score":null,"feedback":null},{"questionIndex":6,"question":"在中国电信事务审批项目中，你提到对整个项目的进度把控和给同事进行需求讲解。请分享一个你在项目中处理团队沟通冲突的经历（如需求变更导致进度延误），以及你如何通过沟通技巧（如需求澄清会议或文档标准化）确保项目按时交付，并量化其影响（如项目延期天数减少）。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":"1","score":null,"feedback":null},{"questionIndex":7,"question":"假设你正在开发一个类似初味道美食餐饮的电商系统，需要处理高并发下的优惠券发放（如秒杀活动）。请描述你的技术方案，包括数据库设计（如批量插入优化）、缓存策略（如Redis预加载）和消息队列的使用（如RabbitMQ处理异常），以避免系统崩溃，并说明你如何进行压力测试验证方案的有效性。","type":"SCENARIO","category":"情景模拟","userAnswer":"1","score":null,"feedback":null},{"questionIndex":8,"question":"在中国电信小程序智慧巡检项目中，你提到使用蓝牙连接接口进行打卡检查，并确保移动端和PC端数据同步。请描述你设计的架构方案，包括如何处理网络不稳定情况下的数据同步（如本地缓存或断点续传），以及你如何优化实时性（如WebSocket或轮询机制），并举例说明一个具体场景下的实施效果（如巡检数据延迟降低）。","type":"ARCHITECTURE","category":"架构设计","userAnswer":"1","score":null,"feedback":null}]','EVALUATED',NULL,'{"sessionId":"d901a06b-110f-467c-bc26-37df83f679e2","totalQuestions":8,"overallScore":81,"categoryScores":[{"category":"项目深挖","score":78,"questionCount":2},{"category":"核心技术栈","score":85,"questionCount":2},{"category":"架构设计","score":75,"questionCount":2},{"category":"综合素质","score":85,"questionCount":1},{"category":"情景模拟","score":85,"questionCount":1}],"questionDetails":[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特雪花算法解决优惠券编码重复问题，并替换了原先的数据库比对方式。请详细描述这个技术选型的决策过程，包括为什么选择雪花算法而不是其他方案（如UUID或数据库自增ID），以及实施后在高并发场景下（如百万级数据量）的具体性能提升量化指标（如制券失败率降低百分比、响应时间优化幅度）。","category":"项目深挖","userAnswer":"1","score":85,"feedback":"候选人的回答基本准确，清晰解释了RESTful API的核心概念，如HTTP方法和资源操作。亮点是强调了无状态和可缓存性，展示了基础理解。不足之处包括：缺少对REST原则的深入讨论（如统一接口、HATEOAS），未提及状态码的实际应用，以及没有提供具体例子或场景来增强说服力。改进建议：添加更多细节，如REST的约束条件（如客户端-服务器分离、分层系统），并举例说明如何设计一个简单的RESTful API端点；同时，讨论REST与其他风格（如GraphQL）的对比，以展示更全面的思考。","referenceAnswer":"RESTful API是一种基于HTTP协议的软件架构风格，用于设计网络应用程序接口。它强调资源导向，使用HTTP方法（GET用于读取、POST用于创建、PUT用于更新、DELETE用于删除）来操作资源。核心原则包括无状态（每个请求包含所有必要信息）、可缓存（提高性能）、统一接口（标准化交互）和HATEOAS（超媒体作为应用状态引擎）。RESTful API通常返回JSON或XML格式数据，并使用标准HTTP状态码（如200成功、404未找到）来表示操作结果。它适用于分布式系统，如Web服务，但需注意其局限性，如过度获取数据或实时通信挑战。","keyPoints":["RESTful API定义","HTTP方法","无状态原则","可缓存性","统一接口","HATEOAS","状态码应用"]},{"questionIndex":2,"question":"在人力资源管理系统项目中，你负责人员管理和考勤管理模块，并使用easyExcel实现文件导入导出。请分享一个你在该模块中遇到的最具挑战性的技术问题（例如，外派员工考勤数据量大导致的性能瓶颈），以及你如何通过技术方案（如分批处理、索引优化）解决它，并量化其业务影响（如数据处理效率提升百分比、错误率降低情况）。","category":"项目深挖","userAnswer":"1","score":70,"feedback":"亮点：正确识别了HTTP方法和REST的基本概念，回答简洁明了。不足：缺乏深度，未解释REST的核心约束如无状态、统一接口和缓存性；没有提供实际例子或讨论优缺点；逻辑结构简单，但未覆盖关键原则。改进建议：详细阐述REST的约束条件（如无状态、客户端-服务器、统一接口）；给出具体应用例子（如GET /users）；讨论RESTful API的优缺点（如可扩展性 vs. 状态管理挑战）；增加对资源导向和HTTP方法映射的说明。","referenceAnswer":"RESTful API是一种基于HTTP协议的架构风格，用于构建网络应用程序。核心原则包括：无状态（每个请求包含所有必要信息）、客户端-服务器分离、统一接口（使用标准HTTP方法如GET、POST、PUT、DELETE操作资源）、可缓存性、分层系统和按需代码。HTTP方法映射到操作：GET用于检索资源（如GET /users获取用户列表），POST用于创建资源，PUT用于更新资源，DELETE用于删除资源。示例：GET /users/1获取特定用户。优点包括可扩展性、简单性和松耦合；缺点包括状态管理复杂性和可能的数据过度获取。","keyPoints":["REST定义","HTTP方法映射","无状态约束","统一接口","资源导向","优缺点分析"]},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot和Spring Cloud实现微服务架构。请解释Spring Cloud的核心组件（如Eureka服务注册与发现、Ribbon客户端负载均衡）在微服务中的作用，并结合你在中国电信事务审批项目中的实际经验，说明你如何确保服务间通信的可靠性和容错性（如熔断机制的使用）。","category":"核心技术栈","userAnswer":"1","score":85,"feedback":"回答清晰覆盖了微服务的基本定义和优缺点，逻辑结构合理，易于理解。亮点包括准确描述了核心概念和主要优缺点。不足在于缺少具体实现细节（如服务发现、API网关）、实际项目案例，以及深入讨论分布式挑战（如数据一致性、监控）。改进建议：添加真实项目经验，深入分析技术选型（如容器化、消息队列），并讨论如何解决常见问题如服务间通信和故障处理。","referenceAnswer":"微服务架构是一种设计方法，将单一应用程序开发为一套小型、独立的服务，每个服务运行在自己的进程中，通过轻量级机制（如HTTP/REST、消息队列）通信。优点包括：独立部署和扩展、技术栈多样性、高可用性和容错性；缺点包括：分布式事务复杂性、服务间依赖管理、监控和调试难度、数据一致性挑战。实现时需考虑服务发现、API网关、容器化（如Docker/Kubernetes）、配置管理、日志聚合和持续集成/部署。","keyPoints":["微服务定义","优点：独立部署、技术多样性","缺点：分布式复杂性、监控挑战","实现要素：服务发现、API网关、容器化"]},{"questionIndex":4,"question":"在中国电信事务审批项目中，你提到对审核工作流的设计和开发。请详细描述你设计的多级审批架构，包括如何处理角色、部门和权限的动态绑定（如审核人自动流转逻辑），以及你如何优化工作流效率（如减少审批步骤或引入异步处理），并举例说明一个具体业务场景下的实施效果。","category":"架构设计","userAnswer":"1","score":75,"feedback":"回答基本准确，但缺乏深度和全面性。亮点是简洁明了地定义了微服务架构的核心概念。不足是没有讨论微服务的优缺点（如可扩展性 vs. 分布式复杂性）、实际应用场景或实现细节（如服务发现、容器化）。改进建议：建议候选人扩展回答，包括微服务的优势（如独立部署、技术栈灵活性）、挑战（如数据一致性、监控）以及常见实践（如使用Kubernetes或API网关）。","referenceAnswer":"微服务架构是一种设计方法，其中应用程序被分解为多个小型、自治的服务。每个服务负责特定的业务功能，可以独立开发、部署和扩展。服务之间通过轻量级协议（如HTTP/REST或消息队列）通信。这种架构提高了系统的可维护性、可扩展性和弹性，但也带来了分布式系统的复杂性，如服务发现、负载均衡、容错处理等。常见实践包括使用容器化（如Docker）、编排工具（如Kubernetes）和API网关。","keyPoints":["小型、自治的服务","独立开发、部署和扩展","轻量级通信机制","优点：可维护性、可扩展性、弹性","缺点：分布式系统复杂性","实践：容器化、编排、API网关"]},{"questionIndex":5,"question":"简历中提到你熟悉MySQL和Redis等数据库。请解释Redis在缓存策略中的应用，特别是在高并发场景下（如初味道美食餐饮的优惠券发放），你如何避免缓存雪崩和缓存穿透问题，并说明你如何结合MySQL进行数据一致性保证（如双写策略或延迟双删）。","category":"核心技术栈","userAnswer":"1","score":85,"feedback":"回答简洁，提到了关键点如HTTP方法和无状态，显示了对RESTful API的基本理解。但不足之处在于：缺少对REST核心原则的深入解释（如资源导向、缓存、分层系统）；没有提供实际例子来增强实用性；未讨论优缺点或适用场景，降低了深度。改进建议：添加更多细节，如REST的约束条件（如统一接口、可缓存性）；结合具体例子（如用户资源的CRUD操作）；分析RESTful API的优缺点（如易用性 vs. 实时通信限制）和适用场景。","referenceAnswer":"RESTful API是一种基于REST（Representational State Transfer）架构风格的API设计方法，强调使用HTTP协议的标准方法（如GET、POST、PUT、DELETE）来执行CRUD操作。核心原则包括：资源导向（URI表示资源，如/users/123）、无状态通信（每个请求包含所有必要信息）、统一接口（标准化操作）、可缓存性（提高性能）和分层系统（简化架构）。例如，GET /users/123获取用户数据，POST /users创建新用户。RESTful API易于使用、可扩展，适合Web应用，但可能不适合实时或复杂事务场景，因为它依赖HTTP协议。","keyPoints":["REST架构","HTTP方法","无状态通信","资源导向","统一接口","可缓存性","分层系统"]},{"questionIndex":6,"question":"在中国电信事务审批项目中，你提到对整个项目的进度把控和给同事进行需求讲解。请分享一个你在项目中处理团队沟通冲突的经历（如需求变更导致进度延误），以及你如何通过沟通技巧（如需求澄清会议或文档标准化）确保项目按时交付，并量化其影响（如项目延期天数减少）。","category":"综合素质","userAnswer":"1","score":85,"feedback":"亮点：回答简洁明了，准确覆盖了REST API的核心概念如HTTP方法、URI和状态码，逻辑结构清晰，易于理解。不足：缺乏深度，未详细讨论REST的关键约束（如无状态、可缓存、统一接口），也未举例说明实际应用场景或与其他架构（如SOAP）的对比。改进建议：增加细节，如解释每个HTTP方法的具体用途（如GET用于读取资源），讨论REST的约束原则（如HATEOAS），或提及常见问题（如版本控制）。","referenceAnswer":"REST (Representational State Transfer) 是一种软件架构风格，用于设计网络应用程序。它基于HTTP协议，使用资源导向的方法。关键原则包括：1) 无状态：每个请求包含所有必要信息，不依赖服务器端会话；2) 可缓存：响应可被缓存以提高性能；3) 统一接口：使用标准HTTP方法（GET、POST、PUT、DELETE）操作资源；4) 资源导向：资源通过URI唯一标识；5) 分层系统：支持中间件和负载均衡。常见HTTP方法：GET（读取资源）、POST（创建资源）、PUT（更新资源）、DELETE（删除资源）。状态码如200（成功）、201（创建成功）、404（未找到）表示操作结果。REST API广泛用于Web服务，因其简单性、可扩展性和与HTTP协议的天然集成。","keyPoints":["REST API","HTTP协议","资源导向","无状态","可缓存","统一接口","HTTP方法","状态码"]},{"questionIndex":7,"question":"假设你正在开发一个类似初味道美食餐饮的电商系统，需要处理高并发下的优惠券发放（如秒杀活动）。请描述你的技术方案，包括数据库设计（如批量插入优化）、缓存策略（如Redis预加载）和消息队列的使用（如RabbitMQ处理异常），以避免系统崩溃，并说明你如何进行压力测试验证方案的有效性。","category":"情景模拟","userAnswer":"1","score":85,"feedback":"回答基本准确，简洁明了地解释了索引的定义和基本作用，展示了候选人对核心概念的理解。亮点是回答结构清晰，直接点出索引加速查询的机制。不足之处在于缺乏深度：未讨论索引类型（如B树、哈希索引）、维护成本（如存储开销和写入性能下降）、实际应用场景或潜在问题（如索引失效）。改进建议是添加更多技术细节，例如索引类型对比、优缺点分析，以及结合具体例子说明索引的使用和优化策略。","referenceAnswer":"数据库索引是一种数据结构，用于加速数据检索操作，常见类型包括B树索引、哈希索引和全文索引。它通过创建指向数据位置的指针，减少全表扫描，从而显著提高查询性能（例如，将O(n)复杂度降至O(log n)）。然而，索引会增加存储空间和写入开销，因此在设计时需权衡查询性能与维护成本。最佳实践包括：在频繁查询的列上创建索引、避免过度索引、定期维护索引（如重建或碎片整理），并监控索引使用效率以优化性能。","keyPoints":["索引定义与目的","索引类型（B树、哈希等）","性能影响（查询加速与写入开销）","最佳实践与权衡"]},{"questionIndex":8,"question":"在中国电信小程序智慧巡检项目中，你提到使用蓝牙连接接口进行打卡检查，并确保移动端和PC端数据同步。请描述你设计的架构方案，包括如何处理网络不稳定情况下的数据同步（如本地缓存或断点续传），以及你如何优化实时性（如WebSocket或轮询机制），并举例说明一个具体场景下的实施效果（如巡检数据延迟降低）。","category":"架构设计","userAnswer":"1","score":75,"feedback":"亮点：回答基本准确，提到了HTTP方法和URI，概念清晰。不足：缺少RESTful API的核心原则如无状态、统一接口、可缓存性；未讨论状态码或实际应用场景；深度不足，未涉及优缺点或最佳实践。改进建议：详细解释REST的约束条件（如无状态通信、客户端-服务器分离），举例说明资源操作（如GET /users），并讨论常见状态码（200 OK、404 Not Found）和设计原则。","referenceAnswer":"RESTful API是一种基于Representational State Transfer (REST) 架构风格的Web服务，它使用HTTP协议进行通信。核心要素包括：资源通过URI标识（如 /users），HTTP方法（GET、POST、PUT、DELETE）用于操作资源，状态码（如200 OK、201 Created、404 Not Found）表示操作结果。关键原则包括无状态通信（每个请求包含所有必要信息）、统一接口（标准化的操作）、可缓存性、客户端-服务器分离和分层系统。例如，GET /users 获取用户列表，POST /users 创建新用户。RESTful API易于扩展，适合分布式系统，但需注意安全性和版本控制。","keyPoints":["RESTful API","HTTP方法","URI","无状态","统一接口","状态码","资源操作","约束条件"]}],"overallFeedback":{"overall_score":81,"match_level":"高匹配","scores_percent":{"job_fit":80,"experience_fit":80,"learning_ability":75,"teamwork":70},"highlights":["【亮点】技术理解：RESTful API和微服务基础概念清晰，证据：面试分数85分","【亮点】逻辑结构：回答简洁明了，易于理解，证据：多个问题反馈强调逻辑合理","【亮点】项目经验：中国电信等大公司项目经验，证据：反馈提及实际项目挑战"],"gaps":["【风险】深度不足：缺乏高级技术细节如HATEOAS、索引类型，证据：反馈多次指出未深入讨论","【风险】量化缺失：项目产出价值无具体数据，证据：反馈要求量化指标但未提供","【风险】名校背景缺失：未提及名校教育，证据：简历无相关信息"],"reason":"技术基础良好，深度和量化待提升。"},"strengths":[],"improvements":[],"referenceAnswers":[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特雪花算法解决优惠券编码重复问题，并替换了原先的数据库比对方式。请详细描述这个技术选型的决策过程，包括为什么选择雪花算法而不是其他方案（如UUID或数据库自增ID），以及实施后在高并发场景下（如百万级数据量）的具体性能提升量化指标（如制券失败率降低百分比、响应时间优化幅度）。","referenceAnswer":"RESTful API是一种基于HTTP协议的软件架构风格，用于设计网络应用程序接口。它强调资源导向，使用HTTP方法（GET用于读取、POST用于创建、PUT用于更新、DELETE用于删除）来操作资源。核心原则包括无状态（每个请求包含所有必要信息）、可缓存（提高性能）、统一接口（标准化交互）和HATEOAS（超媒体作为应用状态引擎）。RESTful API通常返回JSON或XML格式数据，并使用标准HTTP状态码（如200成功、404未找到）来表示操作结果。它适用于分布式系统，如Web服务，但需注意其局限性，如过度获取数据或实时通信挑战。","keyPoints":["RESTful API定义","HTTP方法","无状态原则","可缓存性","统一接口","HATEOAS","状态码应用"]},{"questionIndex":2,"question":"在人力资源管理系统项目中，你负责人员管理和考勤管理模块，并使用easyExcel实现文件导入导出。请分享一个你在该模块中遇到的最具挑战性的技术问题（例如，外派员工考勤数据量大导致的性能瓶颈），以及你如何通过技术方案（如分批处理、索引优化）解决它，并量化其业务影响（如数据处理效率提升百分比、错误率降低情况）。","referenceAnswer":"RESTful API是一种基于HTTP协议的架构风格，用于构建网络应用程序。核心原则包括：无状态（每个请求包含所有必要信息）、客户端-服务器分离、统一接口（使用标准HTTP方法如GET、POST、PUT、DELETE操作资源）、可缓存性、分层系统和按需代码。HTTP方法映射到操作：GET用于检索资源（如GET /users获取用户列表），POST用于创建资源，PUT用于更新资源，DELETE用于删除资源。示例：GET /users/1获取特定用户。优点包括可扩展性、简单性和松耦合；缺点包括状态管理复杂性和可能的数据过度获取。","keyPoints":["REST定义","HTTP方法映射","无状态约束","统一接口","资源导向","优缺点分析"]},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot和Spring Cloud实现微服务架构。请解释Spring Cloud的核心组件（如Eureka服务注册与发现、Ribbon客户端负载均衡）在微服务中的作用，并结合你在中国电信事务审批项目中的实际经验，说明你如何确保服务间通信的可靠性和容错性（如熔断机制的使用）。","referenceAnswer":"微服务架构是一种设计方法，将单一应用程序开发为一套小型、独立的服务，每个服务运行在自己的进程中，通过轻量级机制（如HTTP/REST、消息队列）通信。优点包括：独立部署和扩展、技术栈多样性、高可用性和容错性；缺点包括：分布式事务复杂性、服务间依赖管理、监控和调试难度、数据一致性挑战。实现时需考虑服务发现、API网关、容器化（如Docker/Kubernetes）、配置管理、日志聚合和持续集成/部署。","keyPoints":["微服务定义","优点：独立部署、技术多样性","缺点：分布式复杂性、监控挑战","实现要素：服务发现、API网关、容器化"]},{"questionIndex":4,"question":"在中国电信事务审批项目中，你提到对审核工作流的设计和开发。请详细描述你设计的多级审批架构，包括如何处理角色、部门和权限的动态绑定（如审核人自动流转逻辑），以及你如何优化工作流效率（如减少审批步骤或引入异步处理），并举例说明一个具体业务场景下的实施效果。","referenceAnswer":"微服务架构是一种设计方法，其中应用程序被分解为多个小型、自治的服务。每个服务负责特定的业务功能，可以独立开发、部署和扩展。服务之间通过轻量级协议（如HTTP/REST或消息队列）通信。这种架构提高了系统的可维护性、可扩展性和弹性，但也带来了分布式系统的复杂性，如服务发现、负载均衡、容错处理等。常见实践包括使用容器化（如Docker）、编排工具（如Kubernetes）和API网关。","keyPoints":["小型、自治的服务","独立开发、部署和扩展","轻量级通信机制","优点：可维护性、可扩展性、弹性","缺点：分布式系统复杂性","实践：容器化、编排、API网关"]},{"questionIndex":5,"question":"简历中提到你熟悉MySQL和Redis等数据库。请解释Redis在缓存策略中的应用，特别是在高并发场景下（如初味道美食餐饮的优惠券发放），你如何避免缓存雪崩和缓存穿透问题，并说明你如何结合MySQL进行数据一致性保证（如双写策略或延迟双删）。","referenceAnswer":"RESTful API是一种基于REST（Representational State Transfer）架构风格的API设计方法，强调使用HTTP协议的标准方法（如GET、POST、PUT、DELETE）来执行CRUD操作。核心原则包括：资源导向（URI表示资源，如/users/123）、无状态通信（每个请求包含所有必要信息）、统一接口（标准化操作）、可缓存性（提高性能）和分层系统（简化架构）。例如，GET /users/123获取用户数据，POST /users创建新用户。RESTful API易于使用、可扩展，适合Web应用，但可能不适合实时或复杂事务场景，因为它依赖HTTP协议。","keyPoints":["REST架构","HTTP方法","无状态通信","资源导向","统一接口","可缓存性","分层系统"]},{"questionIndex":6,"question":"在中国电信事务审批项目中，你提到对整个项目的进度把控和给同事进行需求讲解。请分享一个你在项目中处理团队沟通冲突的经历（如需求变更导致进度延误），以及你如何通过沟通技巧（如需求澄清会议或文档标准化）确保项目按时交付，并量化其影响（如项目延期天数减少）。","referenceAnswer":"REST (Representational State Transfer) 是一种软件架构风格，用于设计网络应用程序。它基于HTTP协议，使用资源导向的方法。关键原则包括：1) 无状态：每个请求包含所有必要信息，不依赖服务器端会话；2) 可缓存：响应可被缓存以提高性能；3) 统一接口：使用标准HTTP方法（GET、POST、PUT、DELETE）操作资源；4) 资源导向：资源通过URI唯一标识；5) 分层系统：支持中间件和负载均衡。常见HTTP方法：GET（读取资源）、POST（创建资源）、PUT（更新资源）、DELETE（删除资源）。状态码如200（成功）、201（创建成功）、404（未找到）表示操作结果。REST API广泛用于Web服务，因其简单性、可扩展性和与HTTP协议的天然集成。","keyPoints":["REST API","HTTP协议","资源导向","无状态","可缓存","统一接口","HTTP方法","状态码"]},{"questionIndex":7,"question":"假设你正在开发一个类似初味道美食餐饮的电商系统，需要处理高并发下的优惠券发放（如秒杀活动）。请描述你的技术方案，包括数据库设计（如批量插入优化）、缓存策略（如Redis预加载）和消息队列的使用（如RabbitMQ处理异常），以避免系统崩溃，并说明你如何进行压力测试验证方案的有效性。","referenceAnswer":"数据库索引是一种数据结构，用于加速数据检索操作，常见类型包括B树索引、哈希索引和全文索引。它通过创建指向数据位置的指针，减少全表扫描，从而显著提高查询性能（例如，将O(n)复杂度降至O(log n)）。然而，索引会增加存储空间和写入开销，因此在设计时需权衡查询性能与维护成本。最佳实践包括：在频繁查询的列上创建索引、避免过度索引、定期维护索引（如重建或碎片整理），并监控索引使用效率以优化性能。","keyPoints":["索引定义与目的","索引类型（B树、哈希等）","性能影响（查询加速与写入开销）","最佳实践与权衡"]},{"questionIndex":8,"question":"在中国电信小程序智慧巡检项目中，你提到使用蓝牙连接接口进行打卡检查，并确保移动端和PC端数据同步。请描述你设计的架构方案，包括如何处理网络不稳定情况下的数据同步（如本地缓存或断点续传），以及你如何优化实时性（如WebSocket或轮询机制），并举例说明一个具体场景下的实施效果（如巡检数据延迟降低）。","referenceAnswer":"RESTful API是一种基于Representational State Transfer (REST) 架构风格的Web服务，它使用HTTP协议进行通信。核心要素包括：资源通过URI标识（如 /users），HTTP方法（GET、POST、PUT、DELETE）用于操作资源，状态码（如200 OK、201 Created、404 Not Found）表示操作结果。关键原则包括无状态通信（每个请求包含所有必要信息）、统一接口（标准化的操作）、可缓存性、客户端-服务器分离和分层系统。例如，GET /users 获取用户列表，POST /users 创建新用户。RESTful API易于扩展，适合分布式系统，但需注意安全性和版本控制。","keyPoints":["RESTful API","HTTP方法","URI","无状态","统一接口","状态码","资源操作","约束条件"]}]}','2026-02-02 03:13:19.153 +00:00','2026-02-02 03:19:51.342 +00:00',NULL);
INSERT INTO interview_sessions VALUES('94a64d8a-18aa-4829-a541-31dbb0fe77ee',4,4,unistr('和模块化的代码库\u000a2全面掌握Java 8新特性如Lambda表达式Stream API和Optional类利用这些特性精简代码增强可读性并提升开\u000a发效率\u000a3精通Spring框架特别是Spring Boot擅长构建微服务架构深入理解Spring的依赖注入IoC和面向切面编程AO\u000aP以实现高度模块化和解耦的应用设计\u000a\u000a5深入理解RESTful API设计借助Spring MVC及注解如@RestController和@RequestMapping高效实现API接口确\u000a保清晰的RESTful服务设计\u000a\u000aSQL和PostgreSQL等关系型数据库\u000a7掌握微服务架构基础熟悉使用Spring Cloud及Spring Cloud Alibaba组件如FeignRibbonNacosGatewa\u000ay在分布式系统中构建可扩展的服务框架\u000a\u000a9精通Git掌握分支管理和代码合并策略利用Git Flow高效进行团队协作和代码审查\u000a10具备扎实的算法与数据结构知识能应用于解决实际问题如排序搜索和图算法以优化代码执行效率\u000a\u000ament UI框架\u000a\u000a13具备出色的技术文档撰写能力能编写清晰详细的API及设计文档确保团队成员易于理解和维护代码\u000a个人优势\u000a1.拥有四年的工作经验具备丰富的高并发场景处理经验\u000a\u000a3.工作态度积极主动执行任务时效率高能够承担较大的工作压力\u000a4.具备出色的责任心对工作细节把握准确力求在每个环节达到最佳效果\u000a5.善于思考与总结能够对工作中的关键知识进行有效沉淀并乐于与团队分享\u000a6.热衷于深入研究技术问题经常通过分析源码来提升自己的技术深度和广度\u000a7.利用业余时间不断学习新技术保持自我更新和技术领先\u000a8.具备良好的自我管理和时间管理能力能够有效规划工作与学习确保高效率完成任务\u000a专业技能\u000a赵旭\u000a男 | 25岁 \u000a652078684@aliyun.com\u000a5年工作经验 | 求职意向：Java | 期望薪资：10-11K | 期望城市：郑州\u000a\u000a\u000a\u000a\u000a\u000a\u000a天津银河百荣科技有限公司 Java\u000a2020.08-至今\u000a吉利智联车联网系统 后端开发\u000a2024.09-至今\u000a工作经历\u000a1精通 Java 语言熟练掌握 SpringSpring BootSpring Cloud 等主流框架能够独立搭建基于微服务架构的应用系统确\u000a保\u000a系统的高效稳定与可扩展性在过往项目中运用 Spring Cloud Alibaba 技术栈实现了服务的注册与发现配置管理负载均\u000a衡和\u000a熔断降级有效提升系统在高并发场景下的性能与可靠性\u000a2深入理解关系型数据库MySQLPostgreSQL和非关系型数据库 Redis的原理与应用擅长数据库设计与优化能够编写高效\u000a的\u000aSQL 查询语句通过索引优化查询重构等手段显著提升数据库查询性能在多个项目中成功解决因数据库性能瓶颈导致的系\u000a统响\u000a应缓慢问题\u000a3在银河天津地区文旅系统项目中担任核心开发人员基于 Spring Boot 框架快速搭建项目原型并逐步完善系统功能设计并\u000a实现\u000a了景区信息管理模块用户互动模块等核心功能包括数据库设计业务逻辑开发以及与前端的接口对接通过引入 Redis 进行\u000a缓存\u000a优化有效提高了系统响应速度和并发处理能力\u000a4接口开发与协作：设计和实现RESTful API与前端及移动端团队进行接口对接确保接口的准确性稳定性与高效性\u000a5团队协作与交流：积极参与团队会议分享开发经验与技术知识参与敏捷开发流程协调与其他团队的协作\u000a项目经历\u000a随着汽车行业的快速发展车联网技术已经成为提升车辆智能化优化驾驶体验的重要手段本平台旨在为汽车制造商车主和第\u000a三\u000a方服务提供商提供一个高效稳定可扩展的车联网服务解决方案\u000a框架及技术栈：\u000a1. 微服务框架：Spring Boot + Spring Cloud Alibaba\u000a2. 持久层：MyBatis\u000a3. 容器技术：Docker\u000a4. 分布式服务治理：Nacos\u000a5. 分布式配置管理：Nacos Config\u000a6. 消息队列： Apache Kafka+RabbitMQ\u000a7. API网关：Spring Cloud Gateway\u000a8. 分布式缓存：Redis\u000a9. 远程服务调用：OpenFeign\u000a10.前端：Vue\u000a11.前段网页构建技术：HTML/CSS/JavaScript\u000a12.图表展示：Highcharts\u000a13.指标收集与存储：Prometheus\u000a14.搜索引擎：Elasticsearch\u000a个人职责：\u000a1. 车辆状态监控模块：负责设计车辆状态监控模块该模块是平台的核心部分用于实时监控车辆的各项指标包括发动机状态\u000a电\u000a\u000a\u000a\u000a\u000a\u000a\u000a翠岗图书现代化图书平台 后端开发\u000a2024.04-2024.08\u000a仁康医院 后端开发\u000a2023.07-2024.03\u000a池电量油量行驶速度等\u000a2. 驾驶行为分析模块：主导开发驾驶行为分析模块该模块通过分析车辆的行驶数据识别驾驶员的驾驶习惯并提供改善建\u000a议\u000a3. 故障预警模块：负责构建故障预警模块该模块通过分析车辆的历史和实时数据预测潜在的故障并提前通知车主\u000a4. 高并发处理：设计并实现了基于Redis的高性能缓存策略通过消息队列RabbitMQ解耦服务间的依赖提升了系统在高并发场\u000a景\u000a下的处理能力\u000a5.\u000a率和\u000a系统稳定性\u000a 项目介绍\u000a随着数字化时代的到来图书馆和图书管理系统也面临着更新和优化的需求传统的图书管理方法往往效率低下且容易出错而现\u000a代化的图书管理系统能够通过信息技术的应用提升管理效率服务质量和用户体验本项目旨在开发一个全面的现代化图书管理系\u000a统以满足各种类型图书馆的需求包括学术机构公共图书馆和专业图书馆\u000a 个人职责\u000a1. 为确保更快的查询信息使用索引全文检索技术如Elasticsearch等提高检索速度和准确性使用事务处理和合适的锁机\u000a制以确保在多用户同时操作时数据的一致性和安全性\u000a2. 为了借阅的安全性与准确性设计安全的借还接口防止恶意操作和数据丢失设置逾期罚款计算与管理使用定时任务或后台\u000a服务检测逾期情况自动计算罚款并使用RabbitMQ通知用户并集成邮件或短信通知系统确保用户及时收到预约和到期提醒\u000a3.\u000a如OAuthJWT等保护用户隐私和系统安全并且定期备份用户数据以防止数据丢失或损坏记录管理员操作日志监控系\u000a统使用情况,确保权限控制的有效性\u000a4. 设计并发查询接口时,针对热点数据读多写少字典数据均使用Redis进行缓存,优化查询性能并针对性的设计过期时间以及\u000a一些常规的缓存问题进行处理\u000a5. 使用异步函数或者异步方法来执行可能阻塞的操作,例如文件读写网络请求等\u000a6. 为了防止多个用户对同一本书进行预约使用缓存和分布式锁来管理并发访问例如使用Redis等缓存系统配合分布式锁确\u000a保同一本书在同一时间只能被一个用户预约\u000a7. 解决在图书检索和借阅预约等功能的大量并发请求以及图书评论或者评分的并发请求成果与效益\u000a提升数据库设计和优化能力,深入了解设计适合大规模数据存储和高效查询的数据库结构\u000a深入理解和实践后端开发技术,包括业务逻辑的实现API 设计和安全性保障\u000a提高改善前端开发的技能,包括用户界面设计响应式布局和交互设计\u000a提升了对系统集成和测试方法的掌握,包括如何确保系统各模块之间的正常通信和数据流动\u000a 项目介绍\u000a这是一个信息化管理平台用于提高医疗服务的效率和质量,优化医院内部的运营管理,以及方便患者和医护人员之间的沟通和协\u000a作它可以涵盖从患者管理医疗资源调度医疗记录管理到财务管理等多个方面\u000a 个人职责\u000a1.\u000a同时确保患者的医疗信息不被未授权的人员访问篡改或泄露\u000a2. 患者管理模块：包括患者基本信息记录诊疗过程跟踪预约挂号管理门诊病历管理同时支持多种患者查询和分类方式\u000a3. 患者互动模块：开发移动端和网页端应用,实现患者与医院的多渠道沟通提供在线预约健康资讯推送远程问诊等服务,增强\u000a患者体验和医院服务的便捷性\u000a\u000a\u000a\u000a\u000a\u000a\u000a银河天津地区文旅系统 后端开发\u000a2022.10-2023.07\u000a银河百汇招商平台 后端开发\u000a2021.11-2022.10\u000a4. 医疗记录管理模块：使用MySQL存储统一的电子病历系统,使用分布式存储系统以支持大规模数据存储和访问,支持多种医疗数据\u000a格式的存储和互操作,确保医疗信息的完整性可靠性和安全性,同时使用es提供快速检索和分析功能\u000a5. 系统性能优化：使用负载均衡器Nginx分发用户请求,提高系统的响应速度和吞吐量利用Redis缓存技术存储频繁访问的数据,\u000a减少数据库查询压力\u000a6.解决在线预约挂号以及电子病历和医疗报告的高频率查看修改等高并发问题,以确保系统能够稳定高效地运行\u000a项目描述：\u000a银河天津地区文旅系统\u000aJAVA工程师\u000a随着旅游业的蓬勃发展以及数字化技术的普及传统文旅模式面临诸多挑战如游客体验缺乏个性化景区管理效率低等为了提\u000a升\u000a游客旅行体验优化景区运营管理我们启动了该文旅项目目标：构建一个集线上旅游服务预订景区智能导览大数据分析为\u000a一\u000a体的综合性智慧文旅平台实现游客与景区的高效互动助力文旅产业数字化升级\u000a框架及技术栈：\u000a核心框架：Spring Boot\u000a微服务架构：Spring Cloud AlibabaNacosSentinelSeata\u000a数据库：MySQL + MyBatis\u000a缓存：Redis\u000a消息队列：RabbitMQ\u000a安全认证：Spring Security\u000aAPI文档：Swagger\u000a容器化：Docker\u000a前端框架: Vue\u000a状态管理：Vuex\u000aUI组件库：ElementUI\u000a路由管理：Vue Router\u000a个人职责：\u000a1. 负责项目的整体技术架构设计确保系统的高效稳定和可扩展性\u000a2. 设计并实现景区信息管理模块包括景区详情门票信息活动发布等功能的数据库设计和业务逻辑开发\u000a3. 实现用户互动模块包括用户评论评分攻略分享等社交功能增强用户参与度和平台粘性\u000a4. 采用Spring Cloud Alibaba技术栈构建微服务架构实现服务的注册与发现配置管理负载均衡和熔断降级\u000a5. 引入Redis进行缓存优化提高系统响应速度和并发处理能力\u000a6. 编写详细的项目文档和API接口文档为前端开发团队和其他后端开发人员提供开发依据\u000a该平台基于 Java 技术栈开发旨在打造一站式招商服务平台涵盖项目管理企业信息管理招商流程跟踪数据分析等功能模\u000a块\u000a实现招商工作全流程数字化管理为招商决策提供数据支持提升招商工作的整体效能\u000a框架及技术栈：\u000a核心框架：Spring Boot\u000a微服务架构：Spring Cloud AlibabaNacosSentinelSeata\u000a持久层：MyBatis Plus\u000a安全认证：Spring Security\u000a\u000a\u000a\u000a\u000a\u000a\u000a一津通综合性在线交易与支付平台 后端开发\u000a2020.08-2021.10\u000aAPI文档：Swagger\u000a数据库：MySQL\u000a缓存：Redis\u000a前端框架: Vue\u000a状态管理：Vuex\u000aUI组件库：ElementUI\u000a个人职责：\u000a1. 依据既定的接口设计规范详细定义每个接口的功能请求参数响应数据格式错误码等信息\u000a2. 负责项目核心模块招商流程跟踪 与 数据分析的设计与开发在招商流程跟踪 模块中通过详细调研商业流程设\u000a计\u000a并实现了从项目对接洽谈签约到落地的全流程跟踪确保实时掌握项目进展情况在 数据分析 模块运用 Echarts 图标库\u000a实现数据可视化展示对招商数据进行深度挖掘与分析\u000a3. 针对系统在高并发场景下的性能问题进行了深入的性能调优工作通过对数据库查询语句的优化使用索引执行计划分析\u000a等手\u000a段有效提升了数据库查询效率对 Redis 缓存进行合理配置与优化提高缓存命中率减少数据库访问压力\u000a4. 搭建并优化项目的 CI/CD 流程引入 Jenkins工具实现自动化构建测试与部署实现代码提交后自动触发构建单元测试集\u000a成\u000a测试等流程确保代码质量根据不同环境的特点调整部署脚本确保部署过程的稳定性与可靠性\u000a该项目是一个综合性在线交易与支付平台旨在为用户提供一站式的购物支付及售后服务平台后端主要采用Java语言开发结\u000a合\u000aSpring框架MyBatisMySQL数据库等技术栈该平台能够处理复杂的交易逻辑管理订单流程并提供稳定的支付服务\u000a框架及技术栈：\u000a后端：采用 Spring Boot用于快速构建微服务应用\u000aSpring Cloud用于构建分布式系统\u000aMyBatis用于数据持久层操作\u000aRabbitMQZuulJWTJenkins\u000a前段：结合 HTMLCSSJavaScriptuni-app 以及前端框架 Vue.js 构建用户界面\u000a采用 Element UI 组件库进行页面快速开发\u000a通过 RESTful API 与后端进行数据交互\u000a数据库：选用 MySQL 作为关系型数据库\u000a利用 Redis 缓存非结构化数据\u000a个人职责：\u000a1. 需求分析与系统设计：参与项目的需求讨论理解业务需求为系统设计提供技术方案负责交易系统和订单系统的架构设计\u000a确\u000a保系统的高可用性可扩展性和安全性\u000a2. 核心模块开发：负责开发商品导购下单签约营销计价等核心交易模块开发逆向交易处理逻辑包括退款退货等功能的\u000a实\u000a现实现订单状态管理包括订单创建支付发货完成和逆向处理等流程\u000a3. 服务接口设计与实现：设计并实现RESTful API接口为前端提供数据交互接口与前端团队紧密合作确保API的可用性和性\u000a能满\u000a足前端需求\u000a4. 数据库设计与优化：设计数据库表结构编写SQL脚本优化数据库查询性能实现数据缓存策略减少数据库访问压力提高\u000a\u000a\u000a\u000a\u000a\u000a\u000a天津理工大学中环信息学院 本科 计算机科学与技术\u000a2016-2020\u000a系\u000a统响应速度\u000a教育经历'),8,7,'[{"questionIndex":1,"question":"在吉利智联车联网系统中，你负责设计车辆状态监控模块，用于实时处理发动机状态、电量等指标数据。请详细描述你如何利用Kafka和Redis构建高吞吐量的数据流处理架构，并分享遇到的最大性能瓶颈（如数据延迟或丢失）及其解决方案，最终如何量化优化效果（如QPS提升或延迟降低）？","type":"PROJECT","category":"项目深挖","userAnswer":"1","score":null,"feedback":null},{"questionIndex":2,"question":"你提到精通Java 8新特性，如Lambda表达式和Stream API。请解释在仁康医院项目中，你如何应用这些特性重构业务逻辑代码，具体解决了哪些开发效率或代码可读性问题，并对比重构前后的代码示例说明优化效果？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":"1","score":null,"feedback":null},{"questionIndex":3,"question":"在银河天津地区文旅系统中，你主导设计了基于Spring Cloud Alibaba的微服务架构。请详细说明你如何利用Nacos、Sentinel和Gateway组件实现服务的注册发现、熔断降级和负载均衡，并解释该架构如何支持景区信息管理模块的高并发访问（如节假日流量激增），同时确保系统稳定性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":"1","score":null,"feedback":null},{"questionIndex":4,"question":"你强调具备出色的责任心和对工作细节的把控。请分享一个在翠岗图书现代化图书平台项目中，因细节疏忽导致系统问题（如并发预约冲突）的经历，你如何通过日志分析或代码审查定位问题，并采取了哪些具体改进措施来预防类似问题？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":"1","score":null,"feedback":null},{"questionIndex":5,"question":"假设你正在开发一个新的车联网服务，需要实时分析驾驶行为数据并生成报告。请描述你会如何设计技术方案，包括数据采集、存储（如Elasticsearch vs. MySQL）、处理逻辑（如Spark或Flink），以及如何平衡实时性和准确性，并解释在简历中提到的“高并发场景处理经验”如何应用于此？","type":"SCENARIO","category":"情景模拟","userAnswer":"1","score":null,"feedback":null},{"questionIndex":6,"question":"在银河百汇招商平台项目中，你负责招商流程跟踪模块的开发。请详细说明你如何设计数据库表结构来支持从项目对接到落地的全流程跟踪，并解释在处理大量并发数据时，你如何通过Redis缓存和分布式锁（如RedLock）确保数据一致性和查询性能，最终实现了哪些量化指标（如查询响应时间缩短）？","type":"PROJECT","category":"项目深挖","userAnswer":"1","score":null,"feedback":null},{"questionIndex":7,"question":"你提到擅长数据库设计与优化，特别是在招商平台项目中优化了SQL查询。请具体说明你如何分析执行计划并设计索引策略（如复合索引或覆盖索引），解决了哪些查询性能问题（如慢查询），并对比优化前后的查询效率（如执行时间减少百分比）？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":"1","score":null,"feedback":null},{"questionIndex":8,"question":"在一津通综合性在线交易与支付平台中，你负责交易系统的架构设计。请描述你如何整合Spring Cloud、RabbitMQ和JWT构建分布式事务处理框架，确保订单状态管理（如创建、支付、退款）的最终一致性，并解释该架构如何应对高并发支付场景（如秒杀活动），同时保障数据安全？","type":"ARCHITECTURE","category":"架构设计","userAnswer":"1","score":null,"feedback":null}]','COMPLETED',NULL,NULL,'2026-02-02 03:18:25.729 +00:00','2026-02-02 03:19:56.704 +00:00',NULL);
INSERT INTO interview_sessions VALUES('1da9dfeb-fbb0-4448-a51c-9a21b41c24e6',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特雪花算法解决优惠券编码重复问题，并替换了原有的数据库比对方式。请详细描述这个问题的具体业务背景（如数据量达到百万时出现的性能瓶颈），你选择雪花算法而非其他唯一ID生成方案的原因，以及实施后对制券成功率和系统响应时间的量化提升。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在现代筑美HR软件的人员管理模块中，你使用了easyExcel实现文件导入导出功能。请分享一个具体的业务场景（如员工批量导入），并深入说明你在处理大数据量文件时遇到的性能或数据一致性挑战，以及如何通过技术优化（如分批处理或校验机制）解决的。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot和Spring Cloud实现微服务架构。请解释Spring Boot的自动配置原理如何简化开发，并结合你在初味道美食餐饮项目中的经验，说明你如何利用Spring Cloud的注册中心（如Eureka）实现服务治理，以及在高并发场景下如何处理服务发现和负载均衡。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在中国电信事务审批系统中，你负责审核工作流的设计。请描述你设计的多级审核流程架构（如基于角色和部门的权限控制），并解释如何处理审核节点动态变更（如审核人退回或销毁单子）的复杂业务逻辑，以及如何确保数据一致性和流程可追溯性。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"简历自我评价中提到你乐于与用户、同事和领导沟通需求。请分享一个你在项目中因需求理解偏差导致的问题案例，并详细说明你如何通过沟通技巧（如原型演示或会议协作）快速解决分歧，确保项目按时交付。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"假设你正在负责中国电信小程序智慧巡检系统的开发，用户反馈地图定位功能在蓝牙连接不稳定时出现延迟。请描述你会如何诊断问题（如检查网络或硬件因素），并设计一个容错方案（如本地缓存或重试机制）来提升用户体验。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"简历中提到你熟练使用MySQL和Redis。请比较两者在缓存场景下的适用性差异（如数据持久化和查询性能），并结合初味道美食餐饮项目中的高并发制券需求，说明你如何设计缓存策略（如Redis存储热点数据）来优化数据库压力。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在中国电信小程序智慧巡检项目中，你使用消息队列处理异常信息并配置2个消费者避免死循环。请解释你选择消息队列（如RabbitMQ或Kafka）而非直接处理的架构原因，并详细说明消费者配置的具体实现（如消息重试机制和错误隔离），如何确保系统在高负载下的稳定性。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null}]','CREATED',NULL,NULL,'2026-02-02 03:19:16.005 +00:00','2026-02-02 03:19:16.005 +00:00',NULL);
INSERT INTO interview_sessions VALUES('ed00cde7-9125-430e-9f3f-732331c4f695',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特雪花算法解决优惠券编码重复问题，并替换了原先的数据库比对方式。请详细描述这个技术选型的决策过程，包括为什么选择雪花算法而不是其他唯一ID生成方法，以及在高并发场景下如何确保算法的性能和唯一性？同时，请量化说明这个改进对制券失败率的具体影响。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"你熟练使用Spring Boot和Spring Cloud实现微服务架构。请解释Spring Cloud的核心组件（如Eureka、Feign）在服务治理中的作用，并结合你在项目中的实际经验，说明如何处理服务间的依赖管理和熔断机制，以避免级联故障。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在中国电信事务审批项目中，你负责审核工作流的设计和开发。请描述你设计的基于角色和部门的工作流架构，包括如何处理多岗位审核节点的权限控制，以及如何确保流程的灵活性和可扩展性？同时，请说明如何优化审核流程以减少人工干预。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"简历中提到你''乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题''。请分享一个你在项目中遇到跨团队沟通障碍的具体例子，例如需求变更或技术分歧，并详细说明你如何通过沟通技巧和协作方式化解冲突，最终推动项目进展。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"假设你接手一个遗留系统，该系统使用传统单体架构，性能瓶颈明显且维护困难。请描述你的重构步骤，包括技术选型（如微服务迁移）、风险评估（如数据一致性）、以及如何分阶段实施以最小化业务中断？结合你的简历经验，说明你会优先处理哪些模块。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在人力资源管理系统中，你使用easyExcel实现文件导入导出功能。请详细说明你如何处理大数据量（如百万级数据）的导入导出，包括分批处理、内存优化和错误处理机制？同时，请量化说明这个功能对考勤数据录入效率的提升效果。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"你熟悉Redis等非关系型数据库的使用。请解释Redis相比关系型数据库的优势，特别是在高并发场景下，并说明你在项目中如何利用Redis实现缓存策略（如缓存穿透、雪崩）？请结合一个具体例子，如优惠券系统的缓存设计。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在中国电信小程序智慧巡检项目中，你提到使用消息队列处理异常信息，并配置2个消费者避免死循环。请描述你选择消息队列（如RabbitMQ或Kafka）的原因，以及如何设计消费者机制来确保消息的可靠性和顺序性？同时，请说明如何监控和优化消息队列的性能瓶颈。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null}]','CREATED',NULL,NULL,'2026-02-02 03:19:42.963 +00:00','2026-02-02 03:19:42.963 +00:00',NULL);
INSERT INTO interview_sessions VALUES('2baecd28-41e1-4062-aa8f-6aa727abcb5d',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到解决了优惠券系统在高并发下的唯一性问题，包括从数据库比对改为雪花算法、引入线程池和批量制券。请详细描述这些技术选型的原因、具体实现过程，以及如何量化这些改进对制券失败率和性能的提升效果。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在现代筑美HR项目中，你负责人员管理和考勤管理模块，并使用了easyExcel实现文件导入导出、echarts进行图表分析。请解释这些技术如何解决大数据量下的性能瓶颈，以及在业务场景中如何优化用户体验？请结合具体代码或设计细节说明。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在中国电信事务审批项目中，你设计和开发了审核工作流，涉及角色权限控制、审核节点绑定和异常处理（如退回和销毁）。请详细描述工作流的核心架构设计，如何通过jQuery前端操作实现动态审核状态管理，以及如何确保流程的健壮性和可扩展性？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"简历中提到你熟练使用SpringBoot和SpringCloud实现微服务架构。请解释SpringBoot的核心特性（如自动配置、内嵌服务器）如何简化开发，以及在SpringCloud中如何实现服务注册与发现、负载均衡？请结合智慧屏或智慧巡检项目的具体例子说明。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"你熟悉Redis等非关系型数据库的使用。请详细说明Redis在缓存中的常见应用场景（如会话存储、热点数据缓存），以及你在项目中如何利用Redis优化查询性能？请结合智慧巡检或初味道项目的具体实现案例。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在圣斯龙服装ERP系统中，你应用了MVC设计模式，强调高内聚低耦合。请解释这种模式如何分离模型、视图和控制器，并举例说明在仓库管理模块中如何通过MyBatis集成实现数据操作？这种设计如何影响系统的可维护性和扩展性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"在项目后期运维中，你提到乐于与用户和同事沟通解决需求问题。请分享一个具体例子，说明你如何处理需求变更或冲突，以及你的沟通策略如何确保项目进度和团队协作？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设你在一个新项目中需要设计一个高并发的优惠券系统，类似于初味道美食项目但规模更大。请基于你的经验，详细描述你会如何选择技术栈（如SpringBoot、消息队列、数据库）和架构（如微服务、缓存策略），并解释关键设计决策（如唯一性保证、批量处理）如何应对潜在挑战？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED',NULL,NULL,'2026-02-02 03:19:47.161 +00:00','2026-02-02 03:19:47.161 +00:00',NULL);
INSERT INTO interview_sessions VALUES('6ccc4131-c83e-440b-9710-44bf4e09bdbc',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特的雪花算法解决优惠券编码重复问题，并替换了原先的数据库比对方式。请详细解释选择雪花算法的原因，以及在百万级数据量和高并发场景下，你是如何优化制券流程（如线程池改造、批量插入）来提升性能的？最终优化后的制券失败率降低了多少？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在现代筑美HR软件的考勤管理模块中，你负责使用easyExcel实现文件导入导出功能。请描述在处理大规模员工考勤数据时，遇到的最大技术挑战是什么（如内存溢出或性能瓶颈）？你是如何解决的？并量化说明该优化对数据处理效率的提升效果（如处理时间缩短百分比）。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot实现微服务架构。请解释Spring Boot的核心优势（如自动配置、嵌入式服务器），并结合中国电信事务审批项目，说明你是如何利用Spring Boot简化开发流程和提升部署效率的？举例一个具体功能实现。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"你熟悉Redis等非关系型数据库。在初味道美食餐饮项目中，Redis是如何被用于缓存或消息队列的？请详细说明你在项目中处理缓存穿透、缓存击穿或缓存雪崩的具体策略，以及这些策略如何保障高并发下的系统稳定性？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"简历中提到使用Spring Cloud实现微服务架构。请解释在微服务设计中，你是如何实现服务发现、负载均衡和容错的？结合中国电信小程序智慧屏项目，描述服务治理的具体实现（如注册中心使用），以及如何处理服务间依赖问题？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在项目后期运维中，你提到对同事进行需求讲解和进度把控。请分享一个你成功解决团队沟通障碍或需求变更冲突的经历，说明你如何确保项目按时交付？并举例说明你的沟通策略。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设你正在开发一个类似初味道美食餐饮的电商系统，在秒杀活动中预计有10万用户同时访问。请描述你的技术方案来处理高并发，包括但不限于限流、降级、缓存策略和数据库优化，确保系统不崩溃。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在中国电信智慧巡检项目中，你负责审核页面的操作和流程节点的审核人工作流绑定。请解释工作流引擎的选择依据（如Activiti或自定义），以及如何实现流程节点的动态绑定和异常处理（如退回或销毁操作）？量化说明该功能对巡检效率的提升。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null}]','CREATED',NULL,NULL,'2026-02-02 03:19:55.881 +00:00','2026-02-02 03:19:55.881 +00:00',NULL);
INSERT INTO interview_sessions VALUES('95ef0e80-86c3-458c-9ca5-c046978c4039',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,1,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到通过推特的雪花算法解决了优惠券编码重复问题，并舍弃了原先的数据库比对方法。请详细描述这个转变的技术细节：为什么数据库比对在百万级数据量下性能低下？雪花算法如何确保唯一性？以及你如何处理算法生成的ID与优惠券前缀/后缀的拼接逻辑？","type":"PROJECT","category":"项目深挖","userAnswer":"1","score":null,"feedback":null},{"questionIndex":2,"question":"简历中提到你使用Spring Boot和Spring Cloud实现微服务架构。请解释在初味道美食餐饮项目中，你如何利用Spring Cloud的注册中心（如Eureka或Nacos）进行服务治理？具体包括服务注册、发现、负载均衡的配置过程，以及如何处理服务间的通信（如Feign或RestTemplate）？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在初味道美食餐饮项目中，你为高并发场景引入了消息队列（如RabbitMQ或Kafka）并配置了2个消费者来处理异常信息。请描述这个架构设计的具体实现：消息队列如何与Spring Boot集成？消费者如何实现拒绝策略和重试机制？以及你如何确保消息不丢失和顺序性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在中国电信事务审批项目中，你负责审核工作流的设计和开发。请描述一个具体场景：当单子需要退回给起草人时，你如何通过jQuery前端操作和后端逻辑实现状态变更和权限控制？同时，你如何处理多级审批中角色与部门的绑定逻辑，确保审核人分配的准确性？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"简历中强调你具备独立解决问题的能力。请结合中国电信小程序智慧巡检项目，描述一个你遇到的最具挑战性的技术难题（如蓝牙连接或地图定位的实时性），你是如何分析问题根源、设计解决方案并最终量化的？例如，如何优化巡检数据统计的百分比计算逻辑？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在中国电信小程序智慧屏项目中，你使用jQuery和AJAX实现首页广告详情的动态数据绑定。请解释这个前后端交互架构的设计：如何通过AJAX调用接口获取数据？前端如何处理异步请求和错误？以及你如何优化用户体验，避免页面加载时的白屏或卡顿？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设你负责一个类似圣斯龙服装ERP系统的扩展项目，需要新增一个多渠道订单汇总模块。请描述你的架构设计思路：如何利用Spring MVC和MyBatis实现高内聚低耦合？数据库层面如何设计表结构以支持复杂业务逻辑（如定制订单和供应商分类）？以及你如何确保系统的可扩展性和性能？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在人力资源管理系统项目中，你使用EasyExcel实现文件导入导出功能。请深入讨论这个技术选型的原因：相比传统POI，EasyExcel在处理大文件时有哪些优势？你如何优化导入导出的性能（如内存管理和批处理）？以及你如何处理数据校验和异常情况，确保导入的准确性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null}]','IN_PROGRESS',NULL,NULL,'2026-02-02 03:19:59.610 +00:00','2026-02-02 04:10:33.249 +00:00',NULL);
INSERT INTO interview_sessions VALUES('d4da1414-a2c7-4f65-8391-d511fab22d79',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统中，你负责后端全部开发。请详细描述你在实现WebSocket进行消息推送时遇到的最难问题，以及你是如何解决的？最终量化的产出是什么？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在安心租房项目中，你实现了基于Redis的后台登录。请解释为什么选择Redis而不是传统的Session管理？在实现过程中遇到了哪些挑战，如何克服的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你有扎实的Java基础和良好的面向对象编程习惯。请解释面向对象编程中的封装、继承、多态，并结合你在项目中的一个例子说明如何应用这些原则来提高代码质量。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在多个项目中，你都使用了MySQL和分页技术（如PageHelper）。请详细说明PageHelper的工作原理，以及你在优化分页查询性能时采取的措施。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在松鼠智慧无人酒店系统中，系统分为三个应用模块：员工系统、自助机模块、小程序模块。请描述你设计的后端架构如何支持这些模块的集成和通信？为什么选择前后端分离技术？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在安心租房项目中，你实现了角色权限系统，使用数据库表和拦截器。请解释你设计这个权限系统的思路，以及如何确保系统的安全性和可扩展性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"简历中提到你''能承受一定的工作压力''。请分享一个你在项目中遇到的高压情况，你是如何应对的？结果如何？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设你在开发松鼠智慧无人酒店系统时，微信支付接口突然出现故障，导致用户无法完成支付。作为后端开发，你会如何快速定位问题并解决？请描述你的应急处理流程。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 03:32:10.946 +00:00','2026-02-02 03:32:10.946 +00:00',NULL);
INSERT INTO interview_sessions VALUES('e4dca783-b6ab-48f9-9276-01571f8fd4de',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[{"questionIndex":1,"question":"在松鼠智慧无人酒店系统中，你负责后端全部开发，并使用了WebSocket进行消息推送。请详细说明你选择WebSocket技术的原因，以及它解决了哪些具体的业务痛点？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在松鼠智慧无人酒店项目中，你提到实现了蓝牙开锁功能。请描述开发过程中遇到的最具挑战性的技术问题（例如蓝牙连接稳定性或安全性），以及你如何通过技术方案解决的？并量化该功能上线后的效果（如开锁成功率提升）。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在安心租房项目中，你实现了基于数据库表的角色权限系统。请详细说明你的设计思路，包括如何设计数据库表结构、编写拦截器进行请求拦截，以及如何确保不同角色（如管理员、房东）的权限隔离和数据安全？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"简历中提到你熟悉Redis，并在多个项目中应用（如安心租房的登录功能）。请解释Redis在项目中的具体应用场景（如缓存或会话管理），并说明相比传统方案（如MySQL），Redis带来了哪些性能或架构优势？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在多个项目中，你使用了MySQL数据库和PageHelper实现分页查询。请分享一个你在项目中优化MySQL查询性能的具体例子（例如索引设计或查询语句优化），并说明优化前后的性能对比（如响应时间减少）。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"松鼠智慧无人酒店系统采用前后端分离架构，分为员工系统、自助机模块和小程序模块。请描述你设计的整体架构方案，包括模块间的通信方式（如API接口或消息队列），以及如何处理高并发场景（如支付或开锁请求）？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"简历中提到你‘能承受一定的工作压力’和‘善于沟通’。请举例说明在项目开发中遇到紧急问题（如系统故障或需求变更）时，你如何与团队协作并快速解决？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设在松鼠智慧酒店系统中，用户反馈小程序开锁失败率突然上升。作为后端开发，你会如何系统性地诊断问题（如排查日志或监控指标），并采取哪些技术措施解决？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 03:33:30.707 +00:00','2026-02-02 03:33:30.707 +00:00',NULL);
INSERT INTO interview_sessions VALUES('2116e1d3-c08b-41a7-9d5b-5d6c3822280e',4,4,unistr('和模块化的代码库\u000a2全面掌握Java 8新特性如Lambda表达式Stream API和Optional类利用这些特性精简代码增强可读性并提升开\u000a发效率\u000a3精通Spring框架特别是Spring Boot擅长构建微服务架构深入理解Spring的依赖注入IoC和面向切面编程AO\u000aP以实现高度模块化和解耦的应用设计\u000a\u000a5深入理解RESTful API设计借助Spring MVC及注解如@RestController和@RequestMapping高效实现API接口确\u000a保清晰的RESTful服务设计\u000a\u000aSQL和PostgreSQL等关系型数据库\u000a7掌握微服务架构基础熟悉使用Spring Cloud及Spring Cloud Alibaba组件如FeignRibbonNacosGatewa\u000ay在分布式系统中构建可扩展的服务框架\u000a\u000a9精通Git掌握分支管理和代码合并策略利用Git Flow高效进行团队协作和代码审查\u000a10具备扎实的算法与数据结构知识能应用于解决实际问题如排序搜索和图算法以优化代码执行效率\u000a\u000ament UI框架\u000a\u000a13具备出色的技术文档撰写能力能编写清晰详细的API及设计文档确保团队成员易于理解和维护代码\u000a个人优势\u000a1.拥有四年的工作经验具备丰富的高并发场景处理经验\u000a\u000a3.工作态度积极主动执行任务时效率高能够承担较大的工作压力\u000a4.具备出色的责任心对工作细节把握准确力求在每个环节达到最佳效果\u000a5.善于思考与总结能够对工作中的关键知识进行有效沉淀并乐于与团队分享\u000a6.热衷于深入研究技术问题经常通过分析源码来提升自己的技术深度和广度\u000a7.利用业余时间不断学习新技术保持自我更新和技术领先\u000a8.具备良好的自我管理和时间管理能力能够有效规划工作与学习确保高效率完成任务\u000a专业技能\u000a赵旭\u000a男 | 25岁 \u000a652078684@aliyun.com\u000a5年工作经验 | 求职意向：Java | 期望薪资：10-11K | 期望城市：郑州\u000a\u000a\u000a\u000a\u000a\u000a\u000a天津银河百荣科技有限公司 Java\u000a2020.08-至今\u000a吉利智联车联网系统 后端开发\u000a2024.09-至今\u000a工作经历\u000a1精通 Java 语言熟练掌握 SpringSpring BootSpring Cloud 等主流框架能够独立搭建基于微服务架构的应用系统确\u000a保\u000a系统的高效稳定与可扩展性在过往项目中运用 Spring Cloud Alibaba 技术栈实现了服务的注册与发现配置管理负载均\u000a衡和\u000a熔断降级有效提升系统在高并发场景下的性能与可靠性\u000a2深入理解关系型数据库MySQLPostgreSQL和非关系型数据库 Redis的原理与应用擅长数据库设计与优化能够编写高效\u000a的\u000aSQL 查询语句通过索引优化查询重构等手段显著提升数据库查询性能在多个项目中成功解决因数据库性能瓶颈导致的系\u000a统响\u000a应缓慢问题\u000a3在银河天津地区文旅系统项目中担任核心开发人员基于 Spring Boot 框架快速搭建项目原型并逐步完善系统功能设计并\u000a实现\u000a了景区信息管理模块用户互动模块等核心功能包括数据库设计业务逻辑开发以及与前端的接口对接通过引入 Redis 进行\u000a缓存\u000a优化有效提高了系统响应速度和并发处理能力\u000a4接口开发与协作：设计和实现RESTful API与前端及移动端团队进行接口对接确保接口的准确性稳定性与高效性\u000a5团队协作与交流：积极参与团队会议分享开发经验与技术知识参与敏捷开发流程协调与其他团队的协作\u000a项目经历\u000a随着汽车行业的快速发展车联网技术已经成为提升车辆智能化优化驾驶体验的重要手段本平台旨在为汽车制造商车主和第\u000a三\u000a方服务提供商提供一个高效稳定可扩展的车联网服务解决方案\u000a框架及技术栈：\u000a1. 微服务框架：Spring Boot + Spring Cloud Alibaba\u000a2. 持久层：MyBatis\u000a3. 容器技术：Docker\u000a4. 分布式服务治理：Nacos\u000a5. 分布式配置管理：Nacos Config\u000a6. 消息队列： Apache Kafka+RabbitMQ\u000a7. API网关：Spring Cloud Gateway\u000a8. 分布式缓存：Redis\u000a9. 远程服务调用：OpenFeign\u000a10.前端：Vue\u000a11.前段网页构建技术：HTML/CSS/JavaScript\u000a12.图表展示：Highcharts\u000a13.指标收集与存储：Prometheus\u000a14.搜索引擎：Elasticsearch\u000a个人职责：\u000a1. 车辆状态监控模块：负责设计车辆状态监控模块该模块是平台的核心部分用于实时监控车辆的各项指标包括发动机状态\u000a电\u000a\u000a\u000a\u000a\u000a\u000a\u000a翠岗图书现代化图书平台 后端开发\u000a2024.04-2024.08\u000a仁康医院 后端开发\u000a2023.07-2024.03\u000a池电量油量行驶速度等\u000a2. 驾驶行为分析模块：主导开发驾驶行为分析模块该模块通过分析车辆的行驶数据识别驾驶员的驾驶习惯并提供改善建\u000a议\u000a3. 故障预警模块：负责构建故障预警模块该模块通过分析车辆的历史和实时数据预测潜在的故障并提前通知车主\u000a4. 高并发处理：设计并实现了基于Redis的高性能缓存策略通过消息队列RabbitMQ解耦服务间的依赖提升了系统在高并发场\u000a景\u000a下的处理能力\u000a5.\u000a率和\u000a系统稳定性\u000a 项目介绍\u000a随着数字化时代的到来图书馆和图书管理系统也面临着更新和优化的需求传统的图书管理方法往往效率低下且容易出错而现\u000a代化的图书管理系统能够通过信息技术的应用提升管理效率服务质量和用户体验本项目旨在开发一个全面的现代化图书管理系\u000a统以满足各种类型图书馆的需求包括学术机构公共图书馆和专业图书馆\u000a 个人职责\u000a1. 为确保更快的查询信息使用索引全文检索技术如Elasticsearch等提高检索速度和准确性使用事务处理和合适的锁机\u000a制以确保在多用户同时操作时数据的一致性和安全性\u000a2. 为了借阅的安全性与准确性设计安全的借还接口防止恶意操作和数据丢失设置逾期罚款计算与管理使用定时任务或后台\u000a服务检测逾期情况自动计算罚款并使用RabbitMQ通知用户并集成邮件或短信通知系统确保用户及时收到预约和到期提醒\u000a3.\u000a如OAuthJWT等保护用户隐私和系统安全并且定期备份用户数据以防止数据丢失或损坏记录管理员操作日志监控系\u000a统使用情况,确保权限控制的有效性\u000a4. 设计并发查询接口时,针对热点数据读多写少字典数据均使用Redis进行缓存,优化查询性能并针对性的设计过期时间以及\u000a一些常规的缓存问题进行处理\u000a5. 使用异步函数或者异步方法来执行可能阻塞的操作,例如文件读写网络请求等\u000a6. 为了防止多个用户对同一本书进行预约使用缓存和分布式锁来管理并发访问例如使用Redis等缓存系统配合分布式锁确\u000a保同一本书在同一时间只能被一个用户预约\u000a7. 解决在图书检索和借阅预约等功能的大量并发请求以及图书评论或者评分的并发请求成果与效益\u000a提升数据库设计和优化能力,深入了解设计适合大规模数据存储和高效查询的数据库结构\u000a深入理解和实践后端开发技术,包括业务逻辑的实现API 设计和安全性保障\u000a提高改善前端开发的技能,包括用户界面设计响应式布局和交互设计\u000a提升了对系统集成和测试方法的掌握,包括如何确保系统各模块之间的正常通信和数据流动\u000a 项目介绍\u000a这是一个信息化管理平台用于提高医疗服务的效率和质量,优化医院内部的运营管理,以及方便患者和医护人员之间的沟通和协\u000a作它可以涵盖从患者管理医疗资源调度医疗记录管理到财务管理等多个方面\u000a 个人职责\u000a1.\u000a同时确保患者的医疗信息不被未授权的人员访问篡改或泄露\u000a2. 患者管理模块：包括患者基本信息记录诊疗过程跟踪预约挂号管理门诊病历管理同时支持多种患者查询和分类方式\u000a3. 患者互动模块：开发移动端和网页端应用,实现患者与医院的多渠道沟通提供在线预约健康资讯推送远程问诊等服务,增强\u000a患者体验和医院服务的便捷性\u000a\u000a\u000a\u000a\u000a\u000a\u000a银河天津地区文旅系统 后端开发\u000a2022.10-2023.07\u000a银河百汇招商平台 后端开发\u000a2021.11-2022.10\u000a4. 医疗记录管理模块：使用MySQL存储统一的电子病历系统,使用分布式存储系统以支持大规模数据存储和访问,支持多种医疗数据\u000a格式的存储和互操作,确保医疗信息的完整性可靠性和安全性,同时使用es提供快速检索和分析功能\u000a5. 系统性能优化：使用负载均衡器Nginx分发用户请求,提高系统的响应速度和吞吐量利用Redis缓存技术存储频繁访问的数据,\u000a减少数据库查询压力\u000a6.解决在线预约挂号以及电子病历和医疗报告的高频率查看修改等高并发问题,以确保系统能够稳定高效地运行\u000a项目描述：\u000a银河天津地区文旅系统\u000aJAVA工程师\u000a随着旅游业的蓬勃发展以及数字化技术的普及传统文旅模式面临诸多挑战如游客体验缺乏个性化景区管理效率低等为了提\u000a升\u000a游客旅行体验优化景区运营管理我们启动了该文旅项目目标：构建一个集线上旅游服务预订景区智能导览大数据分析为\u000a一\u000a体的综合性智慧文旅平台实现游客与景区的高效互动助力文旅产业数字化升级\u000a框架及技术栈：\u000a核心框架：Spring Boot\u000a微服务架构：Spring Cloud AlibabaNacosSentinelSeata\u000a数据库：MySQL + MyBatis\u000a缓存：Redis\u000a消息队列：RabbitMQ\u000a安全认证：Spring Security\u000aAPI文档：Swagger\u000a容器化：Docker\u000a前端框架: Vue\u000a状态管理：Vuex\u000aUI组件库：ElementUI\u000a路由管理：Vue Router\u000a个人职责：\u000a1. 负责项目的整体技术架构设计确保系统的高效稳定和可扩展性\u000a2. 设计并实现景区信息管理模块包括景区详情门票信息活动发布等功能的数据库设计和业务逻辑开发\u000a3. 实现用户互动模块包括用户评论评分攻略分享等社交功能增强用户参与度和平台粘性\u000a4. 采用Spring Cloud Alibaba技术栈构建微服务架构实现服务的注册与发现配置管理负载均衡和熔断降级\u000a5. 引入Redis进行缓存优化提高系统响应速度和并发处理能力\u000a6. 编写详细的项目文档和API接口文档为前端开发团队和其他后端开发人员提供开发依据\u000a该平台基于 Java 技术栈开发旨在打造一站式招商服务平台涵盖项目管理企业信息管理招商流程跟踪数据分析等功能模\u000a块\u000a实现招商工作全流程数字化管理为招商决策提供数据支持提升招商工作的整体效能\u000a框架及技术栈：\u000a核心框架：Spring Boot\u000a微服务架构：Spring Cloud AlibabaNacosSentinelSeata\u000a持久层：MyBatis Plus\u000a安全认证：Spring Security\u000a\u000a\u000a\u000a\u000a\u000a\u000a一津通综合性在线交易与支付平台 后端开发\u000a2020.08-2021.10\u000aAPI文档：Swagger\u000a数据库：MySQL\u000a缓存：Redis\u000a前端框架: Vue\u000a状态管理：Vuex\u000aUI组件库：ElementUI\u000a个人职责：\u000a1. 依据既定的接口设计规范详细定义每个接口的功能请求参数响应数据格式错误码等信息\u000a2. 负责项目核心模块招商流程跟踪 与 数据分析的设计与开发在招商流程跟踪 模块中通过详细调研商业流程设\u000a计\u000a并实现了从项目对接洽谈签约到落地的全流程跟踪确保实时掌握项目进展情况在 数据分析 模块运用 Echarts 图标库\u000a实现数据可视化展示对招商数据进行深度挖掘与分析\u000a3. 针对系统在高并发场景下的性能问题进行了深入的性能调优工作通过对数据库查询语句的优化使用索引执行计划分析\u000a等手\u000a段有效提升了数据库查询效率对 Redis 缓存进行合理配置与优化提高缓存命中率减少数据库访问压力\u000a4. 搭建并优化项目的 CI/CD 流程引入 Jenkins工具实现自动化构建测试与部署实现代码提交后自动触发构建单元测试集\u000a成\u000a测试等流程确保代码质量根据不同环境的特点调整部署脚本确保部署过程的稳定性与可靠性\u000a该项目是一个综合性在线交易与支付平台旨在为用户提供一站式的购物支付及售后服务平台后端主要采用Java语言开发结\u000a合\u000aSpring框架MyBatisMySQL数据库等技术栈该平台能够处理复杂的交易逻辑管理订单流程并提供稳定的支付服务\u000a框架及技术栈：\u000a后端：采用 Spring Boot用于快速构建微服务应用\u000aSpring Cloud用于构建分布式系统\u000aMyBatis用于数据持久层操作\u000aRabbitMQZuulJWTJenkins\u000a前段：结合 HTMLCSSJavaScriptuni-app 以及前端框架 Vue.js 构建用户界面\u000a采用 Element UI 组件库进行页面快速开发\u000a通过 RESTful API 与后端进行数据交互\u000a数据库：选用 MySQL 作为关系型数据库\u000a利用 Redis 缓存非结构化数据\u000a个人职责：\u000a1. 需求分析与系统设计：参与项目的需求讨论理解业务需求为系统设计提供技术方案负责交易系统和订单系统的架构设计\u000a确\u000a保系统的高可用性可扩展性和安全性\u000a2. 核心模块开发：负责开发商品导购下单签约营销计价等核心交易模块开发逆向交易处理逻辑包括退款退货等功能的\u000a实\u000a现实现订单状态管理包括订单创建支付发货完成和逆向处理等流程\u000a3. 服务接口设计与实现：设计并实现RESTful API接口为前端提供数据交互接口与前端团队紧密合作确保API的可用性和性\u000a能满\u000a足前端需求\u000a4. 数据库设计与优化：设计数据库表结构编写SQL脚本优化数据库查询性能实现数据缓存策略减少数据库访问压力提高\u000a\u000a\u000a\u000a\u000a\u000a\u000a天津理工大学中环信息学院 本科 计算机科学与技术\u000a2016-2020\u000a系\u000a统响应速度\u000a教育经历'),8,0,'[]','PREPARING',NULL,NULL,'2026-02-02 04:08:15.161 +00:00','2026-02-02 04:08:15.161 +00:00','某公司');
INSERT INTO interview_sessions VALUES('ca76329a-c2f5-4c56-ac09-556cfe6ac0b9',5,5,unistr('联系方式\u000a微信号: 18660055008 \u000a邮箱: 6147199@qq.com \u000a求职信息\u000a工作时长：14年\u000a求职意向：项目经理/主管\u000a期望薪资：8-12K\u000a期望城市：烟台\u000a资格证书\u000a accp软件工程师\u000a osta软件开发\u000a 驾驶证C1\u000aHELLO\u000a刘良东 男 | 39岁\u000a个人优势\u000a近几年以来参与多个项目的研发与运营工作积攒了丰富的项目开发运营经验对SAA\u000aS类项目和电商类产品具有丰富的产品经验\u000a工作经历\u000a烟台贰伍叁网络科技有限公司 项目经理/主管2022.12-至今\u000a内容:\u000a工作期间\u000a1.主导并成功实施跨境电商ERP系统有效优化公司店铺的订单处理供应商管理国\u000a际物流协调及货款结算流程\u000a2.设计并推动跨境电商选品平台的构建涵盖买家端平台端供应商端国际物流及\u000a国际支付功能提升交易效率与用户体验\u000a3.负责进口商品购物平台的规划与实施整合店长平台海外买手等角色功能确保\u000a国际物流与支付流程的顺畅对接\u000a4.通过精细化项目管理确保各阶段任务按时完成质量达标同时处理项目过程中的\u000a突发问题保障项目顺利进行\u000a5.组织并领导跨部门协作通过有效沟通与资源整合提升项目执行效率实现业务目\u000a标与公司战略的紧密对接\u000a业绩:\u000a通过跨境电商ERP系统有效解决公司人员结构踢出重复工作的问题\u000a通过跨境选品平台结合了公司在境外的资源优势拓展公司业务\u000a山东享用宝信息技术有限公司 项目经理/主管2019.05-2022.12\u000a主要负责公司软件部门组建及聚合支付平台策划及设计再生资源平台电商APP新\u000a餐饮系统新零售系统驾驶员自助体检机设备远程管理及数据分析系统及驾校APP的\u000a策划需求文档撰写设计等工作\u000a山东珍生康业生物科技有限公司 国内电商运营2018.11-2019.04\u000a负责公司跨境电商的商城pc端web端微信端APP需求文档撰写主导设计界\u000a面带领项目部完成平台开发期间还负责海关申报国际国内物流合作等工作\u000a\u000a\u000a\u000a\u000a\u000a\u000a山东涅普顿健康产业有限公司 产品经理2016.03-2018.11\u000a负责公司多肽复合片鱼胶原蛋白肽粉鲍鱼多肽复合片等产品的OEM生产加工原\u000a料采购产品包装设计以及公司公众号商城淘宝拼多多等电商运营相关事宜\u000a烟台市加华电子商务有限公司 Java2014.02-2016.02\u000a内容:\u000a负责公司跨境电商网项目的网站设计APPPC端WEB 端的产品开发文档原型设\u000a计参与项目的研发工作国际物流与国内物流的对接等工作\u000a业绩:\u000a月销售10万加\u000a烟台海格尔网络科技有限公司 Java2012.03-2014.01\u000a期间参与设计开发外国人管理系统科目三考试系统HRERP等系统的开发\u000a项目经历\u000a驾驶员自助体检机数据分析系统 项目经理2021.03-2022.09\u000a内容:\u000a此项目为公司自营项目衍生项目目的为更好的管理公司在异地设备管理主要负责\u000a项目各部门协调及需求文档撰写,制定软件开发计划,协调项目成员工作项目采用PHP\u000a\u000a包含分润管理设备收入管理退款管理日月季年销售额管理设备模块\u000a包含设备管理设备故障率管理设备运行管理耗材模块包含出入库记录\u000a仓库管理耗材管理订单模块拍照订单体检订单退款订单合作方模块分\u000a润方管理采购商管理分公司模块部门管理员工管理岗位管理等模块\u000a业绩: 公司内部使用,目前共管理自助体检机200多台,日新增数据达到10W以上+\u000a业绩:\u000a期间平台远程管理300多台设备创建约600多万条交易数据\u000a再生资源平台 项目经理2022.01-2022.05\u000a此项目为公司外包项目项目目标为解决小微企业在再生资源回收行业无法提供商品\u000a来源问题通过与甲方沟通及现场实际调研发现小微企业再回收再生资源时基本\u000a不会开具发票根据这一现状通过资源整合直接与大型回收企业绑定通过人车\u000a货钱同步可溯源的形式规范市场做到政府有据可查有法可依使再生资源交易\u000a市场正规化合理化项目采用PHP语言ThinkPhp6+ swoole4+uniapp+MySQL框架\u000a开发在项目开发期间主要负责与客户沟通及现场调研对接需求根据客户要求撰写\u000a需求文档协调项目成员协作制定开发周期实时与客户保持沟\u000a通\u000a线下餐饮平台系统 项目经理2019.05-2022.01\u000a根据微信公众号以及微信收款商业的基础上研发适合线下餐饮店铺的点餐系统系统\u000a包含微信公众号卡包包模块支付及会员模块店铺外卖功能营销模块财务模\u000a\u000a\u000a\u000a\u000a\u000a\u000a块打印模块老板端APP小程序等140余项模块\u000a餐饮系统 项目经理/主管2020.06-2021.02\u000a此项目为公司外包项目项目目标为新形式下的餐饮店提供更好的管理软件使顾客\u000a成为店铺经营的参与者通过结合新媒体和外卖的形式达到快速盈利的目的项目采\u000a\u000a商业的基础上研发适合线下餐饮店铺的点餐系统系统包含商家基本信息模块菜品\u000a模块档口管理餐桌管理收银台模块员工管理订单管理预约管理排队管\u000a理拓客管理微信公众号卡包模块支付及会员模块店铺外卖功能营销模块\u000a财务模块打印模块老板端APP小程序等140余项模块\u000a聚合支付 项目经理/主管2019.06-2020.06\u000a此项目为公司自营项目通过集合微信刷脸支付和支付宝刷脸支付使商家免除同时\u000a放置两台刷脸设备避免浪费以及垄断项目采用JAVA语言spring boot+VUE+MySQL\u000a框架开发根据微信支付商业版和支付宝支付研发的集合平台主要面向于线下商铺\u000a的专业收款软件其中主要模块为店铺信息模块会员模块拓客模块打印模块\u000a商家线上商城模块营销模块引客模块店员提成模块刷脸支付模块等\u000a教育经历\u000a中央广播电视大学 大专 企业管理2011-2013\u000a学习企业管理'),8,0,'[{"questionIndex":1,"question":"在主导跨境电商ERP系统实施时，您选择的技术栈是PHP和MySQL，请详细说明为什么选择这个技术栈来解决订单处理、国际物流协调及货款结算流程中的具体挑战？它如何帮助优化公司人员结构并消除重复工作？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在聚合支付平台项目中，您使用Java Spring Boot和VUE框架集成微信刷脸支付和支付宝刷脸支付。请描述在开发过程中遇到的最核心技术挑战（如支付安全、接口兼容性或并发处理），以及您如何通过技术选型或架构设计来解决这些挑战，最终实现了什么量化效果（如设备减少率或支付效率提升）？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"再生资源平台采用ThinkPhp6 + swoole4 + uniapp + MySQL架构，您在设计时如何考虑高并发和实时数据处理（如人车货同步可溯源）的需求？请解释架构中的关键决策点，以及该设计如何支持平台在规范市场和政府合规方面的扩展性？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在组织跨部门协作以提升项目执行效率时（如跨境电商选品平台或进口商品购物平台），您如何处理不同部门（如供应商端、国际物流、支付）的利益冲突或沟通障碍？请结合一个具体项目实例，说明您的方法如何实现业务目标与公司战略的紧密对接？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"假设您在管理驾驶员自助体检机数据分析系统时，遇到一个关键模块（如设备故障率管理）因数据量激增（日新增数据10W+）导致系统性能瓶颈。作为项目经理，您会如何分析问题、协调资源并制定解决方案？请描述您的应急步骤和最终如何确保系统稳定运行？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在驾驶员自助体检机数据分析系统中，您提到管理200多台设备并创建了600多万条交易数据。请分享在项目开发过程中遇到的最难技术问题（如数据一致性或实时监控），您如何通过技术手段（如PHP或swoole优化）解决？最终量化的产出（如故障率降低或效率提升）是什么？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"在跨境电商选品平台构建中，您选择uniapp作为前端框架。请解释uniapp的技术特性如何解决买家端、供应商端和国际支付功能中的用户体验问题（如跨平台兼容性或响应速度），以及这个选型决策如何提升交易效率？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在项目过程中处理突发问题（如线下餐饮平台系统开发中的需求变更或资源短缺）时，您如何保持团队士气和项目进度？请结合一个具体项目实例，说明您的抗压策略和沟通方法如何确保任务按时完成且质量达标？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null}]','CREATED',NULL,NULL,'2026-02-02 04:11:59.223 +00:00','2026-02-02 04:12:38.273 +00:00','某公司');
INSERT INTO interview_sessions VALUES('462c105a-fb49-413f-a098-acbdbb558566',6,6,unistr('王丹麒\u000a 性别:男 手机:15098577313  微信：DanKy_WeChat  邮箱：danky.wang@foxMail.com\u000a1. 具备出色的适应能力,融入新业务领域并掌握核心知识 \u000a2. 熟悉软件开发流程,拥有在软件生命周期各个阶段的丰富经验 \u000a3. 优秀的表达与沟通能力,对跨部门沟通和协作有相当的经验 \u000a4. 自驱能力强,良好的结果导向和抗压能力,有带小团队经验\u000a5. 优秀的逻辑思维能力,在开发及运维过程中能够准确清晰定位并解决问题 \u000a1. 具有扎实的java编程基础和良好的编码习惯 \u000a2. 熟练掌握StrutsSpringSpring BootSpringMVCHibernateMyBatis框架并知晓其运行原\u000a理\u000a3. 具备微服务框架Spring CloudAliBaBa/Dubbo使用经验知晓其运行机制 \u000a4. 熟悉分布式系统的设计和应用熟悉分布式缓存消息队列等机制 \u000a5. 熟练掌握MySQL,Oracle等关系型数据库使用及底层原理具备系统数据库设计和规划能力,优化SQL语句 \u000a6. 熟悉Jquery,BootStrap,EasyUI,Element,Echarts等前端组件 \u000a7. 熟练使用版本控制系统git,svn;熟悉linux系统娴熟运用常用命令有shell,存储过程使用经验 \u000a本人主要负责生产可视化系统包含作业系统GIS管控平台数字库场 \u000a所用技术： \u000a后端：SpringCloudAlibaba+Nacos+OpenFegin+Gateway+WebScoket+MQTT \u000a数据库:Oralce+TDEngine+Redis \u000a消息中间件KafKa \u000a前端:Vue2+Element+HJavaScript+MineMap \u000a从零到一负责BPM系统业务流程需求的梳理确认流程的定义配置及调整; \u000a个人评价\u000a专业技能\u000a项目经历\u000a某港口数字化作业系统(2025.4-至今)\u000a蓝凌BPM业务流程系统(2022.02-2024.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a负责解决用户日常使用过程中出现的各类问题包括系统答疑bug记录工单处理及反馈信息等; \u000a负责BPM系统与用友NCC钉钉等业务系统对接联调 \u000a根据各业务部门要求拉取数据自定义流程表单查询模块\u000a开发安防信息管理系统设备保养与维修模块设备管理模块车辆管理模块等\u000aBPM系统与用友NCC补丁升级系统维护数据备份系统健康度检查 \u000a所用技术:Oracle+SQLServer+蓝凌BPM低代码平台+SSM \u000a1.开发地纬核三医保进销存接口(烟台地区和潍坊地区) 2.处理住院医生站护士站药品系统材料系统的问\u000a题\u000a\u000a合生活APP是珠江系地产旗下一款旨在把业主物业管理以及社区商业生活圈紧密联系起来提供多元化的社区\u000a服务全力打造1KM智能社区生活圈的移动应用主要功能有社区公告智能管家邻里交流商家特惠合支\u000a付物业缴费1KM智能社区生活圈等结算系统主要有订单拆分结算提现退款人员激励异常处理等\u000a功能本人主要负责迭代系统开发任务接收其他系统请求生成相对应的分润单结算单退款单激励单\u000a差异单等数据信息以及维护处理生产环境的各种问题\u000a所用技术:SpringCloudAliBaBa+Dubbo+Redis+RabbitMQ+MySQL+Linux \u000a对业务项下提交的相关纸质单据及客户交单申请书的扫描件进行影像自动识别进行准确单据分类后各类型单\u000a据逐项进行分析实现单据的影像内容直接转换为业务审核信息进而由系统根据审单规则实现自动匹配审单\u000a职责描述：对信用证以及各类贸易相关票据进行报文切分校验组报持久化\u000a所用技术：Python+Oracle \u000a中国银行票交所项目为企业客户上提供全流程的电子汇票服务包括：出票承兑收票转让背书贴现转\u000a贴现再贴现央行卖出商业汇票质押保证提示付款追索并在线进行纸质银行承兑汇票的出票申请以\u000a及查询出票的处理状态\u000a职责描述：\u000a开发中行票交所票据系统前置机接收人行票交所发送报文将报文信息经过处理后通知中行后台系统处理以\u000a及中行后台系统推送数据前置机组装报文后发送票交所\u000a所用技术:SpringMVC+Spring+MyBatis+IBMMQ+Oracle+Cobol \u000a医院信息化HIS系统2021.3-2022.2\u000a合生活APP结算系统(2020.7-2020.11)\u000a建行国结信用证智能审单项目(2019.04-2020.07)\u000a中国银行票据交易所项目(2018.07-2019.04)\u000a融创/万达中央预订系统(2017.9-2018.07)\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a中央预定系统是构建于主题娱乐总部层面的,主要以线上预定和散客预定为主的交易系统 \u000a包含后台管理系统,预订部,分销平台,官方预定通道四个子系统 \u000a\u000a维护团票雪票秀场以及乐视,招商银行的购票入口的接入招商一网通支付的接入等 \u000a所用技术:SpirngMVC+Spring+MyBatis+JSP+MySQL+Linux+Redis \u000a项目描述:北京神州泰岳大数据精准营销平台是智能数据公司的主要盈利产品每天对三亿移动互联网用户的\u000a上网行为进行沉淀分析公司现有房产金融股票P2P汽车新闻视频等多项主题数据也可通过数据\u000a定制对数据进行多维度的分析\u000a项目职责:对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品 \u000a所用技术：Apache POI +Hive \u000a中国移动营业厅信息平台是北京移动为了统一管理并且提升线下营业厅效率与服务水平的内部信息管理系统主\u000a要分为营业厅厅效管理营业厅生命周期管理卡资源号码申请管理等等模块\u000a本人主要负责营业厅业务行为洞察分析模块,营业厅销售统计报表,营业厅暗访路线管理,营业厅统一考核等模块. \u000a\u000aFCM财务管理系统是北京移动分公司为了提高公司财务工作效率与管理水平并适应新时代大环境背景下于07年立\u000a项开发的项目FCM系统主要包括报账系统,TD报账,铁通报账营收稽核资金平台账务稽核划小核算等子\u000a系统在项目中本人主要根据甲方客户邮件进行新需求的开发与原有项目的维护编写项目文档,解决各种\u000abug \u000a\u000a大数据精准营销平台(2017.1-2017.8)\u000a中国移动营业厅信息平台(2014.12-2016.12)\u000a中国移动北京分公司财务管理系统(FCM)2012.12-2014.11\u000a公司履历\u000a某软件公司(2025.4-至今)\u000a全栈工程师主要负责港口生产可视化(GIS)的开发\u000a格润富德农牧科技股份有限公司2022.2-2024.7\u000a程序员岗在企管部信息科负责参与公司IT信息化建设需求分析技术选型供应商管理\u000a山东中联佳裕软件股份有限公司 2021.3-2022.2\u000a后端工程师新医院产品部负责HIS系统相关模块开发\u000a软通动力信息技术集团股份有限公司2017.9-2020.11\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a开发组长与甲方共同分析需求明确需求分解分配工作任务指导初中级开发工程师主持内部会议\u000a北京神州泰岳智能数据有限公司2017.1-2017.8\u000a研发支撑对产品需求工单的数据进行提取以及后期数据的分类与更新再直接对接销售或者产品\u000a柯莱特信息科技(北京)有限责任公司2012.12-2016.12\u000a运维开发工程师驻场开发和整包项目开发\u000a教育背景\u000a山东青年政治学院 新闻采编与制作 2008.9-2011.7 \u000a鲁东大学 计算机科学与技术 2022.3-2024.7\u000a荣誉与证书\u000a山东青年政治学院计算机大赛二等奖 \u000aPMP(Project Management Professional)项目管理专业人士资格认证'),8,0,'[{"questionIndex":1,"question":"在港口生产可视化系统中，你提到使用了WebSocket和MQTT进行实时数据传输。请详细描述你设计这个实时通信机制的具体架构，包括技术选型原因（如为什么选择WebSocket而非HTTP长轮询），以及在实际部署中遇到的最大性能挑战是什么？你是如何量化问题并最终解决的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"你简历中强调熟悉Spring Cloud Alibaba的运行机制。请解释Nacos在微服务架构中的核心作用，特别是在服务发现和配置管理方面，你如何利用它来处理服务实例的动态扩缩容？并分享一个你基于Nacos解决配置冲突的实际案例。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"在港口项目中，你使用了TDEngine作为时序数据库来处理GIS数据。请描述你为什么选择TDEngine而非传统关系型数据库（如Oracle）来支持高并发地理空间查询？在架构设计上，你如何整合TDEngine与Redis和Kafka以实现数据流的高效处理？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"你提到有带小团队的经验，并负责指导初中级开发工程师。请分享一个具体例子，说明你如何分解任务、分配工作以及确保团队按时交付项目。在这个过程中，你如何处理技术分歧或进度延误？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"情景模拟：假设在港口生产可视化系统的生产环境中，突然出现大量用户报告GIS地图加载延迟超过5秒，系统日志显示MQTT消息队列积压。作为负责人，你会采取哪些步骤来快速定位问题（如从网络、服务、数据库层面分析），并描述你的应急处理流程和后续优化方案。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在蓝凌BPM业务流程系统中，你负责与用友NCC和钉钉的对接集成。请详细描述这个集成过程中的技术难点（如数据格式转换或API兼容性问题），以及你如何设计解决方案来确保数据一致性和系统稳定性？最终带来了哪些可量化的业务收益（如效率提升百分比）？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"你简历中提到优化SQL语句的经验。请分享一个你针对Oracle数据库查询优化的具体实例，包括原始查询的性能问题（如慢查询分析）、你采取的优化方法（如索引调整或查询重构），以及优化后的性能提升效果（如响应时间减少或吞吐量增加）。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"你强调优秀的跨部门沟通能力。请描述一个你与业务部门（如港口作业部门）合作解决复杂需求的例子，包括需求分析中的冲突点（如技术可行性vs业务紧急性），你如何通过沟通达成共识，并最终推动项目落地？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null}]','CREATED',NULL,NULL,'2026-02-02 04:12:03.628 +00:00','2026-02-02 04:12:55.956 +00:00','某公司');
INSERT INTO interview_sessions VALUES('0ce1895c-0df9-45cb-82e9-58e14f6a035c',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特的雪花算法解决优惠券编码重复问题，替代了原先的数据库全量比对方案。请详细描述你选择雪花算法而非其他唯一ID生成方案（如UUID或数据库自增ID）的核心原因，以及在实施过程中如何处理时钟回拨问题，并量化该方案对制券性能的提升效果。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在初味道美食餐饮项目的高并发制券场景中，你将异步线程改为线程池，并采用批量插入（每批次5000条）。请解释线程池相比直接创建线程在内存管理和响应速度上的优势，以及你如何配置线程池的核心参数（如核心线程数、队列容量）来平衡吞吐量和资源消耗？有没有遇到过线程池阻塞或任务堆积问题，如何解决的？","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot实现微服务架构。请解释Spring Boot的自动配置原理（如@EnableAutoConfiguration和条件注解），并举例说明你在项目中如何自定义一个Spring Boot Starter来封装通用业务逻辑（如优惠券服务），以及如何处理依赖冲突问题。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在项目中，你使用Redis作为非关系型数据库。请描述Redis在初味道美食餐饮或智慧巡检项目中的具体应用场景（如缓存或会话管理），并详细说明你如何实现Redis的缓存穿透、缓存击穿和缓存雪崩的防护机制？例如，使用布隆过滤器或互斥锁时，如何权衡性能和一致性？","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在Spring Cloud微服务架构中，你负责服务治理和消息队列集成。请描述你如何设计服务注册与发现（如Eureka或Nacos）和配置中心（如Spring Cloud Config），以及处理服务间通信（如Feign或OpenFeign）的容错机制？在遇到分布式事务问题时（如跨服务数据一致性），你采用了哪些策略（如消息队列最终一致性）？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"在初味道美食餐饮项目中，你导入消息队列处理异常信息，并配置2个消费者避免死循环。请解释你选择消息队列（如RabbitMQ或Kafka）的原因，以及如何设计消费者重试机制（如死信队列）来确保消息可靠投递？在消费者服务异常时，如何监控和优化消息处理延迟？","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"在项目四（中国电信事务审批）中，你负责需求讲解和进度把控。请分享一个你与用户或同事沟通解决复杂业务需求的例子（如工作流设计），并描述你如何确保团队理解需求？在需求变更频繁的情况下，你如何平衡开发效率和项目进度？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"假设在项目六（中国电信小程序智慧巡检）中，系统在高并发下出现巡检数据延迟问题，导致地图定位和设备信息展示卡顿。作为开发负责人，你会如何诊断问题（如分析数据库查询或网络瓶颈），并设计解决方案？请描述你的分析步骤和优化措施（如引入缓存或异步处理），以及如何量化改进效果？","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 04:16:16.029 +00:00','2026-02-02 04:16:51.093 +00:00','某公司');
INSERT INTO interview_sessions VALUES('000c8586-7312-43eb-9980-b90386c4f690',47,50,unistr('叶敏\u000a学历：大专籍贯：湖南岳阳\u000a年龄：28目前居住：湖南长沙\u000aE-mail：635155274@qq.com工作经验：5年\u000a电话：15802699919\u000a应聘岗位：java软件工程师\u000a教育经历\u000a湖南科技职业技术学院软件开发\u000a工作经历\u000a2021/6至今湖南松鼠智慧酒店管理有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统后端代码的全部实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3数据库构思与创建\u000a2019/62021/4承德易企网络科技有限公司工作岗位:java软件工程师\u000a主要职责：1完成软件系统代码的实现编写代码注释\u000a2分析并解决软件开发过程中的问题\u000a3配合项目经理完成相关任务目标\u000a专业技能\u000a有扎实的Java基础,熟悉面向对象编程,有良好的编程习惯\u000a\u000a熟练运用EclipseIDEA集成开发工具\u000a熟练使用Git/SVN进行版本的控制,Maven自动化构建工具\u000a熟悉Mysql等主流数据库,了解非关系型数据库Redis\u000a熟练Tomcat部署配置,了解Nginx\u000a熟悉jspservletjdbcjavabean等技术\u000a项目经验\u000a2021/6-至今\u000a项目1：松鼠智慧无人酒店系统\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a微信小程序微信支付微信卡券通通锁蓝牙连接开锁,elementui以及uniapp\u000a项目描述：\u000a该系统是为用户提供自助入住的新型酒店系统该系统运用了前后端分离技术该系统主要\u000a分为三个应用模块：员工系统模块客户自助机入住模块小程序模块\u000a责任描述：\u000a全程参与了需求分析demo设计数据库设计项目开发负责后端全部开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a员工系统模块：1.预定订房使用云支付以及现金,余额进行付款预定房间,入住查房以及退\u000a房功能,使用websocket进行消息推送以及企业微信机器人群消息通知以及云打\u000a印打印放单功能\u000a\u000a\u000a4.会员储值退款功能使用云支付以及现金充值以及退款\u000a5.优惠券使用与发放功能使用微信公众号卡券功能接口创建卡券投\u000a放卡券以及核销卡券等\u000a6.商品出库入库利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操\u000a作商品购买与退款功能使用云支付以及现金充值以及退款\u000a\u000a以及微信公众号创建会员卡以及微信卡包功能\u000a8.餐桌功能利用\u000aPageHelper\u000a和elementui实现分页以及数据的增删改查操作\u000a以及使用zxing包生成二维码点餐功能\u000a自助机模块：1.自助机预定订房入住以及续房支付功能使用云支付以及余额现金支付\u000a2.自助机api进行发房卡功能\u000a3.自助机使用百度AI身份识别进行身份证以及人脸对比功能\u000a4.身份证信息以及房间号录入公安系统功能\u000a小程序模块：1.预定订房会员充值优惠券购买商品购买礼包购买使用微信服务商\u000aJSAPI使用小程序下单支付以及退款申请\u000a2.小程序注册会员使用微信公众号创建会员卡以及微信卡包功能\u000a3.小程序房间开锁以及门禁开锁使用通通锁api进行开锁时间设置以及蓝\u000a牙开锁以及房间密码开锁\u000a4.小程序申请退房使用websocket进行退房消息通知以及企业微信机器人\u000a群消息通知\u000a5.使用云打印功能打印早餐券下午茶券停车票功能\u000a6.小程序展示房间号以及自己用户信息功能\u000a2020/8-2021/2\u000a项目2：安心租房\u000a>\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a>\u000a\u000a加密,第三方短信接口作验证\u000a,\u000a百度\u000aAI\u000a身份识别以及前端layui框架等\u000a项目描述：\u000a该系统是安心租房给用户提供了一个房屋短期出租和预订房屋的平台该系统运用了前\u000a后端分离技术后台主要由数据维护角色权限和数据统计系统提供支持,前台分为：用户模\u000a块,房客模块,房东模块,订单模块,支付等\u000a责任描述：\u000a全程参与了需求分析\u000ademo\u000a设计数据库设计项目开发负责后台数据维护和后台数据统\u000a计以及角色权限的开发：\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.后台登录：基于redis的后台登录\u000a2.\u000a后台数据维护：用户维护订单维护房屋类型维护城市维护管理员维护\u000a:\u000a利用\u000aPageHelper\u000a和\u000alayui\u000a实现分页以及数据的增删改查操作\u000a3.房屋维护：利用了ftp服务器对房东提交房屋进行对房屋的审核,查看房屋图片是否真实\u000a4.角色权限：用数据库表实现给不同的角色授权,显示不同的页面同时编写拦截器对数据请\u000a求进行拦截\u000a5.数据统计：例如每月用户的增长量折线图每月房屋新增量统计图等还可以选择时间精确\u000a控制数据范围百度Echarts的优雅展示图表支持PDF和Excel格式的导出和打印\u000a2020/3-2020/6\u000a项目3：客户关系管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a项目描述：\u000a客户关系管理系统是根据协同工作理念和\u000a\u000a以客户为中心\u000a\u000a思想的思想所设计的客户关系管理系\u000a统这个系统可以提升企业与客户在每个阶段的互动和控制能力将市场营销活动销售服务后\u000a台商务和客服支持构成精确的闭环控制系统提供协同的开放式的基于任意角色的和服务客户\u000a全生命周期的企业门户准确高效地帮助企业提高销售额提高获利能力满足客户员工和管\u000a理者的各方面需求\u000a责任描述：\u000a1.基于redis用户登录以及注册,使用MD5密码加密\u000a2.独立实现用户营销管理将所有用户进行展示,可以进行分页增删改查等操作\u000a3.独立实现客户管理,包括客户添加,删除,修改,查询等功能,对分页排序等功能进行优化\u000a2019/9-2019/11\u000a项目4：\u000a工地管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a\u000a方短信接口作验证等\u000a项目描述：\u000a本系统的研究和最终实现目标是一个能运用于处理一些一般性施工工程管理业务\u000a,\u000a能够在企\u000a业与施工方进行交流的自动化系统其基本功能包含：\u000a1.\u000a登录注册\u000a;2.\u000a前台展示施工队伍及相关内\u000a容3.后台用户管理4.施工队伍和成员管理5.施工内容管理6.项目管理\u000a主要角色：劳务人员施工方项目方系统管理员\u000a主要实现：本系统涉及多方角色为了其安全性和高可扩展性采用\u000aSpringboot,\u000a数据库采用\u000amysql\u000a\u000a同时使用了第三方短信接口作验证\u000a该系统采用前后端分离为了页面的美观以及提高开发效率采用\u000alayui\u000a作为框架模板\u000a责任描述\u000a后台：利用PageHelper对用户管理施工队伍和成员管理项目管理施工的内容进行分\u000a页查询以及施工内容的增删改\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a2019/6-2019/8\u000a项目5：任务管理系统\u000a开发工具：IDEA,Mysql,Tomcatwindows操作系统\u000a技术选型：\u000aspring,springmvc,mybatis,html5,ajax,xml,jquery等项目描述：\u000a主管员工管理员三种角色的人员管理一个任务的制定分配以及该任务的计划的实施\u000a指主导任务的结束的整个过程的管理\u000a责述：\u000a数据库表及序列的创建\u000a任务整个模块包括制定修改查看删除以及排序\u000a自我评价\u000a\u000a有很强的适应能力能快速适应新环境\u000a\u000a自信乐观善于思考喜欢钻研新事物和新技术\u000a\u000a工作认真负责有较强的协作能力能承受一定的工作压力\u000a\u000a乐于与同事以及领导沟通,以便快速解决项目遇到的问题能够快速的融入团队'),8,0,'[]','PREPARING','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 04:27:29.145 +00:00','2026-02-02 04:27:29.145 +00:00','某公司');
INSERT INTO interview_sessions VALUES('d0acad56-d7df-4b39-920a-71b0d8a70160',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[]','PREPARING','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 04:28:01.694 +00:00','2026-02-02 04:28:01.694 +00:00','某公司');
INSERT INTO interview_sessions VALUES('3f6d9690-420e-4b97-b985-cabb3fff5794',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用雪花算法解决了优惠券编码重复问题，并从数据库全量比对改为随机数模式。请详细描述这个重构过程的技术细节，包括如何实现雪花算法的集成、如何处理高并发场景下的线程安全问题，以及最终在制券失败率和性能提升上的量化数据。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在现代筑美HR软件中，你负责人员管理和考勤管理模块，并使用了easyExcel实现文件导入导出。请解释在处理大规模员工数据导入时，你如何优化easyExcel的内存管理和性能，以及如何处理数据校验异常的机制，并举例说明一个具体业务场景下的应用效果。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot和Spring Cloud实现微服务架构。请结合中国电信小程序智慧屏项目，详细说明你如何利用Spring Cloud的组件（如Eureka、Feign）实现服务注册、发现和调用，以及如何处理服务间的分布式事务问题。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在圣斯龙服装ERP系统中，你应用了MVC设计模式进行开发。请描述你如何分离模型、视图和控制器层，并解释这种模式如何提高代码的可维护性和扩展性。同时，请举例说明在仓库管理模块中，你如何通过MyBatis实现DAO层的重用。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在中国电信事务审批项目中，你负责工作流设计和开发。请详细说明你如何设计审批流程引擎，包括角色权限控制、审核节点绑定和状态管理机制，并解释如何处理审核退回和销毁场景下的数据一致性问题。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"假设你接手一个类似中国电信智慧巡检项目的高并发系统，需要实时处理蓝牙设备打卡和位置数据。请描述你会如何设计架构来确保低延迟和高可用性，包括消息队列的使用、缓存策略和数据库优化，并解释如何应对突发流量峰值。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"简历中提到你熟悉Redis的使用。请结合初味道美食餐饮项目，详细说明你如何利用Redis实现优惠券的缓存和分布式锁，以解决高并发下的库存超卖问题，并解释Redis的持久化策略如何影响系统可靠性。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在中国电信小程序智慧屏项目中，你负责成果上报流程和数据统计。请描述你如何与前端团队协作，使用jQuery和Ajax实现动态数据绑定，以及如何处理用户权限控制和数据展示的实时性问题，并举例说明一个沟通挑战的解决过程。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 04:30:08.389 +00:00','2026-02-02 04:30:56.985 +00:00','某公司');
INSERT INTO interview_sessions VALUES('9cb9be69-1d9e-4a8e-97c5-566617759d4b',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),3,0,'[{"questionIndex":0,"question":"请做一个简单的自我介绍。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null},{"questionIndex":1,"question":"你为什么应聘这个职位？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null},{"questionIndex":2,"question":"你认为自己最大的优势是什么？","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 04:59:17.641 +00:00','2026-02-02 05:01:07.099 +00:00','某公司');
INSERT INTO interview_sessions VALUES('f394fe6c-0e2e-4031-a91b-2c716da0915f',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特雪花算法解决优惠券编码重复问题，并替换了原先的数据库比对方式。请详细解释为什么选择雪花算法而不是其他方案（如UUID或数据库自增ID），以及实施后对系统性能的具体改进（如制券失败率降低多少、响应时间优化数据）。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在中国电信事务审批项目中，你负责审核工作流的设计和开发。请描述工作流的核心设计思路，包括如何处理多级审核（如角色中多个岗位的审核人分配）、权限控制机制，以及遇到的主要技术挑战（如编辑操作限制）和解决方案。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot和Spring Cloud实现微服务架构。请解释Spring Cloud的核心组件（如Eureka注册中心、Ribbon负载均衡、Feign声明式调用）在微服务中的作用，以及你在项目中如何配置它们以实现服务治理和调用。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在项目中，你使用Redis解决了哪些具体问题？例如，在初味道美食餐饮项目中，消息队列配置了Redis，请描述Redis在消息队列中的应用场景（如异常信息处理）、优势（如性能提升），以及如何配置消费者避免死循环。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"基于你的项目经验（如初味道美食餐饮和中国电信小程序智慧屏），请设计一个简单的微服务架构系统，包括前端、后端服务、数据库和缓存层，并解释技术选型理由（如为什么选择Spring Cloud而不是单体架构，以及Redis在缓存层的作用）。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"简历中提到你乐于与用户以及同事和领导沟通。请分享一个在中国电信事务审批项目中需要与多方沟通解决复杂问题的例子（如需求变更或权限冲突），以及你如何确保沟通效率和效果（如文档整理或进度把控）。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设你正在开发一个类似初味道美食餐饮的优惠券系统，在双十一大促期间，预计会有百万级并发请求。请描述你的技术方案来确保系统稳定性和性能，包括如何使用线程池、批量插入、消息队列和缓存来处理高并发场景。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在项目后期运维中（如中国电信小程序智慧巡检），你经常需要解决测试问题和添加需求。请描述一个高压环境下处理紧急任务的经历（如系统故障或需求上线），以及你如何管理时间和优先级（如任务分配或抗压策略）。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 05:06:41.873 +00:00','2026-02-02 05:07:45.529 +00:00','某公司');
INSERT INTO interview_sessions VALUES('dd972c29-38fe-46ed-a0b3-3161aca6d525',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[]','PREPARING','2026-02-03 05:13:43.741 +00:00',NULL,'2026-02-02 05:13:43.754 +00:00','2026-02-02 05:13:43.754 +00:00','某公司');
INSERT INTO interview_sessions VALUES('773745cd-4328-497e-a868-0d5a0839a737',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[]','PREPARING','2026-02-03 05:14:48.336 +00:00',NULL,'2026-02-02 05:14:48.341 +00:00','2026-02-02 05:14:48.341 +00:00','公司');
INSERT INTO interview_sessions VALUES('55351062-064b-43e5-84f4-3fbc7eb8729d',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[]','PREPARING','2026-02-03 05:15:38.404 +00:00',NULL,'2026-02-02 05:15:38.408 +00:00','2026-02-02 05:15:38.408 +00:00','公司');
INSERT INTO interview_sessions VALUES('3f190038-9427-430a-90a7-fcd9042dd322',3,3,unistr('[肖彦文]联系电话：1536437230\u000a年龄：25岁性别：男\u000a籍贯：湖南益阳学历：本科\u000a电子邮件：xiao5182021@163.com学校:西南科技大学\u000a工作性质：全职目标职能：JAVA软件开发工程师目标薪资：面议\u000a公司名称：成都虚谷伟业科技有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2020.4-2021.11\u000a工作描述：1.负责的详细设计功能开发单元测试代码优化工作\u000a2.遵循开发管理流程编写和完善设计文档\u000a3.后期项目的优化和维护\u000a公司名称：上海睿城软件有限公司\u000a职位名称：Java软件开发工程师\u000a工作时间：2021.11-2024.10\u000a工作描述：1.项目后期运维功能开发\u000a2.对接需求整理相关文档\u000a3.解决测试问题任务分配\u000a熟练使用SpringmvcSpringMyBatis等开源框架\u000a\u000a熟练使用springboot,能使用springboot,springCloud实现微服务架构\u000a熟练使用html5cssjqueryajax等前端技术\u000a熟练使用mysqlsqlserver了解oracle等关系型数据库的使用\u000a熟悉非关系型数据库redis等使用\u000a熟练使用IDEAMavenGit项目管理和项目构建工具\u000a熟练Linux操作系统的使用,熟悉常用命令,能够搭建各种单机以及集群开发环境\u000a项目一：初味道美食餐饮2021/1-2021/11\u000a项目描述：初味道美食小程序主要功能有在线预览商品详情在线客服咨询商品分类领劵中心商品浏览等功能能线上下单快递配送让\u000a\u000a注册中心实现服务治理\u000a技术描述：\u000a求职意向\u000a专业技能\u000a项目经历\u000a个人信息\u000a工作经历\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a1.主要实现优惠券促销活动首先创建活动然后创建券组采用预处理的方式提前进行制券在第一版本主要实现功能的基本业务\u000a然后在分支实现大数量和高并发问题\u000a2.解决优惠券编码重复问题原先采用的是获取数据库所有的券然后去比对是否重复如果库数据量达百万的时候就会出现非常缓慢\u000a而且会出现经常制券失败等所以此版本舍弃原先采用随机数的模式通过推特的雪花算法来避免唯一但是依然保留优惠券前缀和后缀\u000a3.由原来的异步采用线程修改为线程池以为高并发时候存在大量的线程占内存空间\u000a4.由原来制券采用for循环模式修改为批量制券而且采用分配插入优惠券一批次目前定为5000\u000a\u000a导入消息队列对于异常信息拒绝解决并重返消息队列中配置2个消费者以避免其中一个服务异常消息处理出现死循环\u000a项目责任:\u000a1.负责个人中心商品模块的编码\u000a2.个人中心主要包括我的收藏我的优惠卷\u000a3.负责项目的开发文档整理,项日后期的版木更新和维护工作\u000a项目二：人力资源管理系统(2020/5-2020/10)\u000a现代筑美HR软件:\u000a该项目是为碧桂园控股有限公司旗下的高新技术企业现代筑美家居打造的HR软件由于企业员工既有公司\u000a总部的2000多人又有分布于全国一二三线城市的2000多员外派员工所有考勤这一块的工作量非常大\u000a而对于外派员工考勤管理更是一个空白导致考勤排班工作量大数据不完整相关流程也是纸质流程相\u000a对落后为了有效改变此现状现代筑美开启了HR考勤项目的选型工作主要包括人事考勤薪资绩效\u000a招聘培训后勤门禁计件验厂管理等模块\u000a技能描述：\u000a\u000a\u000a3.使用easyExcel实现文件的导入导出\u000a4.使用echarts实现图表分析\u000a5.使用knife4j实现在线api文档及测试\u000a负责模块：\u000a负责前期分析业务模块划分数据库设计\u000a主要负责人员管理考勤管理的功能\u000a对系统进行了一些简单的代码重构优化如利用泛型技术对DAO层\u000a进行重构以提高代码重用度\u000a项目三：圣斯龙服装ERP系统2020/10-2021/3\u000a项目描述：\u000a该项目是为成都圣斯龙服饰有限公司量身打造的ERP系统解决了该公司在线定制客户多业务繁杂订单类\u000a别多和交货周期短等问题我们对供应商分类管理优化入库流程定制订单旗帜备注使得加工需求一目了\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a然多渠道订单汇总处理使效率直线上升如今的圣斯龙在经营管理上日渐完善从供应商管理到定制订\u000a单汇总备货的布料配饰采购再到定制生产成衣发给顾客构建成了一套完整的采购生产发货流程从根本\u000a上解决了圣斯龙的经营管理难题项目主要分为用户管理岗位管理角色管理计量单位收支(科目)项目\u000a采购管理零售管理商品管理报表管理部门管理菜单管理基础设置结算账户基本资料销售管\u000a理库存盘点仓库管理单据管理财务管理\u000a技能描述：\u000a1.以MVC设计模式为准模型视图控制器分离开发\u000a2.持久化层对orm框架(Mybatis)的配置并与spring集成\u000a3.Dao层定义数据操作接口主要负责对数据库的操作\u000a4.service层写对数据的处理以及业务逻辑实现\u000a5.controller(web)层写数据对前台的传递以及视图解析采取这样的方式进行开发是为了高内聚低耦\u000a合的开发思想\u000a\u000a项目责任：\u000a负责仓库管理库存管理单据管理的编码\u000a后期有对数据的运维工作简单的文档整理\u000a数据业务能力\u000a项目四：中国电信事务审批2021/11-2024/10\u000a\u000a项目描述:企业OA系统是把企业部门个人的信息录入系统公司的新闻通知公告等需要企业员工获知的信息都展现到系统当中让领导打\u000a\u000a对员工的一个管控和工作计划的合理化通过角色人员部门对权限控制的管控领导需要对该项目业务信息进行了解可以通过角色划分来\u000a进行审核权限查看改业务信息\u000a技术描述:\u000a\u000a权分域角色中是否存在多个岗位\u000a\u000a点的时候送该角色所在部门的领导作为审核人进行审核\u000a\u000a前单子进行编辑操作\u000a4.通过jquery前端的操作对该页面审核的时候会通过一些点击改变事件对页面的一些操作处理\u000a\u000a看当前单子所在审核状目前审核人领导显示单子审核不通过可以进行退回起草人或销毁\u000a项目责任:1.进行项目后期运维开发添加需求需求改进功能开发\u000a2.对整个项目的进度进行把控给同事进行需求讲解\u000a3,对审核工作流的的一个设计和开发\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a项目五：中国电信小程序智慧屏2022/2-2024/8\u000a开发环境：springCloud+jquery+jdk8+mysql\u000a项目描述:随申办智慧屏产品\u000a\u000a果进度分享来统计成员的一个情况可以对目前成果进行评论点赞查看多少人进行学习数据可以观看视频下载文档该学习智慧屏详情来进行\u000a了解情况\u000a技术描述:\u000a1.学习型组织提交学习申请时候会对该账号进行一个查询查看你是那个二级单位根据二级单位查询三级部门\u000a2.学习上报之后已办结的单子会进入成果分享页面展示会对该成果进行流程审批\u000a3.成果展示流程通过可以对该成果进行评论点赞通过jquery进行操作\u000a4.首页会有广告详情点击会通过ajax调用接口进行数据查询结果而绑定前端数据展示图片文案\u000a5.有图表统计该组织参加学习通过点亮的方式查看改信息情况\u000a6.首页会显示组织申报成果分享图表展示评论点赞信息\u000a项目责任:负责成果上报流程页面开发\u000a成果评论点赞数据统计\u000a组织流程统计数据展示\u000a后续维护运维\u000a项目六：中国电信小程序智慧巡检2023/7-2024/9\u000a开发环境：MySQL+jquery+springboot+ide+消息队列\u000a项目描述：该项目是对电信人员走访现场设备通过蓝牙来连接接口进行打卡检查设备安全隐患对巡检人员的一个系统化管理\u000a地图实施明确该巡检人员位置情况描述该设备的信息数据来统计下一次巡检时间该项目pc和移动端交互移动端发起巡检\u000a手机能实行监控\u000a技术描述:\u000a1.登录用户获取当前用户所在位置地图描述具体位置\u000a\u000a情\u000a3.首页会根据数据库查询的数据进行百分比判断百分率是多少分子除分母来进行显示百分率\u000a4.后台管理员能对数据进行操作权限控制\u000a5.通过session会话参数取到的该审核节点会进行判断来操作改设备是否合格不合格将退回发起人重新审核\u000a项目责任：负责审核页面的操作和流程节点的审核人工作流绑定\u000a后续测试问题运维开发\u000a1.能够查阅各种开发技术的中英文手册具有独立解决问题的能力有良好的开发习惯和设计思路能够尽快熟悉业务能快速\u000a自我评价\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a融入团队\u000a2.逻辑思维能力强思路清楚学习能力强对新技术有着强烈的好奇心还了解.NET的ADO技术和一些控件的使用\u000a3.有自制力做事有始有终对工作尽职尽责乐于从事有挑战性的工作\u000a4.乐于与用户以及同事和领导沟通以便快速解决项目遇到的问题\u000a5.做事勤勉服从领导命令'),8,0,'[{"questionIndex":1,"question":"在初味道美食餐饮项目中，你提到使用推特雪花算法解决优惠券编码重复问题，并替换了原有的数据库比对方式。请详细描述雪花算法的具体实现过程，包括如何处理前缀和后缀，以及在百万级数据量下如何确保唯一性和性能优化。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":2,"question":"在现代筑美HR系统中，你负责人员管理和考勤模块，并使用easyExcel实现文件导入导出。请分享你如何优化导入导出性能，例如处理大数据量时的分批策略、内存管理技巧，以及如何与echarts集成进行图表分析。","type":"PROJECT","category":"项目深挖","userAnswer":null,"score":null,"feedback":null},{"questionIndex":3,"question":"简历中提到你熟练使用Spring Boot和Spring Cloud实现微服务架构。请解释Spring Cloud的注册中心（如Eureka或Nacos）如何实现服务治理，包括服务注册、发现、健康检查机制，以及在中国电信事务审批项目中如何应用这些机制来管理审核工作流。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":4,"question":"在初味道美食项目中，你使用Redis处理高并发场景，并提到消息队列用于异常处理。请详细描述Redis如何缓存优惠券数据以减少数据库压力，以及消息队列（如RabbitMQ）的配置策略，包括消费者数量设置和死信队列处理机制。","type":"TECHNICAL_CORE","category":"核心技术栈","userAnswer":null,"score":null,"feedback":null},{"questionIndex":5,"question":"在中国电信事务审批项目中，你负责工作流审核的设计和开发。请描述你如何设计微服务架构下的工作流引擎，包括服务间通信方式（如REST或gRPC）、分布式事务处理（如Seata），以及如何通过角色和部门实现动态审核人分配。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null},{"questionIndex":6,"question":"简历中提到你乐于与用户、同事和领导沟通以解决项目问题。请分享一个具体例子，说明在需求变更或技术冲突时，你如何通过沟通协调确保项目进度，并举例说明你如何处理团队中的分歧。","type":"SOFT_SKILLS","category":"综合素质","userAnswer":null,"score":null,"feedback":null},{"questionIndex":7,"question":"假设在中国电信智慧巡检项目中，用户报告一个紧急bug：巡检数据在审核流程中出现不一致，导致设备状态错误。请描述你如何快速定位问题（如日志分析、复现步骤），并制定应急修复方案，同时如何与测试团队协作验证。","type":"SCENARIO","category":"情景模拟","userAnswer":null,"score":null,"feedback":null},{"questionIndex":8,"question":"在圣斯龙服装ERP系统中，你负责仓库管理模块，并采用MVC设计模式。请解释你如何设计该模块的分层架构（Controller、Service、DAO），确保高内聚低耦合，并举例说明如何使用MyBatis优化SQL查询以提高库存盘点效率。","type":"ARCHITECTURE","category":"架构设计","userAnswer":null,"score":null,"feedback":null}]','CREATED','2026-02-04 16:00:00.000 +00:00',NULL,'2026-02-02 05:21:09.751 +00:00','2026-02-02 05:23:12.474 +00:00','某公司');
